    --card-border: #EADCC9;
  }

  body {
    @apply bg-bg-cream text-primary-dark transition-colors duration-300;
    font-family: 'Nunito', Arial, sans-serif;
    -webkit-overflow-scrolling: touch;
    scroll-behavior: smooth;
    overflow-x: hidden;
  }

  .product-img-blend {
    mix-blend-mode: multiply;
  }
}

@layer utilities {
  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }

  .no-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }

  /* Global image styling for proper rendering */
  img {
    max-width: 100%;
    height: auto;
    display: block;
  }

  /* Product images specific styling */
  .product-img {
    width: 100%;
    height: 100%;
    object-fit: contain;
    object-position: center;
  }

  .product-img-cover {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
  }
}

/* --- Premium Night Sky Animations --- */
@keyframes twinkle-star {
  0%, 100% {
    opacity: 1;
    transform: scale(1);
    filter: drop-shadow(0 0 4px rgba(255, 255, 255, 0.8));
  }
  50% {
    opacity: 0.35;
    transform: scale(0.7);
    filter: drop-shadow(0 0 1px rgba(255, 255, 255, 0.2));
  }
}

@keyframes cloud-move-slow {
  0% {
    transform: translate3d(-10%, 0, 0);
  }
  50% {
    transform: translate3d(10%, 0, 0);
  }
  100% {
    transform: translate3d(-10%, 0, 0);
  }
}

@keyframes cloud-move-slower {
  0% {
    transform: translate3d(5%, 0, 0);
  }
  50% {
    transform: translate3d(-15%, 0, 0);
  }
  100% {
    transform: translate3d(5%, 0, 0);
  }
}

@keyframes soft-pulse-glow {
  0%, 100% {
    opacity: 0.6;
    transform: scale(1);
  }
  50% {
    opacity: 0.85;
    transform: scale(1.15);
  }
}

.animate-twinkle-s1 {
  animation: twinkle-star 2s infinite ease-in-out;
}
.animate-twinkle-s2 {
  animation: twinkle-star 3.5s infinite ease-in-out;
}
.animate-twinkle-s3 {
