}

.animate-cloud-slow {
  animation: cloud-move-slow 28s infinite ease-in-out;
}

.animate-cloud-slower {
  animation: cloud-move-slower 38s infinite ease-in-out;
}

.animate-glow-pulse {
  animation: soft-pulse-glow 5s infinite ease-in-out;
}

/* --- Splash Screen Animations --- */
@keyframes splash-zoom-video {
