import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { AlertTriangle, Trash2, CheckCircle2, ShieldAlert, X } from 'lucide-react';

/**
 * Reusable ConfirmDialog for destructive actions
 * Types: delete, approve, reject, block, suspend, logout, generic
 */
const PRESETS = {
  delete: {
    icon: Trash2,
    iconBg: 'bg-red-50',
    iconColor: 'text-red-500',
    confirmBg: 'bg-red-500 hover:bg-red-600 shadow-red-100',
    title: 'Delete Confirmation',
    message: 'This action cannot be undone. Are you sure you want to proceed?',
    confirmText: 'Delete',
  },
  approve: {
    icon: CheckCircle2,
    iconBg: 'bg-green-50',
    iconColor: 'text-green-500',
    confirmBg: 'bg-green-500 hover:bg-green-600 shadow-green-100',
    title: 'Approve Confirmation',
    message: 'Are you sure you want to approve this item?',
    confirmText: 'Approve',
  },
  reject: {
    icon: ShieldAlert,
    iconBg: 'bg-red-50',
    iconColor: 'text-red-500',
    confirmBg: 'bg-red-500 hover:bg-red-600 shadow-red-100',
    title: 'Reject Confirmation',
    message: 'Are you sure you want to reject this item?',
    confirmText: 'Reject',
  },
  block: {
    icon: ShieldAlert,
    iconBg: 'bg-red-50',
    iconColor: 'text-red-500',
    confirmBg: 'bg-red-500 hover:bg-red-600 shadow-red-100',
    title: 'Block Account',
    message: 'This will immediately block the account. Are you sure?',
    confirmText: 'Block',
  },
  suspend: {
    icon: AlertTriangle,
    iconBg: 'bg-amber-50',
    iconColor: 'text-amber-500',
    confirmBg: 'bg-amber-500 hover:bg-amber-600 shadow-amber-100',
    title: 'Suspend Account',
    message: 'This will temporarily suspend the account. The user will not be able to access the platform.',
    confirmText: 'Suspend',
  },
  generic: {
    icon: AlertTriangle,
    iconBg: 'bg-blue-50',
    iconColor: 'text-blue-500',
    confirmBg: 'bg-blue-500 hover:bg-blue-600 shadow-blue-100',
    title: 'Confirmation',
    message: 'Are you sure you want to proceed?',
    confirmText: 'Confirm',
  },
};

const ConfirmDialog = ({
  isOpen,
  onClose,
  onConfirm,
  type = 'generic',
  title,
  message,
  confirmText,
  loading = false,
}) => {
  const preset = PRESETS[type] || PRESETS.generic;
  const Icon = preset.icon;

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 bg-slate-900/50 backdrop-blur-sm"
            onClick={onClose}
          />
          <motion.div
            initial={{ opacity: 0, scale: 0.9, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9, y: 20 }}
            transition={{ type: 'spring', damping: 25, stiffness: 300 }}
            className="relative bg-white rounded-[28px] shadow-2xl w-full max-w-sm p-8 text-center"
          >
            <div className={`w-16 h-16 ${preset.iconBg} ${preset.iconColor} rounded-2xl flex items-center justify-center mx-auto mb-6`}>
              <Icon size={28} />
            </div>

            <h3 className="text-lg font-black text-slate-900 font-montserrat uppercase tracking-tight mb-2">
              {title || preset.title}
            </h3>
            <p className="text-sm text-slate-500 font-medium leading-relaxed mb-8">
              {message || preset.message}
            </p>

            <div className="flex gap-3">
              <button
                onClick={onClose}
                disabled={loading}
                className="flex-1 py-3.5 bg-slate-50 text-slate-500 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-100 transition-all disabled:opacity-50"
              >
                Cancel
              </button>
              <button
                onClick={onConfirm}
                disabled={loading}
                className={`flex-1 py-3.5 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-lg transition-all active:scale-95 disabled:opacity-50 ${preset.confirmBg}`}
              >
                {loading ? (
                  <span className="flex items-center justify-center gap-2">
                    <span className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                    Processing...
                  </span>
                ) : (
                  confirmText || preset.confirmText
                )}
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
};

export default ConfirmDialog;

import React, { useState, useMemo } from 'react';
import { Search, Filter, ArrowUpDown, ArrowUp, ArrowDown } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import Pagination from './Pagination';
import EmptyState from './EmptyState';
import SearchInput from '../../../../shared/components/SearchInput';

/**
 * Premium Reusable DataTable
 * Features: search, sort, sticky header, pagination, hover, responsive
 *
 * columns: [{ key, label, sortable, render }]
 * data: array of row objects
 */
const DataTable = ({
  columns = [],
  data = [],
  searchPlaceholder = 'Search...',
  searchKeys = [],
  onRowClick,
  emptyTitle,
  emptyDescription,
  emptyIcon,
  itemsPerPageDefault = 10,
  showSearch = true,
  showPagination = true,
  stickyHeader = true,
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [sortConfig, setSortConfig] = useState({ key: null, direction: 'asc' });
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(itemsPerPageDefault);

  // Filter by search
  const filteredData = useMemo(() => {
    if (!searchQuery || searchKeys.length === 0) return data;
    const q = searchQuery.toLowerCase();
    return data.filter((row) =>
      searchKeys.some((key) => {
        const value = row[key];
        return value && String(value).toLowerCase().includes(q);
      })
    );
  }, [data, searchQuery, searchKeys]);

  // Sort
  const sortedData = useMemo(() => {
    if (!sortConfig.key) return filteredData;
    return [...filteredData].sort((a, b) => {
      const aVal = a[sortConfig.key];
      const bVal = b[sortConfig.key];
      if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
  }, [filteredData, sortConfig]);

  // Paginate
  const totalPages = Math.ceil(sortedData.length / itemsPerPage);
  const paginatedData = showPagination
    ? sortedData.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage)
    : sortedData;

  const handleSort = (key) => {
    setSortConfig((prev) => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc',
    }));
  };

  const handlePageChange = (page) => {
    setCurrentPage(page);
  };

  const handleItemsPerPageChange = (count) => {
    setItemsPerPage(count);
    setCurrentPage(1);
  };

  // Reset page on search
  const handleSearch = (value) => {
    setSearchQuery(value);
    setCurrentPage(1);
  };

  const SortIcon = ({ columnKey }) => {
    if (sortConfig.key !== columnKey) return <ArrowUpDown size={12} className="opacity-30" />;
    return sortConfig.direction === 'asc' ? <ArrowUp size={12} /> : <ArrowDown size={12} />;
  };

  return (
    <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
      {/* Search Bar */}
      {showSearch && (
        <div className="p-6 border-b border-slate-50">
          <SearchInput
            type="text"
            placeholder={searchPlaceholder}
            value={searchQuery}
            onChange={(e) => handleSearch(e.target.value)}
            aria-label="Search table"
          />
        </div>
      )}

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full text-left" role="table">
          <thead className={stickyHeader ? 'sticky top-0 z-10' : ''}>
            <tr className="bg-slate-50/70 text-[10px] font-black text-slate-400 uppercase tracking-widest backdrop-blur-sm">
              {columns.map((col) => (
                <th
                  key={col.key}
                  className={`px-6 py-4 ${col.sortable ? 'cursor-pointer select-none hover:text-slate-900 transition-colors' : ''} ${col.align === 'right' ? 'text-right' : ''}`}
                  onClick={col.sortable ? () => handleSort(col.key) : undefined}
                  aria-sort={sortConfig.key === col.key ? (sortConfig.direction === 'asc' ? 'ascending' : 'descending') : undefined}
                >
                  <span className="flex items-center gap-1.5">
                    {col.label}
                    {col.sortable && <SortIcon columnKey={col.key} />}
                  </span>
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50 text-sm">
            <AnimatePresence>
              {paginatedData.length > 0 ? (
                paginatedData.map((row, i) => (
                  <motion.tr
                    key={row.id || i}
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    transition={{ delay: i * 0.03 }}
                    onClick={() => onRowClick?.(row)}
                    className={`group hover:bg-blue-50/30 transition-colors ${onRowClick ? 'cursor-pointer' : ''}`}
                  >
                    {columns.map((col) => (
                      <td key={col.key} className={`px-6 py-5 ${col.align === 'right' ? 'text-right' : ''}`}>
                        {col.render ? col.render(row[col.key], row) : row[col.key]}
                      </td>
                    ))}
                  </motion.tr>
                ))
              ) : (
                <tr>
                  <td colSpan={columns.length}>
                    <EmptyState
                      icon={emptyIcon}
                      title={emptyTitle || 'No results found'}
                      description={emptyDescription || 'Try adjusting your search or filters.'}
                    />
                  </td>
                </tr>
              )}
            </AnimatePresence>
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {showPagination && paginatedData.length > 0 && (
        <Pagination
          currentPage={currentPage}
          totalPages={totalPages}
          totalItems={sortedData.length}
          itemsPerPage={itemsPerPage}
          onPageChange={handlePageChange}
          onItemsPerPageChange={handleItemsPerPageChange}
        />
      )}
    </div>
  );
};

export default DataTable;

import React from 'react';
import { motion } from 'framer-motion';
import { Inbox } from 'lucide-react';

/**
 * Professional Empty State component
 */
const EmptyState = ({
  icon: Icon = Inbox,
  title = 'No data found',
  description = 'There are no items to display at this time.',
