          ]
        },
        {
          name: 'Delivery Partners',
          icon: <Truck size={18} />,
          subItems: [
            { name: 'All Partners', path: '/admin/delivery/all' },
            { name: 'Onboarding', path: '/admin/delivery/approval' },
          ]
        },
      ]
    },
    {
      title: 'CONTENT',
      items: [
        { name: 'Review Moderation', path: '/admin/content/reviews', icon: <MessageSquare size={18} /> },
        { name: 'Q&A Moderation', path: '/admin/content/qna', icon: <HelpCircle size={18} /> },
        { name: 'Legal & Policies', path: '/admin/content/legal', icon: <FileText size={18} /> },
      ]
    },
    {
      title: 'SUPPORT',
      items: [
        { name: 'Help Desk', path: '/admin/support/tickets', icon: <Inbox size={18} /> },
      ]
    },
    {
      title: 'CATALOG',
      items: [
        { name: 'Moderation', path: '/admin/products/moderation', icon: <Layers size={18} /> },
        { name: 'Categories', path: '/admin/categories', icon: <Briefcase size={18} /> },
      ]
    },
    {
      title: 'FINANCE',
      items: [
        { name: 'Earnings', path: '/admin/finance/earnings', icon: <DollarSign size={18} /> },
        { name: 'Payouts', path: '/admin/payouts', icon: <Banknote size={18} /> },
        { name: 'Commission Rules', path: '/admin/finance/rules', icon: <Percent size={18} /> },
        { name: 'Tax & GST Config', path: '/admin/finance/tax', icon: <ShieldCheck size={18} /> },
        { name: 'Delivery Charges', path: '/admin/finance/delivery-charges', icon: <Truck size={18} /> },
      ]
    },
    {
      title: 'SYSTEM',
      items: [
        { name: 'Sub-Admins', path: '/admin/system/sub-admins', icon: <ShieldCheck size={18} /> },
        { name: 'Role Management', path: '/admin/system/roles', icon: <Lock size={18} /> },
        { name: 'Audit Logs', path: '/admin/system/audit-logs', icon: <FileText size={18} /> },
        { name: 'Settings', path: '/admin/settings', icon: <Settings size={18} /> },
        { name: 'Logout', path: '/admin/auth', icon: <LogOut size={18} /> },
      ]
    }
  ];

  const getPageTitle = () => {
    const currentPath = location.pathname;
    for (const group of menuGroups) {
      for (const item of group.items) {
        if (item.path === currentPath) return item.name;
        if (item.subItems) {
          const sub = item.subItems.find(s => s.path === currentPath);
          if (sub) return sub.name;
        }
      }
    }
    return 'Admin Console';
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] flex text-slate-900 font-nunito">
      {/* Mobile Sidebar Overlay Backdrop */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-slate-950/40 backdrop-blur-sm z-40 lg:hidden transition-opacity"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside
        className={`bg-slate-950 border-r border-slate-900 flex flex-col fixed inset-y-0 left-0 z-50 w-72 transition-transform duration-300 ease-in-out lg:translate-x-0 ${
          isSidebarOpen ? 'translate-x-0' : '-translate-x-full'
        } shadow-[4px_0_24px_rgba(0,0,0,0.02)]`}
      >
        <div className="h-20 flex items-center px-6 gap-3">
          <Link to="/admin/dashboard" className="flex items-center gap-3 group">
            <img 
              src="/mthibg.png" 
              alt="Logo" 
              className="h-14 w-auto object-contain transition-transform duration-300 group-hover:scale-105" 
            />
          </Link>
        </div>

        <nav className="flex-1 py-2 px-3 space-y-6 overflow-y-auto no-scrollbar">
          {menuGroups.map((group, gIdx) => (
            <div key={gIdx} className="space-y-2">
              <h3 className="px-4 text-[9px] font-semibold text-slate-500 uppercase tracking-[2px]">
                {group.title}
              </h3>
              <div className="space-y-1.5">
                {group.items.map((item) => {
                  const hasSubItems = item.subItems && item.subItems.length > 0;
                  const isMenuOpen = !!openMenus[item.name];
                  const isActive = location.pathname === item.path ||
                    (hasSubItems && item.subItems.some(sub => location.pathname === sub.path));

                  if (hasSubItems) {
                    return (
                      <div key={item.name} className="space-y-1">
                        <button
                          onClick={() => toggleSubMenu(item.name)}
                          className={`w-full flex items-center justify-between px-4 py-2.5 rounded-xl transition-all ${isActive
                              ? 'bg-slate-900 text-white'
                              : 'text-slate-400 hover:bg-slate-900/50 hover:text-white'
                            }`}
                        >
                          <div className="flex items-center gap-3">
                            <span className={`flex-shrink-0 ${isActive ? 'text-white' : ''}`}>{item.icon}</span>
                            <span className="font-bold text-[13px] font-raleway">{item.name}</span>
                          </div>
                          <span className="opacity-40">{isMenuOpen ? <ChevronDown size={12} /> : <ChevronRight size={12} />}</span>
                        </button>

                        <AnimatePresence>
                          {isMenuOpen && (
                            <motion.div 
                              initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }}
                              className="ml-10 space-y-1.5 border-l-2 border-slate-800 pl-5 overflow-hidden"
                            >
                              {item.subItems.map((sub) => (
                                <Link
                                  key={sub.path}
                                  to={sub.path}
                                  onClick={() => setIsSidebarOpen(false)}
                                  className={`block py-2.5 text-[13px] font-bold transition-all ${location.pathname === sub.path
                                      ? 'text-white font-extrabold'
                                      : 'text-slate-500 hover:text-white'
                                    }`}
                                >
                                  {sub.name}
                                </Link>
                              ))}
                            </motion.div>
                          )}
                        </AnimatePresence>
                      </div>
                    );
                  }

                  return (
                    <Link
                      key={item.path}
                      to={item.path}
                      onClick={() => setIsSidebarOpen(false)}
                      className={`flex items-center gap-3 px-4 py-2.5 rounded-xl transition-all ${isActive
                          ? 'bg-slate-800 text-white shadow-none'
                          : 'text-slate-400 hover:bg-slate-900/50 hover:text-white'
                        }`}
                    >
                      <span className="flex-shrink-0">{item.icon}</span>
                      <span className="font-bold text-[13px] font-raleway">{item.name}</span>
                    </Link>
                  );
                })}
              </div>
            </div>
          ))}
        </nav>

        {/* Sidebar Footer */}
        <div className="p-6 border-t border-slate-900">
            <div 
              onClick={() => { navigate('/admin/settings'); setIsSidebarOpen(false); }}
              className={`p-4 bg-slate-900 rounded-2xl flex items-center gap-3 cursor-pointer hover:bg-slate-800 transition-all`}
            >
              <div className="w-8 h-8 rounded-full bg-white shadow-sm flex items-center justify-center font-bold text-xs text-slate-950 border border-slate-800">
                 A
              </div>
              <div>
                 <p className="text-[11px] font-bold text-slate-200 uppercase leading-none">System Admin</p>
                 <p className="text-[10px] text-green-500 font-bold mt-1 flex items-center gap-1">
                    <span className="w-1 h-1 bg-green-500 rounded-full animate-pulse" /> Live & Secure
                 </p>
              </div>
           </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 transition-all duration-500 ease-in-out lg:ml-72">
        {/* Topbar */}
        <header className="h-24 bg-white border-b border-slate-100 sticky top-0 z-40 px-4 sm:px-6 lg:px-10 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <button
              onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              className="w-10 h-10 border border-slate-100 flex items-center justify-center rounded-xl hover:bg-slate-50 transition-all shadow-sm active:scale-90 lg:hidden"
            >
              <Menu size={18} className="text-slate-900" />
            </button>

            <div className="hidden lg:block">
              <h2 className="text-xl font-semibold text-slate-900 uppercase tracking-tight font-montserrat">{getPageTitle()}</h2>
              <p className="text-[11px] text-slate-400 font-bold uppercase tracking-widest mt-1 font-raleway">
                Admin Management • Verified Session
              </p>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <div className="hidden md:block w-full max-w-[180px] sm:max-w-[260px] md:max-w-[320px] lg:w-96">
              <SearchInput
                type="text"
                value={searchQuery}
                onChange={(e) => {
                  setSearchQuery(e.target.value);
                  setShowSearchDropdown(e.target.value.length > 0);
                }}
                onFocus={() => searchQuery.length > 0 && setShowSearchDropdown(true)}
                onBlur={() => setTimeout(() => setShowSearchDropdown(false), 200)}
                placeholder="Search global records..."
              />

              {/* Search Dropdown */}
              <AnimatePresence>
                {showSearchDropdown && (
                  <motion.div 
                    initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 10 }}
                    className="absolute top-full left-0 right-0 mt-3 bg-white border border-slate-100 rounded-[24px] shadow-2xl overflow-hidden z-50 p-2"
                  >
                    <p className="px-4 py-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">Quick Navigation</p>
                    {filteredLinks.length > 0 ? filteredLinks.map(link => (
                      <button
                        key={link.path}
                        onClick={() => {
                          navigate(link.path);
                          setSearchQuery('');
                          setShowSearchDropdown(false);
                        }}
                        className="w-full flex items-center gap-3 px-4 py-3 hover:bg-slate-50 rounded-xl text-sm font-bold text-slate-700 transition-all text-left"
                      >
                        <div className="w-8 h-8 bg-slate-100 text-slate-600 rounded-lg flex items-center justify-center">
                          <Layers size={14} />
                        </div>
                        {link.name}
                      </button>
                    )) : (
                      <p className="px-4 py-6 text-sm text-slate-400 font-medium text-center">No matching records found.</p>
                    )}
                  </motion.div>
                )}
              </AnimatePresence>
            </div>

            <div className="flex items-center gap-3">
               <div className="relative">
                  <button 
                    onClick={() => setShowNotifications(!showNotifications)}
                    className={`w-12 h-12 border rounded-2xl flex items-center justify-center relative transition-all ${showNotifications ? 'bg-slate-950 text-white border-slate-950 shadow-lg' : 'bg-white border-slate-100 text-slate-400 hover:text-slate-900 shadow-sm'}`}
                  >
                     <Bell size={20} />
                     {!showNotifications && <div className="absolute top-3.5 right-3.5 w-2 h-2 bg-red-500 rounded-full border-2 border-white" />}
                  </button>

                  {/* Notifications Dropdown */}
                  <AnimatePresence>
                    {showNotifications && (
                      <motion.div 
                        initial={{ opacity: 0, scale: 0.95, y: 10 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={{ opacity: 0, scale: 0.95, y: 10 }}
                        className="absolute top-full right-0 mt-3 w-80 bg-white border border-slate-100 rounded-[28px] shadow-2xl z-50 overflow-hidden"
                      >
                        <div className="p-5 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
                           <h4 className="font-black text-[11px] uppercase tracking-widest text-slate-900">Notifications</h4>
                           <span className="bg-slate-100 text-slate-600 text-[9px] font-black px-2 py-0.5 rounded-full">3 New</span>
                        </div>
                        <div className="max-h-[400px] overflow-y-auto no-scrollbar">
                           {mockNotifications.map(n => (
                             <button key={n.id} className="w-full p-5 flex gap-4 hover:bg-slate-50 transition-all text-left border-b border-slate-50 last:border-0">
                                <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${n.type === 'warning' ? 'bg-amber-100 text-amber-600' : n.type === 'success' ? 'bg-green-100 text-green-600' : 'bg-slate-100 text-slate-600'}`}>
                                   {n.type === 'warning' ? <AlertCircle size={18} /> : n.type === 'success' ? <CheckCircle2 size={18} /> : <Bell size={18} />}
                                </div>
                                <div>
                                   <p className={`text-xs font-bold ${n.read ? 'text-slate-500' : 'text-slate-900'}`}>{n.title}</p>
                                   <p className="text-[10px] text-slate-400 font-medium mt-1 uppercase tracking-wider">{n.time}</p>
                                </div>
                             </button>
                           ))}
                        </div>
                        <button 
                          onClick={() => { navigate('/admin/comms/notifications'); setShowNotifications(false); }}
                          className="w-full py-4 bg-slate-50 text-[10px] font-black uppercase tracking-widest text-slate-900 hover:bg-slate-100 transition-all"
                        >
                           View All Notifications
                        </button>
                      </motion.div>
                    )}
                  </AnimatePresence>
               </div>
               <div 
                 onClick={() => navigate('/admin/settings')}
                 className={`w-12 h-12 bg-slate-950 rounded-2xl flex items-center justify-center text-white font-semibold text-lg shadow-xl cursor-pointer hover:scale-105 active:scale-95 transition-all`}
               >
                 A
               </div>
            </div>
          </div>
        </header>

        <main className="p-4 sm:p-6 lg:p-8 max-w-[1600px] mx-auto">
          <Outlet />
        </main>
      </div>
    </div>
  );
};

export default AdminLayout;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Lock, Mail, Eye, EyeOff, ShieldCheck, X } from 'lucide-react';
import { motion } from 'framer-motion';

const Auth = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleLogin = (e) => {
    e.preventDefault();
    if (!email || !password) {
      setError('Please fill in all fields');
      return;
    }
    
    // Check credentials: 9111966732 / 123456
    if (email === '9111966732' && password === '123456') {
      setError('');
      // Set admin auth flag
      localStorage.setItem('isAdminAuthenticated', 'true');
      // Mock login
      navigate('/admin/dashboard');
    } else {
      setError('Invalid username/phone or password');
    }
  };

  // Inline SVG pattern for background
  const backgroundPattern = `data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path d="M10 20c2-3 5-5 8-5s6 2 8 5-2 8-5 8-6-2-8-5zm30 20c2-3 5-5 8-5s6 2 8 5-2 8-5 8-6-2-8-5zM25 45c1-2 3-3 5-3s4 1 5 3-1 4-3 4-4-1-5-3zM45 15c1-2 3-3 5-3s4 1 5 3-1 4-3 4-4-1-5-3z" fill="%23ffffff" fill-opacity="0.12" fill-rule="evenodd"/></svg>`;

  return (
    <div 
      className="min-h-screen flex flex-col items-center justify-between p-4 md:p-6 bg-gradient-to-br from-[#77eba3] to-[#42c585] relative overflow-hidden"
      style={{ backgroundImage: `radial-gradient(circle at 20% 30%, #77eba3 0%, #42c585 100%), url('${backgroundPattern}')` }}
    >
      {/* Background organic elements */}
      <div className="absolute top-10 left-10 opacity-20 pointer-events-none">
        <svg width="100" height="100" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M50 0C35 25 15 35 0 50C15 65 35 75 50 100C65 75 85 65 100 50C85 35 65 25 50 0Z" fill="white" />
        </svg>
      </div>
      <div className="absolute bottom-20 right-10 opacity-15 pointer-events-none">
        <svg width="140" height="140" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M20 80C40 80 60 60 80 20C60 20 40 40 20 80Z" fill="white" />
          <circle cx="50" cy="50" r="10" fill="white" />
        </svg>
      </div>

      {/* Top Header Row */}
      <div className="w-full max-w-[420px] flex items-center justify-between z-10">
        <button 
          onClick={() => navigate('/')}
          className="bg-white/20 hover:bg-white/30 text-white p-2 rounded-full backdrop-blur-md active:scale-95 transition-all"
        >
          <X size={20} strokeWidth={2.5} />
        </button>
        <span className="text-white font-bold tracking-wider text-sm">ADMIN PANEL</span>
        <div className="w-9"></div>
      </div>

      {/* Main card */}
      <div className="w-full max-w-[420px] bg-[#f2fff5] rounded-[32px] px-6 py-8 shadow-2xl border border-white/40 z-10 my-6">
        <div className="text-center mb-8">
          <h2 className="text-3xl font-extrabold text-[#0a4a17]">
            Welcome back
          </h2>
          <p className="text-[#3b8a53] text-[13px] font-semibold mt-1">
            Verified Management Session
          </p>
        </div>

        <form onSubmit={handleLogin} className="space-y-5">
          {error && (
            <div className="bg-red-50 border border-red-100 text-red-500 text-[11px] font-bold p-3.5 rounded-2xl text-center uppercase tracking-wider">
              {error}
            </div>
          )}

          {/* Email / Username Field */}
          <div>
            <label className="block text-[12px] font-bold text-[#1f592c] mb-1.5 px-1 uppercase tracking-wider">
              Admin Username / Phone
            </label>
            <div className="relative">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-[#3b8a53]">
                <Mail size={18} />
              </span>
              <input
                type="text"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="e.g. 9111966732"
                className="w-full pl-11 pr-4 py-3 bg-[#e8fced] border-2 border-transparent focus:border-[#42c585] rounded-[16px] text-[14px] font-semibold text-[#0a4a17] placeholder-[#81b29a] focus:outline-none transition-all shadow-inner"
                required
              />
            </div>
          </div>

          {/* Password Field */}
          <div>
            <label className="block text-[12px] font-bold text-[#1f592c] mb-1.5 px-1 uppercase tracking-wider">
              Secure Password
            </label>
            <div className="relative">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-[#3b8a53]">
                <Lock size={18} />
              </span>
              <input
                type={showPassword ? 'text' : 'password'}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••••••"
                className="w-full pl-11 pr-11 py-3 bg-[#e8fced] border-2 border-transparent focus:border-[#42c585] rounded-[16px] text-[14px] font-semibold text-[#0a4a17] placeholder-[#81b29a] focus:outline-none transition-all shadow-inner"
                required
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-4 top-1/2 -translate-y-1/2 text-[#3b8a53] hover:text-[#0a4a17] transition-colors"
              >
                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
              </button>
            </div>
          </div>

          {/* Sign In Button */}
          <motion.button
            type="submit"
            whileTap={{ scale: 0.97 }}
            className="w-full py-4 bg-[#0c5c20] hover:bg-[#073f15] text-white rounded-[16px] text-[15px] font-bold uppercase tracking-wider shadow-lg hover:shadow-xl transition-all cursor-pointer"
          >
            Sign In to Dashboard
          </motion.button>
        </form>
      </div>

      {/* Footer Logo & Styling */}
      <div className="flex flex-col items-center gap-1 my-4 z-10">
        <img 
          src="/mthibg.png" 
          alt="Mithilakart" 
          className="h-10 w-auto object-contain"
        />
        <div className="flex items-center text-[18px] font-bold text-white tracking-wide italic">
          <span className="opacity-90">Mithila</span><span className="text-[#073f15]">kart</span>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState } from 'react';
import { FileText, Save, RotateCcw, AlertCircle, CheckCircle2, Edit3, XCircle } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const LegalPolicies = () => {
  const [activeTab, setActiveTab] = useState('privacy'); // 'privacy' or 'terms'
  const [isEditing, setIsEditing] = useState(false);
  
  const [privacyPolicy, setPrivacyPolicy] = useState(`Privacy Policy for Cocio

Last Updated: May 2026

At Cocio, we take your privacy seriously. This policy describes how we collect, use, and protect your personal data when you use our B2B marketplace.

1. DATA COLLECTION
We collect information that you provide when creating an account, such as your business name, email address, and contact details.

2. HOW WE USE DATA
We use your information to facilitate transactions, provide customer support, and improve our services.

3. DATA PROTECTION
We implement industry-standard security measures to ensure the safety of your personal information.`);

  const [termsConditions, setTermsConditions] = useState(`Terms & Conditions for Cocio

1. ACCEPTANCE OF TERMS
By accessing and using the Cocio platform, you agree to comply with these terms.

2. VENDOR OBLIGATIONS
Vendors must provide accurate product information and maintain professional standards of service.

3. PAYMENTS & COMMISSIONS
All transactions are subject to platform commissions as defined in the Finance section.`);

  const [isSaving, setIsSaving] = useState(false);
  const [showToast, setShowToast] = useState(false);

  const handleSave = () => {
    setIsSaving(true);
    // Mock API call
    setTimeout(() => {
      setIsSaving(false);
      setIsEditing(false);
      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    }, 1500);
  };

  const handleDiscard = () => {
    setIsEditing(false);
    // In a real app, you would reset the state to the original fetched data
  };

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-semibold text-slate-900 tracking-tight">Legal & Policies</h1>
          <p className="text-slate-500 text-sm mt-1">Manage your platform's Privacy Policy and Terms of Use</p>
        </div>
        <div className="flex items-center gap-3">
          {!isEditing ? (
            <button 
              onClick={() => setIsEditing(true)}
              className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-xl transition-all shadow-lg shadow-blue-100 text-sm font-semibold"
            >
              <Edit3 size={18} />
              <span>Edit Content</span>
            </button>
          ) : (
            <>
              <button 
                onClick={handleDiscard}
                className="flex items-center gap-2 px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-xl transition-all text-sm font-semibold"
              >
                <XCircle size={18} />
                <span>Discard</span>
              </button>
              <button 
                onClick={handleSave}
                disabled={isSaving}
                className="flex items-center gap-2 bg-green-600 hover:bg-green-700 text-white px-6 py-2.5 rounded-xl transition-all shadow-lg shadow-green-100 text-sm font-semibold disabled:opacity-50"
              >
                {isSaving ? (
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                ) : (
                  <Save size={18} />
