              )) : (
                <tr>
                  <td colSpan="6" className="px-6 py-20 text-center">
                    <div className="flex flex-col items-center gap-3 text-slate-300">
                      <UsersIcon size={48} className="opacity-20" />
                      <p className="text-sm font-bold uppercase tracking-widest">No customers found matching your search</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add Customer Slide-over */}
      <AnimatePresence>
        {isAddModalOpen && (
          <div className="fixed inset-0 z-[100] flex items-center justify-end p-4 bg-slate-900/40 backdrop-blur-sm">
            <motion.div 
              initial={{ x: '100%' }}
              animate={{ x: 0 }}
              exit={{ x: '100%' }}
              className="w-full max-w-lg bg-white h-full rounded-[32px] shadow-2xl p-10 flex flex-col"
            >
              <div className="flex justify-between items-center mb-10">
                <h2 className="text-2xl font-black text-slate-900 font-montserrat uppercase tracking-tight">Add New Customer</h2>
                <button 
                  onClick={() => setIsAddModalOpen(false)} 
                  className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-400 hover:text-slate-900 transition-all active:scale-90 shadow-sm"
                >
                  <XCircle size={24} />
                </button>
              </div>

              <div className="flex-1 space-y-8 overflow-y-auto no-scrollbar pb-10">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Full Name</label>
                  <input 
                    name="name"
                    value={formData.name}
                    onChange={handleInputChange}
                    type="text" 
                    placeholder="e.g. Rahul Sharma" 
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 px-6 text-sm font-black focus:ring-4 focus:ring-blue-50 outline-none transition-all" 
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Email Address</label>
                  <input 
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    type="email" 
                    placeholder="rahul@example.com" 
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 px-6 text-sm font-black focus:ring-4 focus:ring-blue-50 outline-none transition-all" 
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Phone Number</label>
                  <input 
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    type="tel" 
                    placeholder="+91 00000 00000" 
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 px-6 text-sm font-black focus:ring-4 focus:ring-blue-50 outline-none transition-all" 
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Initial Status</label>
                  <select 
                    name="status"
                    value={formData.status}
                    onChange={handleInputChange}
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 px-6 text-sm font-black focus:ring-4 focus:ring-blue-50 outline-none transition-all appearance-none"
                  >
                    <option value="Active">Active</option>
                    <option value="Inactive">Inactive</option>
                    <option value="VIP">VIP</option>
                  </select>
                </div>
                
                <div className="bg-blue-50 p-6 rounded-[24px] border border-blue-100 flex gap-4 items-start">
                   <div className="p-2 bg-white rounded-xl text-blue-500 shadow-sm">
                      <ShieldCheck size={20} />
                   </div>
                   <div>
                      <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Platform Sync</p>
                      <p className="text-[11px] text-blue-400 font-bold mt-1 leading-relaxed uppercase">Adding a customer will automatically trigger a welcome email and sync profile across all storefronts.</p>
                   </div>
                </div>
              </div>

              <div className="pt-8 border-t border-slate-50 flex gap-4">
                <button onClick={() => setIsAddModalOpen(false)} className="flex-1 py-4 bg-slate-50 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-100 transition-all">Cancel</button>
                <button 
                  onClick={handleSaveCustomer}
                  className="flex-1 py-4 bg-blue-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-blue-100 hover:scale-105 active:scale-95 transition-all flex items-center justify-center gap-2"
                >
                   <CheckCircle2 size={16} />
                   Save Customer
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Users;

import React from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import AdminLayout from '../layouts/AdminLayout';
import Auth from '../pages/Auth';
import Dashboard from '../pages/Dashboard';
import ProductModeration from '../products/ProductModeration';
import VendorList from '../vendors/VendorList';
import VendorApproval from '../vendors/VendorApproval';
import SellerDashboard from '../../vendor/dashboard/Dashboard';
import InventoryList from '../../vendor/inventory/InventoryList';
import CategoryManager from '../catalog/CategoryManager';
import BannerManager from '../catalog/BannerManager';
import CategoryChipsManager from '../catalog/CategoryChipsManager';
import HomeSectionsManager from '../catalog/HomeSectionsManager';

// New Admin Pages
import Analytics from '../pages/Analytics';
import StockAlerts from '../pages/inventory/StockAlerts';
import Orders from '../pages/Orders';
import AddProduct from '../pages/AddProduct';
import PlatformEarnings from '../pages/finance/PlatformEarnings';
import Payouts from '../pages/Payouts';
import Rules from '../pages/Rules';
import TaxConfig from '../pages/finance/TaxConfig';
import DeliveryCharges from '../pages/finance/DeliveryCharges';
import AllDeliveries from '../pages/delivery/AllDeliveries';
import DeliveryApproval from '../pages/delivery/DeliveryApproval';
import Settings from '../pages/Settings';
import Users from '../pages/Users';
import CustomerDetail from '../pages/users/CustomerDetail';
import SubAdmins from '../pages/system/SubAdmins';

// Promotions
import Coupons from '../pages/promotions/Coupons';
import FlashSale from '../pages/promotions/FlashSale';
import FeaturedProducts from '../pages/promotions/FeaturedProducts';

// Comms
import Notifications from '../pages/comms/Notifications';

// Content
import ReviewModeration from '../pages/content/ReviewModeration';
import QnAModeration from '../pages/content/QnAModeration';
import LegalPolicies from '../pages/content/LegalPolicies';

// Operations
import Returns from '../pages/operations/Returns';
import OrderDetail from '../pages/operations/OrderDetail';
import Refunds from '../pages/operations/Refunds';

// Support
import Tickets from '../pages/support/Tickets';

// Reports
import SalesReport from '../pages/reports/SalesReport';
import SellerReport from '../pages/reports/SellerReport';
import UserReport from '../pages/reports/UserReport';
import OrderReport from '../pages/reports/OrderReport';
import InventoryReport from '../pages/reports/InventoryReport';
import RefundReport from '../pages/reports/RefundReport';

// System
import AuditLogs from '../pages/system/AuditLogs';
import RoleManagement from '../pages/system/RoleManagement';

// Vendors
import SellerDetail from '../pages/vendors/SellerDetail';

const AdminProtectedRoute = () => {
  const isAdminAuthenticated = localStorage.getItem('isAdminAuthenticated') === 'true';
  if (!isAdminAuthenticated) {
    return <Navigate to="/admin/auth" replace />;
  }
  return <AdminLayout />;
};

const AdminRoutes = () => {
  return (
    <Routes>
      <Route path="auth" element={<Auth />} />

      <Route element={<AdminProtectedRoute />}>
        <Route path="dashboard" element={<Dashboard />} />
        <Route path="analytics" element={<Analytics />} />
        <Route path="users" element={<Users />} />
        <Route path="users/:userId" element={<CustomerDetail />} />
        
        {/* Storefront & Catalog */}
        <Route path="products/moderation" element={<ProductModeration />} />
        <Route path="categories" element={<CategoryManager />} />
        <Route path="storefront/banners" element={<BannerManager />} />
        <Route path="storefront/chips" element={<CategoryChipsManager />} />
        <Route path="storefront/sections/:section" element={<HomeSectionsManager />} />
        
        {/* Business Ops */}
        <Route path="inventory/all" element={<InventoryList />} />
        <Route path="inventory/add" element={<AddProduct />} />
        <Route path="inventory/alerts" element={<StockAlerts />} />
        <Route path="orders" element={<Orders />} />
        <Route path="orders/:orderId" element={<OrderDetail />} />

        {/* Operations */}
        <Route path="operations/returns" element={<Returns />} />
        <Route path="operations/refunds" element={<Refunds />} />

        {/* Support */}
        <Route path="support/tickets" element={<Tickets />} />

        {/* Promotions */}
        <Route path="promotions/coupons" element={<Coupons />} />
        <Route path="promotions/flash-sale" element={<FlashSale />} />
        <Route path="promotions/featured" element={<FeaturedProducts />} />

        {/* Comms */}
        <Route path="comms/notifications" element={<Notifications />} />

        {/* Content */}
        <Route path="content/reviews" element={<ReviewModeration />} />
        <Route path="content/qna" element={<QnAModeration />} />
        <Route path="content/legal" element={<LegalPolicies />} />
        
        {/* Partners */}
        <Route path="vendors/all" element={<VendorList />} />
        <Route path="vendors/:vendorId" element={<SellerDetail />} />
        <Route path="vendors/approval" element={<VendorApproval />} />
        <Route path="delivery/all" element={<AllDeliveries />} />
        <Route path="delivery/approval" element={<DeliveryApproval />} />
        
        {/* Finance */}
        <Route path="finance/earnings" element={<PlatformEarnings />} />
        <Route path="payouts" element={<Payouts />} />
        <Route path="finance/rules" element={<Rules />} />
        <Route path="finance/tax" element={<TaxConfig />} />
        <Route path="finance/delivery-charges" element={<DeliveryCharges />} />

        {/* Reports */}
        <Route path="reports/sales" element={<SalesReport />} />
        <Route path="reports/sellers" element={<SellerReport />} />
        <Route path="reports/users" element={<UserReport />} />
        <Route path="reports/orders" element={<OrderReport />} />
        <Route path="reports/inventory" element={<InventoryReport />} />
        <Route path="reports/refunds" element={<RefundReport />} />
        
        {/* System */}
        <Route path="system/sub-admins" element={<SubAdmins />} />
        <Route path="system/audit-logs" element={<AuditLogs />} />
        <Route path="system/roles" element={<RoleManagement />} />
        <Route path="settings" element={<Settings />} />
        
        <Route path="" element={<Navigate to="dashboard" replace />} />
      </Route>
    </Routes>
  );
};

export default AdminRoutes;

/**
 * Admin API Service Layer
 * ========================
 * Centralized API service with placeholder functions.
 * Replace base URL and endpoints when backend is ready.
 * All functions use async/await and return { data, error, loading } pattern.
 */

import axios from 'axios';

const API_BASE = '/api/v1/admin';

// Create axios instance with defaults
const api = axios.create({
  baseURL: API_BASE,
  timeout: 15000,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Request interceptor (attach auth token when backend is ready)
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('adminToken');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// Response interceptor
api.interceptors.response.use(
  (response) => response.data,
  (error) => {
    const message = error.response?.data?.message || 'Something went wrong';
    return Promise.reject({ message, status: error.response?.status });
  }
);

/**
 * Generic async handler wrapping API calls
 * Returns { data, error } for consistent handling
 */
const asyncHandler = async (apiCall) => {
  try {
    const data = await apiCall();
    return { data, error: null };
  } catch (error) {
    return { data: null, error: error.message || 'Request failed' };
  }
};

// ─── Auth ────────────────────────────────────────────────
export const authApi = {
  login: (credentials) => asyncHandler(() => api.post('/auth/login', credentials)),
  logout: () => asyncHandler(() => api.post('/auth/logout')),
  getProfile: () => asyncHandler(() => api.get('/auth/profile')),
  changePassword: (data) => asyncHandler(() => api.put('/auth/password', data)),
};

// ─── Dashboard ───────────────────────────────────────────
export const dashboardApi = {
  getStats: () => asyncHandler(() => api.get('/dashboard/stats')),
  getRevenueChart: (period) => asyncHandler(() => api.get(`/dashboard/revenue?period=${period}`)),
  getRecentOrders: () => asyncHandler(() => api.get('/dashboard/recent-orders')),
  getRecentActivities: () => asyncHandler(() => api.get('/dashboard/activities')),
};

// ─── Users ───────────────────────────────────────────────
export const usersApi = {
  getAll: (params) => asyncHandler(() => api.get('/users', { params })),
  getById: (id) => asyncHandler(() => api.get(`/users/${id}`)),
  create: (data) => asyncHandler(() => api.post('/users', data)),
  update: (id, data) => asyncHandler(() => api.put(`/users/${id}`, data)),
  block: (id) => asyncHandler(() => api.patch(`/users/${id}/block`)),
  unblock: (id) => asyncHandler(() => api.patch(`/users/${id}/unblock`)),
  suspend: (id) => asyncHandler(() => api.patch(`/users/${id}/suspend`)),
  delete: (id) => asyncHandler(() => api.delete(`/users/${id}`)),
  getOrders: (id) => asyncHandler(() => api.get(`/users/${id}/orders`)),
  getWallet: (id) => asyncHandler(() => api.get(`/users/${id}/wallet`)),
  export: (params) => asyncHandler(() => api.get('/users/export', { params, responseType: 'blob' })),
};

// ─── Sellers / Vendors ───────────────────────────────────
export const sellersApi = {
  getAll: (params) => asyncHandler(() => api.get('/sellers', { params })),
  getById: (id) => asyncHandler(() => api.get(`/sellers/${id}`)),
  approve: (id) => asyncHandler(() => api.patch(`/sellers/${id}/approve`)),
  reject: (id, reason) => asyncHandler(() => api.patch(`/sellers/${id}/reject`, { reason })),
  suspend: (id) => asyncHandler(() => api.patch(`/sellers/${id}/suspend`)),
