  packed: 'Packed',
  shipped: 'Shipped',
  delivered: 'Delivered',
  cancelled: 'Cancelled',
  returned: 'Returned',
  active: 'Active',
  inactive: 'Inactive',
  out_of_stock: 'Out of Stock',
  draft: 'Draft',
  approved: 'Approved',
  rejected: 'Rejected',
  paid: 'Paid',
  refunded: 'Refunded',
  failed: 'Failed',
  expired: 'Expired',
  completed: 'Completed',
  processing: 'Processing',
};

const StatusBadge = ({ status, size = 'md', className = '' }) => {
  const normalizedStatus = status?.toLowerCase()?.replace(/\s+/g, '_');
  const variant = statusColors[normalizedStatus] || 'neutral';
  const label = statusLabels[normalizedStatus] || status;

  return (
    <Badge variant={variant} size={size} dot className={className}>
      {label}
    </Badge>
  );
};

export default StatusBadge;

/**
 * MobileMenu Component
 * Slide-out drawer sidebar for mobile devices.
 */
import React from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Store, LayoutDashboard, Package, PlusCircle, Warehouse,
  ShoppingCart, RotateCcw, Users, Star, Ticket, Bell,
  BarChart3, Wallet, Settings, LogOut } from 'lucide-react';
import { useSellerAuth } from '../../context/SellerAuthContext';
import { SIDEBAR_MENU } from '../../constants';

const iconComponents = {
  LayoutDashboard, Package, PlusCircle, Warehouse, ShoppingCart,
  RotateCcw, Users, Star, Ticket, Bell, BarChart3, Wallet,
  Settings, LogOut, Store,
};

const MobileMenu = ({ isOpen, onClose }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const { seller, logout } = useSellerAuth();

  const handleLogout = async () => {
    await logout();
    navigate('/seller/login');
    onClose();
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          {/* Backdrop */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/40 backdrop-blur-sm z-50 lg:hidden"
          />

          {/* Drawer */}
          <motion.aside
            initial={{ x: '-100%' }}
            animate={{ x: 0 }}
            exit={{ x: '-100%' }}
            transition={{ type: 'spring', damping: 25, stiffness: 200 }}
            className="fixed inset-y-0 left-0 w-72 bg-slate-950 z-50 flex flex-col shadow-2xl lg:hidden border-r border-slate-900 text-slate-200"
          >
            {/* Header */}
            <div className="h-16 flex items-center justify-between px-5 border-b border-slate-900">
              <div className="flex items-center gap-3">
                <img 
                  src="/logomith-removebg-preview.png" 
                  alt="Mithilakart" 
                  className="h-10 w-auto object-contain"
                />
              </div>
              <button onClick={onClose} className="p-2 rounded-lg hover:bg-slate-900 transition-colors" aria-label="Close menu">
                <X size={20} className="text-slate-400" />
              </button>
            </div>

            {/* Navigation */}
            <nav className="flex-1 py-4 px-3 overflow-y-auto">
              {SIDEBAR_MENU.map((group, gIdx) => (
                <div key={gIdx} className={gIdx > 0 ? 'mt-5' : ''}>
                  <p className="px-3 mb-2 text-[10px] font-semibold text-slate-500 uppercase tracking-widest">
                    {group.group}
                  </p>
                  <div className="space-y-1">
                    {group.items.map((item) => {
                      const IconComponent = iconComponents[item.icon];
                      const active = location.pathname === item.path;

                      if (item.path === '#logout') {
                        return (
                          <button
                            key={item.name}
                            onClick={handleLogout}
                            className="w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium text-red-400 hover:bg-red-950/30 hover:text-red-500"
                          >
                            {IconComponent && <IconComponent size={20} />}
                            <span>{item.name}</span>
                          </button>
                        );
                      }

                      return (
                        <Link
                          key={item.path}
                          to={item.path}
                          onClick={onClose}
                          className={`
                            flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium transition-all
                            ${active
                              ? 'bg-slate-800 text-white border border-slate-700'
                              : 'text-slate-400 hover:bg-slate-900/60 hover:text-white'
                            }
                          `}
                        >
                          {IconComponent && <IconComponent size={20} className={active ? 'text-white' : 'text-slate-500'} />}
                          <span>{item.name}</span>
                        </Link>
                      );
                    })}
                  </div>
                </div>
              ))}
            </nav>

            {/* Footer */}
            <div className="border-t border-slate-900 p-4">
              <div className="flex items-center gap-3 p-3 bg-slate-900/60 rounded-xl">
                <div className="w-9 h-9 bg-slate-800 rounded-xl flex items-center justify-center">
                  <span className="text-sm font-bold text-white">{seller?.name?.charAt(0) || 'S'}</span>
                </div>
                <div>
                  <p className="text-xs font-semibold text-slate-200">{seller?.storeName || 'Seller Store'}</p>
                  <p className="text-[10px] text-slate-400">{seller?.email || 'seller@example.com'}</p>
                </div>
              </div>
            </div>
          </motion.aside>
        </>
      )}
    </AnimatePresence>
  );
};

export default MobileMenu;

/**
 * SellerLayout Component
 * Main layout wrapper with sidebar, topbar, and content area.
 * Completely independent — does NOT reuse AdminLayout.
 */
import React, { useState } from 'react';
import { Outlet } from 'react-router-dom';
import { AnimatePresence, motion } from 'framer-motion';
import Sidebar from './Sidebar';
import Topbar from './Topbar';
import MobileMenu from './MobileMenu';
import { useTheme } from '../../context/ThemeContext';
import '../../styles/seller.css';

const SellerLayout = () => {
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const { theme } = useTheme();

  return (
    <div className={`seller-module min-h-screen flex`}
         style={{ backgroundColor: 'var(--seller-bg)' }}>
      {/* Desktop Sidebar */}
      <Sidebar
        collapsed={sidebarCollapsed}
        onToggle={() => setSidebarCollapsed(!sidebarCollapsed)}
      />

      {/* Mobile Sidebar Drawer */}
      <MobileMenu
        isOpen={mobileMenuOpen}
        onClose={() => setMobileMenuOpen(false)}
      />

      {/* Main Content Area */}
      <div
        className={`flex-1 flex flex-col min-h-screen transition-all duration-300 ease-in-out ${
          sidebarCollapsed ? 'lg:ml-20' : 'lg:ml-[272px]'
        }`}
      >
        {/* Top Navbar */}
        <Topbar
          onMenuClick={() => setMobileMenuOpen(true)}
          sidebarCollapsed={sidebarCollapsed}
        />

        {/* Page Content */}
        <main className="flex-1 p-4 sm:p-6 lg:p-8 max-w-[1600px] w-full mx-auto">
          <AnimatePresence mode="wait">
            <motion.div
              key={location.pathname}
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -8 }}
              transition={{ duration: 0.2 }}
            >
              <Outlet />
            </motion.div>
          </AnimatePresence>
        </main>
      </div>
    </div>
  );
};

export default SellerLayout;

/**
 * Sidebar Component
 * Professional sidebar navigation for seller dashboard.
 */
import React from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  LayoutDashboard, Package, PlusCircle, Warehouse, ShoppingCart,
  RotateCcw, Users, Star, Ticket, Bell, BarChart3, Wallet,
  Settings, LogOut, ChevronLeft, ChevronRight, Store,
} from 'lucide-react';
import { useSellerAuth } from '../../context/SellerAuthContext';
import { SIDEBAR_MENU } from '../../constants';

const iconComponents = {
  LayoutDashboard, Package, PlusCircle, Warehouse, ShoppingCart,
  RotateCcw, Users, Star, Ticket, Bell, BarChart3, Wallet,
  Settings, LogOut, Store,
};

const Sidebar = ({ collapsed, onToggle }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const { seller, logout } = useSellerAuth();

  const handleLogout = async () => {
    await logout();
    navigate('/seller/login');
  };

  const isActive = (path) => location.pathname === path;

  return (
    <aside
      className={`
        fixed inset-y-0 left-0 z-40 hidden lg:flex flex-col
        bg-[var(--seller-sidebar-bg,#fff)] border-r border-[var(--seller-border-light,#F3F4F6)]
        transition-all duration-300 ease-in-out
        ${collapsed ? 'w-20' : 'w-[272px]'}
      `}
    >
      {/* Header / Logo Area */}
      <div className={`h-16 flex items-center border-b border-[var(--seller-border-light,#F3F4F6)] ${collapsed ? 'justify-center px-2' : 'px-6'}`}>
        {collapsed ? (
          <div className="w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center">
            <Store size={20} className="text-white" />
          </div>
        ) : (
          <Link to="/seller/dashboard" className="flex items-center gap-3 group">
            <img 
              src="/logomith-removebg-preview.png" 
              alt="Mithilakart" 
              className="h-10 w-auto object-contain transition-transform duration-300 group-hover:scale-105"
            />
          </Link>
        )}
      </div>

      {/* Navigation */}
      <nav className="flex-1 py-4 px-3 overflow-y-auto seller-no-scrollbar">
        {SIDEBAR_MENU.map((group, gIdx) => (
          <div key={gIdx} className={gIdx > 0 ? 'mt-6' : ''}>
            {/* Group Label */}
            {!collapsed && (
              <p className="px-3 mb-2 text-[10px] font-semibold text-slate-500 uppercase tracking-widest">
                {group.group}
              </p>
            )}

            <div className="space-y-1">
              {group.items.map((item) => {
                const IconComponent = iconComponents[item.icon];
                const active = isActive(item.path);

                // Logout special case
                if (item.path === '#logout') {
                  return (
                    <button
                      key={item.name}
                      onClick={handleLogout}
                      className={`
                        w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium
                        transition-all duration-200 group
                        text-red-400 hover:bg-red-950/30 hover:text-red-500
                        ${collapsed ? 'justify-center' : ''}
                      `}
                      title={collapsed ? item.name : undefined}
                    >
                      {IconComponent && <IconComponent size={20} className="flex-shrink-0" />}
                      {!collapsed && <span>{item.name}</span>}
                    </button>
                  );
                }

                return (
                  <Link
                    key={item.path}
                    to={item.path}
                    className={`
                      flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium
                      transition-all duration-200 group relative
                      ${collapsed ? 'justify-center' : ''}
                      ${active
                        ? 'bg-slate-800 text-white shadow-none border border-slate-700'
                        : 'text-slate-400 hover:bg-slate-900/60 hover:text-white'
                      }
                    `}
                    title={collapsed ? item.name : undefined}
                  >
                    {IconComponent && (
                      <IconComponent
                        size={20}
                        className={`flex-shrink-0 ${active ? 'text-white' : 'text-slate-500 group-hover:text-white'}`}
                      />
                    )}
                    {!collapsed && <span>{item.name}</span>}

                    {/* Tooltip for collapsed mode */}
                    {collapsed && (
                      <div className="absolute left-full ml-2 px-2.5 py-1.5 bg-gray-900 text-white text-xs font-medium rounded-lg
                                      opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity whitespace-nowrap z-50">
                        {item.name}
                      </div>
                    )}
                  </Link>
                );
              })}
            </div>
          </div>
        ))}
      </nav>

      {/* Sidebar Footer — Seller Info */}
      <div className={`border-t border-[var(--seller-border-light,#F3F4F6)] p-4 ${collapsed ? 'px-2' : ''}`}>
        {collapsed ? (
          <div className="w-10 h-10 mx-auto bg-slate-900 rounded-xl flex items-center justify-center">
            <span className="text-sm font-bold text-white">
              {seller?.name?.charAt(0) || 'S'}
            </span>
          </div>
        ) : (
          <div className="flex items-center gap-3 p-3 bg-slate-900/60 rounded-xl">
            <div className="w-9 h-9 bg-slate-800 rounded-xl flex items-center justify-center flex-shrink-0">
              <span className="text-sm font-bold text-white">
                {seller?.name?.charAt(0) || 'S'}
              </span>
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-xs font-semibold text-slate-200 truncate">
                {seller?.storeName || 'Seller Store'}
              </p>
              <p className="text-[10px] text-green-500 font-medium flex items-center gap-1">
                <span className="w-1.5 h-1.5 bg-green-500 rounded-full seller-pulse-dot" />
                Verified Seller
              </p>
            </div>
          </div>
        )}
      </div>

      {/* Collapse Toggle */}
      <button
        onClick={onToggle}
        className="absolute top-20 -right-3 w-6 h-6 bg-slate-900 border border-slate-800 rounded-full
                   flex items-center justify-center shadow-sm hover:shadow-md transition-all
                   hover:bg-slate-800 hover:border-slate-700 z-50"
        aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
      >
        {collapsed ? <ChevronRight size={14} className="text-slate-400" /> : <ChevronLeft size={14} className="text-slate-400" />}
      </button>
    </aside>
  );
};

export default Sidebar;

/**
 * Topbar Component
 * Top navigation bar with search, notifications, profile, and theme toggle.
 */
import React, { useState, useRef, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Menu, Search, Bell, Sun, Moon, ChevronRight,
  User, Settings, LogOut, X,
} from 'lucide-react';
import { useSellerAuth } from '../../context/SellerAuthContext';
import { useTheme } from '../../context/ThemeContext';
import { notifications as dummyNotifications } from '../../utils/dummyData';
import { getRelativeTime } from '../../utils/formatters';
import { SIDEBAR_MENU } from '../../constants';

const Topbar = ({ onMenuClick }) => {
  const { seller, logout } = useSellerAuth();
  const { theme, toggleTheme } = useTheme();
  const navigate = useNavigate();
  const location = useLocation();

  const [searchQuery, setSearchQuery] = useState('');
  const [showSearch, setShowSearch] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  const notifRef = useRef(null);
  const profileRef = useRef(null);

  const unreadCount = dummyNotifications.filter((n) => !n.read).length;

  // Close dropdowns on outside click
  useEffect(() => {
    const handler = (e) => {
      if (notifRef.current && !notifRef.current.contains(e.target)) setShowNotifications(false);
      if (profileRef.current && !profileRef.current.contains(e.target)) setShowProfile(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  // Build breadcrumb
  const getBreadcrumb = () => {
    const path = location.pathname.replace('/seller/', '').replace('/seller', '');
    if (!path || path === 'dashboard') return null;
    const parts = path.split('/').filter(Boolean);
    return parts.map((p) => p.charAt(0).toUpperCase() + p.slice(1).replace(/-/g, ' '));
  };

  // Get current page title
  const getPageTitle = () => {
    const path = location.pathname;
    for (const group of SIDEBAR_MENU) {
      for (const item of group.items) {
        if (item.path === path) return item.name;
      }
    }
    return 'Dashboard';
  };

  // Search navigation links
  const allLinks = SIDEBAR_MENU.flatMap((g) => g.items).filter((i) => i.path !== '#logout');
  const filteredLinks = searchQuery
    ? allLinks.filter((l) => l.name.toLowerCase().includes(searchQuery.toLowerCase()))
    : [];

  return (
    <header className="sticky top-0 z-30 h-16 bg-[var(--seller-topbar-bg,#fff)] border-b border-[var(--seller-border-light,#F3F4F6)] px-4 sm:px-6 lg:px-8 flex items-center justify-between gap-4">
      {/* Left: Menu + Title */}
      <div className="flex items-center gap-4">
        {/* Mobile Menu Toggle */}
        <button
          onClick={onMenuClick}
          className="lg:hidden p-2 rounded-xl hover:bg-gray-100 transition-colors"
          aria-label="Open menu"
        >
          <Menu size={20} className="text-gray-600" />
        </button>

        {/* Page Title + Breadcrumb */}
        <div className="hidden sm:block">
          <h2 className="text-base font-semibold text-[var(--seller-text,#111827)]">{getPageTitle()}</h2>
          {getBreadcrumb() && (
            <div className="flex items-center gap-1.5 text-[11px] text-[var(--seller-subtext,#6B7280)]">
              <span className="hover:text-blue-600 cursor-pointer" onClick={() => navigate('/seller/dashboard')}>Home</span>
              {getBreadcrumb().map((part, i) => (
                <React.Fragment key={i}>
                  <ChevronRight size={10} />
                  <span className={i === getBreadcrumb().length - 1 ? 'text-[var(--seller-text,#111827)] font-medium' : ''}>{part}</span>
                </React.Fragment>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Right: Search + Actions */}
      <div className="flex items-center gap-2 sm:gap-3">
        {/* Search */}
        <div className="relative hidden md:block">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => { setSearchQuery(e.target.value); setShowSearch(e.target.value.length > 0); }}
            onFocus={() => searchQuery.length > 0 && setShowSearch(true)}
            onBlur={() => setTimeout(() => setShowSearch(false), 200)}
            placeholder="Quick navigate..."
            className="w-52 lg:w-72 pl-9 pr-8 py-2 text-sm bg-[var(--seller-sidebar-hover,#F3F4F6)] border border-transparent
                       rounded-xl focus:ring-2 focus:ring-blue-100 focus:border-blue-200 focus:bg-white
                       outline-none transition-all placeholder:text-gray-400"
          />
          {searchQuery && (
            <button onClick={() => { setSearchQuery(''); setShowSearch(false); }} className="absolute right-2.5 top-1/2 -translate-y-1/2">
              <X size={14} className="text-gray-400" />
            </button>
          )}

          {/* Search Dropdown */}
          <AnimatePresence>
            {showSearch && (
              <motion.div
                initial={{ opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: 8 }}
                className="absolute top-full left-0 right-0 mt-2 bg-white border border-gray-200 rounded-xl shadow-lg z-50 overflow-hidden"
              >
                {filteredLinks.length > 0 ? filteredLinks.map((link) => (
                  <button
                    key={link.path}
                    onClick={() => { navigate(link.path); setSearchQuery(''); setShowSearch(false); }}
                    className="w-full flex items-center gap-3 px-4 py-3 text-sm text-gray-700 hover:bg-blue-50 transition-colors text-left"
                  >
                    <Search size={14} className="text-gray-400" />
                    {link.name}
                  </button>
                )) : (
                  <p className="px-4 py-6 text-sm text-gray-400 text-center">No results found</p>
                )}
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Theme Toggle */}
        <button
          onClick={toggleTheme}
          className="p-2.5 rounded-xl hover:bg-gray-100 transition-colors"
          aria-label={`Switch to ${theme === 'light' ? 'dark' : 'light'} mode`}
        >
          {theme === 'light' ? <Moon size={18} className="text-gray-500" /> : <Sun size={18} className="text-amber-400" />}
        </button>

        {/* Notifications */}
        <div className="relative" ref={notifRef}>
          <button
            onClick={() => { setShowNotifications(!showNotifications); setShowProfile(false); }}
            className={`relative p-2.5 rounded-xl transition-colors ${
              showNotifications ? 'bg-blue-50 text-blue-600' : 'hover:bg-gray-100 text-gray-500'
            }`}
            aria-label="Notifications"
          >
            <Bell size={18} />
            {unreadCount > 0 && (
              <span className="absolute -top-0.5 -right-0.5 w-5 h-5 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center border-2 border-white">
                {unreadCount > 9 ? '9+' : unreadCount}
              </span>
            )}
          </button>

          <AnimatePresence>
            {showNotifications && (
              <motion.div
                initial={{ opacity: 0, scale: 0.95, y: 8 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: 8 }}
                className="absolute right-0 top-full mt-2 w-80 bg-white border border-gray-200 rounded-2xl shadow-xl z-50 overflow-hidden"
              >
                <div className="flex items-center justify-between px-5 py-3.5 border-b border-gray-100">
                  <h4 className="text-sm font-semibold text-gray-900">Notifications</h4>
                  <span className="text-[10px] font-semibold text-blue-600 bg-blue-50 px-2 py-0.5 rounded-full">
                    {unreadCount} new
                  </span>
                </div>
                <div className="max-h-[360px] overflow-y-auto">
                  {dummyNotifications.slice(0, 5).map((n) => (
                    <div
                      key={n.id}
                      className={`px-5 py-3.5 border-b border-gray-50 last:border-0 hover:bg-gray-50 transition-colors cursor-pointer ${
                        !n.read ? 'bg-blue-50/30' : ''
                      }`}
                    >
                      <div className="flex items-start gap-3">
                        <div className={`w-2 h-2 mt-1.5 rounded-full flex-shrink-0 ${n.read ? 'bg-gray-200' : 'bg-blue-500'}`} />
                        <div>
                          <p className={`text-sm ${n.read ? 'text-gray-500' : 'text-gray-900 font-medium'}`}>{n.title}</p>
                          <p className="text-xs text-gray-400 mt-0.5 line-clamp-1">{n.message}</p>
                          <span className="text-[10px] text-gray-400 mt-1 block">{getRelativeTime(new Date(n.createdAt))}</span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
                <button
                  onClick={() => { navigate('/seller/notifications'); setShowNotifications(false); }}
                  className="w-full py-3 text-xs font-semibold text-blue-600 hover:bg-blue-50 transition-colors border-t border-gray-100"
                >
                  View All Notifications
                </button>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Profile Menu */}
        <div className="relative" ref={profileRef}>
          <button
            onClick={() => { setShowProfile(!showProfile); setShowNotifications(false); }}
            className="flex items-center gap-2.5 p-1.5 rounded-xl hover:bg-gray-100 transition-colors"
          >
            <div className="w-8 h-8 bg-gradient-to-br from-blue-600 to-indigo-600 rounded-xl flex items-center justify-center shadow-sm">
              <span className="text-white text-xs font-bold">
                {seller?.name?.charAt(0) || 'S'}
              </span>
            </div>
            <span className="hidden lg:block text-sm font-medium text-[var(--seller-text,#111827)]">
              {seller?.name?.split(' ')[0] || 'Seller'}
            </span>
          </button>

          <AnimatePresence>
            {showProfile && (
              <motion.div
                initial={{ opacity: 0, scale: 0.95, y: 8 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: 8 }}
                className="absolute right-0 top-full mt-2 w-56 bg-white border border-gray-200 rounded-xl shadow-xl z-50 overflow-hidden"
