/**
 * Seller Auth Context
 * Manages seller authentication state with dummy validation.
 * When backend is ready, replace loginSeller/logoutSeller with real API calls.
 */
import React, { createContext, useContext, useState, useCallback, useEffect } from 'react';
import { loginSeller as apiLogin, logoutSeller as apiLogout } from '../services/sellerApi';

const SellerAuthContext = createContext(null);

export const SellerAuthProvider = ({ children }) => {
  const [seller, setSeller] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  // Check for existing session on mount
  useEffect(() => {
    const token = localStorage.getItem('seller_token');
    const savedSeller = localStorage.getItem('seller_data');
    if (token && savedSeller) {
      try {
        setSeller(JSON.parse(savedSeller));
        setIsAuthenticated(true);
      } catch {
        localStorage.removeItem('seller_token');
        localStorage.removeItem('seller_data');
      }
    }
    setIsLoading(false);
  }, []);

  const login = useCallback(async (email, password) => {
    try {
      setIsLoading(true);
      const response = await apiLogin({ email, password });
      const { token, seller: sellerData } = response;

      localStorage.setItem('seller_token', token);
      localStorage.setItem('seller_data', JSON.stringify(sellerData));

      setSeller(sellerData);
      setIsAuthenticated(true);
      return { success: true };
    } catch (error) {
      return { success: false, message: error.message || 'Login failed' };
    } finally {
      setIsLoading(false);
    }
  }, []);

  const logout = useCallback(async () => {
    try {
      await apiLogout();
    } catch {
      // Proceed with local logout even if API fails
    }
    localStorage.removeItem('seller_token');
    localStorage.removeItem('seller_data');
    setSeller(null);
    setIsAuthenticated(false);
  }, []);

  const updateSellerData = useCallback((data) => {
    const updated = { ...seller, ...data };
    setSeller(updated);
    localStorage.setItem('seller_data', JSON.stringify(updated));
  }, [seller]);

  const value = {
    seller,
    isAuthenticated,
    isLoading,
    login,
    logout,
    updateSellerData,
  };

  return (
    <SellerAuthContext.Provider value={value}>
      {children}
    </SellerAuthContext.Provider>
  );
};

export const useSellerAuth = () => {
  const context = useContext(SellerAuthContext);
  if (!context) {
    throw new Error('useSellerAuth must be used within a SellerAuthProvider');
  }
  return context;
};

export default SellerAuthContext;

/**
 * Theme Context
 * Manages light/dark mode for the seller module.
 * Scoped to .seller-module wrapper — does not affect other modules.
 */
import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';

const ThemeContext = createContext(null);

export const ThemeProvider = ({ children }) => {
  const [theme, setTheme] = useState(() => {
    return localStorage.getItem('seller_theme') || 'light';
  });

  useEffect(() => {
    localStorage.setItem('seller_theme', theme);
    // Apply theme class to the seller module wrapper
    const root = document.documentElement;
    if (theme === 'dark') {
      root.classList.add('seller-dark');
    } else {
      root.classList.remove('seller-dark');
    }
    return () => root.classList.remove('seller-dark');
  }, [theme]);

  const toggleTheme = useCallback(() => {
    setTheme((prev) => (prev === 'light' ? 'dark' : 'light'));
  }, []);

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
};

export default ThemeContext;

/**
 * useDebounce Hook
 * Debounces a value by a specified delay.
 */
import { useState, useEffect } from 'react';

const useDebounce = (value, delay = 300) => {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => clearTimeout(timer);
  }, [value, delay]);

  return debouncedValue;
};

export default useDebounce;

/**
 * useMediaQuery Hook
 * Detect responsive breakpoints.
 */
import { useState, useEffect } from 'react';

const useMediaQuery = (query) => {
  const [matches, setMatches] = useState(() => {
    if (typeof window !== 'undefined') {
      return window.matchMedia(query).matches;
    }
    return false;
  });

  useEffect(() => {
    const mediaQuery = window.matchMedia(query);
    const handler = (e) => setMatches(e.matches);

    mediaQuery.addEventListener('change', handler);
    setMatches(mediaQuery.matches);

    return () => mediaQuery.removeEventListener('change', handler);
  }, [query]);

  return matches;
};

export default useMediaQuery;

// Predefined breakpoint hooks
export const useIsMobile = () => useMediaQuery('(max-width: 639px)');
export const useIsTablet = () => useMediaQuery('(min-width: 640px) and (max-width: 1023px)');
export const useIsDesktop = () => useMediaQuery('(min-width: 1024px)');

/**
 * usePagination Hook
 * Manages pagination state and logic.
 */
import { useState, useMemo, useCallback } from 'react';

const usePagination = (data = [], defaultPageSize = 10) => {
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(defaultPageSize);

  const totalPages = useMemo(() => Math.ceil(data.length / pageSize), [data.length, pageSize]);

  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return data.slice(start, start + pageSize);
  }, [data, currentPage, pageSize]);

  const goToPage = useCallback((page) => {
    setCurrentPage(Math.min(Math.max(1, page), totalPages || 1));
  }, [totalPages]);

  const nextPage = useCallback(() => {
    setCurrentPage((prev) => Math.min(prev + 1, totalPages));
  }, [totalPages]);

  const prevPage = useCallback(() => {
    setCurrentPage((prev) => Math.max(prev - 1, 1));
  }, []);

  const changePageSize = useCallback((size) => {
    setPageSize(size);
    setCurrentPage(1);
  }, []);

  return {
    currentPage,
    pageSize,
    totalPages,
    paginatedData,
    totalItems: data.length,
    goToPage,
    nextPage,
    prevPage,
    changePageSize,
  };
};

export default usePagination;

