                <Button size="xs" variant="ghost" icon={Edit3} onClick={() => toast.success('Edit coupon')}>Edit</Button>
                <Button size="xs" variant="ghost" icon={Trash2} className="text-red-500 hover:bg-red-50"
                        onClick={() => setDeleteModal({ open: true, coupon })}>Delete</Button>
              </div>
            </Card>
          </motion.div>
        ))}
      </div>

      <ConfirmModal
        isOpen={deleteModal.open}
        onClose={() => setDeleteModal({ open: false, coupon: null })}
        onConfirm={() => { toast.success('Coupon deleted'); setDeleteModal({ open: false, coupon: null }); }}
        type="delete" title="Delete Coupon"
        message={`Delete coupon "${deleteModal.coupon?.code}"? This cannot be undone.`}
        confirmLabel="Delete Coupon"
      />
    </div>
  );
};

export default CouponList;

/**
 * Customer List Page
 */
import React, { useState } from 'react';
import { Users, Mail, Phone, ShoppingBag } from 'lucide-react';
import { PageHeader, SearchFilter, DataTable } from '../../components/common';
import { customers } from '../../utils/dummyData';
import { formatCurrency, formatDate, getInitials } from '../../utils/formatters';
import useDebounce from '../../hooks/useDebounce';

const CustomerList = () => {
  const [searchQuery, setSearchQuery] = useState('');
  const debouncedSearch = useDebounce(searchQuery);

  const filtered = debouncedSearch
    ? customers.filter((c) => c.name.toLowerCase().includes(debouncedSearch.toLowerCase()) || c.email.toLowerCase().includes(debouncedSearch.toLowerCase()))
    : customers;

  const columns = [
    { key: 'name', label: 'Customer', render: (_, row) => (
      <div className="flex items-center gap-3">
        <div className="w-9 h-9 bg-gradient-to-br from-blue-100 to-indigo-100 rounded-xl flex items-center justify-center flex-shrink-0">
          <span className="text-xs font-bold text-blue-600">{getInitials(row.name)}</span>
        </div>
        <div>
          <p className="text-sm font-semibold text-gray-900">{row.name}</p>
          <p className="text-xs text-gray-400">{row.email}</p>
        </div>
      </div>
    )},
    { key: 'phone', label: 'Phone', render: (val) => <span className="text-sm text-gray-600">{val}</span> },
    { key: 'orders', label: 'Orders', render: (val) => <span className="text-sm font-semibold text-gray-900">{val}</span> },
    { key: 'totalSpend', label: 'Lifetime Spend', render: (val) => <span className="text-sm font-semibold text-gray-900">{formatCurrency(val)}</span> },
    { key: 'avgOrderValue', label: 'Avg. Order', render: (val) => <span className="text-sm text-gray-600">{formatCurrency(val)}</span> },
    { key: 'lastOrder', label: 'Last Order', render: (val) => <span className="text-xs text-gray-500">{formatDate(val)}</span> },
    { key: 'notes', label: 'Notes', render: (val) => val ? <span className="text-xs text-gray-500 italic">{val}</span> : <span className="text-xs text-gray-300">—</span> },
  ];

  return (
    <div className="space-y-6 pb-8">
      <PageHeader title="Customers" subtitle={`${customers.length} customers have ordered from your store`} />
      <SearchFilter searchValue={searchQuery} onSearchChange={setSearchQuery} placeholder="Search by name or email..." />
      <DataTable columns={columns} data={filtered} emptyIcon="search" emptyTitle="No customers found" />
    </div>
  );
};

export default CustomerList;

/**
 * Seller Dashboard Page
 * Complete dashboard with stats, charts, recent orders, and quick actions.
 */
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import {
  ShoppingCart, Package, DollarSign, Wallet, Star, Users,
  TrendingUp, AlertTriangle, ArrowRight, Plus, BarChart3, Ticket,
  Eye, Clock, CheckCircle2, XCircle, RotateCcw,
} from 'lucide-react';
import {
  AreaChart, Area, BarChart, Bar, XAxis, YAxis, CartesianGrid,
  Tooltip, ResponsiveContainer, PieChart, Pie, Cell, LineChart, Line,
} from 'recharts';
import { StatCard, PageHeader, StatusBadge } from '../../components/common';
import { Card } from '../../components/ui';
import { DashboardSkeleton } from '../../components/ui/Skeleton';
import { formatCurrency, formatDate, getRelativeTime } from '../../utils/formatters';
import {
  dashboardStats, orders, products, reviews,
  monthlySalesData, weeklySalesData, categorySalesData, inventoryAlerts,
} from '../../utils/dummyData';
import { CHART_COLORS } from '../../constants';

const Dashboard = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Simulate API loading
    const timer = setTimeout(() => setLoading(false), 600);
    return () => clearTimeout(timer);
  }, []);

  if (loading) return <DashboardSkeleton />;

  const stats = dashboardStats;
  const recentOrders = orders.slice(0, 5);
  const topProducts = [...products].sort((a, b) => b.sales - a.sales).slice(0, 5);
  const latestReviews = reviews.slice(0, 3);

  return (
    <div className="space-y-8 pb-8">
      <PageHeader title="Dashboard" subtitle="Overview of your store performance">
        <button
          onClick={() => navigate('/seller/products/add')}
          className="flex items-center gap-2 px-4 py-2.5 bg-[#2563EB] text-white text-sm font-semibold rounded-xl
                     shadow-lg shadow-blue-200/50 hover:bg-[#1D4ED8] transition-all active:scale-95"
        >
          <Plus size={18} /> Add Product
        </button>
      </PageHeader>

      {/* ─── Stat Cards ─────────────────────────────────── */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5">
        <StatCard title="Today's Orders" value={stats.todayOrders} subtitle="orders received today" icon={ShoppingCart} iconBg="bg-blue-50" iconColor="text-blue-600" trend="up" trendValue="+12%" delay={0} />
        <StatCard title="Revenue" value={formatCurrency(stats.revenue)} subtitle="total revenue this month" icon={DollarSign} iconBg="bg-green-50" iconColor="text-green-600" trend="up" trendValue="+18%" delay={1} />
        <StatCard title="Wallet Balance" value={formatCurrency(stats.walletBalance)} subtitle="available for withdrawal" icon={Wallet} iconBg="bg-purple-50" iconColor="text-purple-600" delay={2} />
        <StatCard title="Avg. Rating" value={stats.averageRating} subtitle={`based on ${328} reviews`} icon={Star} iconBg="bg-amber-50" iconColor="text-amber-500" trend="up" trendValue="+0.2" delay={3} />
      </div>

      {/* ─── Quick Stats Row ─────────────────────────────── */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        {[
          { label: 'Pending', value: stats.pendingOrders, icon: Clock, color: 'text-amber-500', bg: 'bg-amber-50' },
          { label: 'Completed', value: stats.completedOrders, icon: CheckCircle2, color: 'text-green-500', bg: 'bg-green-50' },
          { label: 'Cancelled', value: stats.cancelledOrders, icon: XCircle, color: 'text-red-500', bg: 'bg-red-50' },
          { label: 'Returns', value: stats.returns, icon: RotateCcw, color: 'text-orange-500', bg: 'bg-orange-50' },
        ].map((item, i) => (
          <motion.div
            key={item.label}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.4 + i * 0.1 }}
            className="bg-white rounded-xl border border-gray-100 p-4 flex items-center gap-3"
          >
            <div className={`p-2 rounded-lg ${item.bg}`}>
              <item.icon size={18} className={item.color} />
            </div>
            <div>
              <p className="text-xl font-bold text-gray-900">{item.value}</p>
              <p className="text-[11px] text-gray-400 font-medium">{item.label}</p>
            </div>
          </motion.div>
        ))}
      </div>

      {/* ─── Charts Row ─────────────────────────────────── */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Monthly Sales Chart */}
        <Card title="Monthly Sales" subtitle="Revenue & orders trend" className="lg:col-span-2">
          <div className="h-[320px] mt-4">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={monthlySalesData}>
                <defs>
                  <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563EB" stopOpacity={0.15} />
                    <stop offset="95%" stopColor="#2563EB" stopOpacity={0} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F3F4F6" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: '#9CA3AF', fontSize: 12 }} />
                <YAxis axisLine={false} tickLine={false} tick={{ fill: '#9CA3AF', fontSize: 12 }} tickFormatter={(v) => `₹${(v/1000)}k`} />
                <Tooltip
                  contentStyle={{ borderRadius: '12px', border: '1px solid #E5E7EB', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                  formatter={(value, name) => [name === 'revenue' ? formatCurrency(value) : value, name === 'revenue' ? 'Revenue' : 'Orders']}
                />
                <Area type="monotone" dataKey="revenue" stroke="#2563EB" strokeWidth={2.5} fill="url(#colorRevenue)" />
                <Line type="monotone" dataKey="orders" stroke="#8B5CF6" strokeWidth={2} dot={false} strokeDasharray="5 5" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </Card>

        {/* Category Sales Pie */}
        <Card title="Category Breakdown" subtitle="Sales by category">
          <div className="h-[220px] mt-4">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={categorySalesData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={90}
                  paddingAngle={4}
                  dataKey="value"
                >
                  {categorySalesData.map((_, i) => (
                    <Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip formatter={(value) => `${value}%`} />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="space-y-2 mt-2">
            {categorySalesData.map((cat, i) => (
              <div key={cat.name} className="flex items-center justify-between text-sm">
                <div className="flex items-center gap-2">
                  <span className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: CHART_COLORS[i] }} />
                  <span className="text-gray-600">{cat.name}</span>
                </div>
                <span className="font-semibold text-gray-900">{cat.value}%</span>
              </div>
            ))}
          </div>
        </Card>
      </div>

      {/* ─── Weekly Orders Chart + Quick Actions ─────────── */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <Card title="Weekly Orders" subtitle="Orders this week" className="lg:col-span-2">
          <div className="h-[280px] mt-4">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={weeklySalesData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F3F4F6" />
                <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fill: '#9CA3AF', fontSize: 12 }} />
                <YAxis axisLine={false} tickLine={false} tick={{ fill: '#9CA3AF', fontSize: 12 }} />
                <Tooltip contentStyle={{ borderRadius: '12px', border: '1px solid #E5E7EB' }} />
                <Bar dataKey="orders" fill="#2563EB" radius={[6, 6, 0, 0]} barSize={36} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </Card>

        {/* Quick Actions */}
        <Card title="Quick Actions" subtitle="Shortcuts to common tasks">
          <div className="grid grid-cols-2 gap-3 mt-4">
            {[
              { label: 'Add Product', icon: Plus, path: '/seller/products/add', color: 'text-blue-600', bg: 'bg-blue-50' },
              { label: 'View Orders', icon: ShoppingCart, path: '/seller/orders', color: 'text-green-600', bg: 'bg-green-50' },
              { label: 'Analytics', icon: BarChart3, path: '/seller/analytics', color: 'text-purple-600', bg: 'bg-purple-50' },
              { label: 'Coupons', icon: Ticket, path: '/seller/coupons', color: 'text-amber-600', bg: 'bg-amber-50' },
              { label: 'Inventory', icon: Package, path: '/seller/inventory', color: 'text-indigo-600', bg: 'bg-indigo-50' },
              { label: 'Earnings', icon: Wallet, path: '/seller/earnings', color: 'text-emerald-600', bg: 'bg-emerald-50' },
            ].map((action) => (
              <button
                key={action.label}
                onClick={() => navigate(action.path)}
                className={`flex flex-col items-center gap-2 p-4 rounded-xl ${action.bg} hover:scale-105 active:scale-95 transition-all`}
              >
                <action.icon size={22} className={action.color} />
                <span className="text-xs font-semibold text-gray-700">{action.label}</span>
              </button>
            ))}
          </div>
        </Card>
      </div>

      {/* ─── Recent Orders + Low Stock ──────────────────── */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Recent Orders */}
        <Card
          title="Recent Orders"
          headerAction={
            <button onClick={() => navigate('/seller/orders')} className="text-xs font-semibold text-blue-600 hover:text-blue-700 flex items-center gap-1">
              View All <ArrowRight size={14} />
            </button>
          }
        >
          <div className="space-y-3 mt-4">
            {recentOrders.map((order) => (
              <div
                key={order.id}
                onClick={() => navigate(`/seller/orders/${order.id}`)}
                className="flex items-center justify-between p-3.5 rounded-xl hover:bg-gray-50 transition-colors cursor-pointer group"
              >
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-gray-50 rounded-xl flex items-center justify-center group-hover:bg-white transition-colors">
                    <ShoppingCart size={18} className="text-gray-400" />
                  </div>
                  <div>
                    <p className="text-sm font-semibold text-gray-900">#{order.id}</p>
                    <p className="text-xs text-gray-400">{order.customer.name}</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-sm font-semibold text-gray-900">{formatCurrency(order.finalAmount)}</p>
                  <StatusBadge status={order.status} size="sm" />
                </div>
              </div>
            ))}
          </div>
        </Card>

        {/* Inventory Alerts */}
        <Card
          title="Inventory Alerts"
          headerAction={
            <span className="text-[10px] font-semibold text-red-600 bg-red-50 px-2 py-1 rounded-full">
              {inventoryAlerts.length} alerts
            </span>
          }
        >
          <div className="space-y-3 mt-4">
            {inventoryAlerts.map((alert) => (
              <div key={alert.productId} className="flex items-center justify-between p-3.5 rounded-xl bg-gray-50 hover:bg-gray-100 transition-colors">
                <div className="flex items-center gap-3">
                  <div className={`p-2 rounded-lg ${alert.status === 'out' ? 'bg-red-50' : 'bg-amber-50'}`}>
                    <AlertTriangle size={18} className={alert.status === 'out' ? 'text-red-500' : 'text-amber-500'} />
                  </div>
                  <div>
                    <p className="text-sm font-semibold text-gray-900">{alert.title}</p>
                    <p className="text-xs text-gray-400">
                      {alert.stock === 0 ? 'Out of stock' : `${alert.stock} units remaining`}
                    </p>
                  </div>
                </div>
                <button className="px-3 py-1.5 bg-[#2563EB] text-white text-xs font-semibold rounded-lg hover:bg-[#1D4ED8] transition-colors">
                  Restock
                </button>
              </div>
            ))}

            {/* Top Selling Products */}
            <div className="pt-4 mt-2 border-t border-gray-100">
              <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-3">Top Selling Products</p>
              {topProducts.slice(0, 3).map((product, i) => (
                <div key={product.id} className="flex items-center justify-between py-2.5">
                  <div className="flex items-center gap-3">
                    <span className="w-6 h-6 bg-blue-50 rounded-lg flex items-center justify-center text-[10px] font-bold text-blue-600">
                      {i + 1}
                    </span>
                    <p className="text-sm text-gray-700 font-medium line-clamp-1">{product.title}</p>
                  </div>
                  <span className="text-xs font-semibold text-gray-500">{product.sales} sold</span>
                </div>
              ))}
            </div>
          </div>
        </Card>
      </div>

      {/* ─── Latest Reviews ─────────────────────────────── */}
      <Card
        title="Latest Reviews"
        headerAction={
          <button onClick={() => navigate('/seller/reviews')} className="text-xs font-semibold text-blue-600 hover:text-blue-700 flex items-center gap-1">
            View All <ArrowRight size={14} />
          </button>
        }
      >
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-4">
          {latestReviews.map((review) => (
            <div key={review.id} className="p-4 rounded-xl border border-gray-100 hover:border-blue-100 transition-colors">
              <div className="flex items-center gap-2 mb-2">
                <div className="flex gap-0.5">
                  {Array.from({ length: 5 }).map((_, i) => (
                    <Star key={i} size={14} className={i < review.rating ? 'text-amber-400 fill-amber-400' : 'text-gray-200'} />
                  ))}
                </div>
                <span className="text-xs text-gray-400">{getRelativeTime(new Date(review.createdAt))}</span>
              </div>
              <p className="text-sm text-gray-600 line-clamp-2 mb-2">{review.text}</p>
              <div className="flex items-center justify-between">
                <p className="text-xs font-semibold text-gray-900">{review.customer}</p>
                <p className="text-[10px] text-gray-400 truncate ml-2">{review.productTitle}</p>
              </div>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
};

export default Dashboard;

/**
 * Earnings Page
 * Wallets, Payouts, Transaction history, Settlements.
 */
import React, { useState } from 'react';
import { Wallet, Landmark, RefreshCw, DollarSign, Download, ArrowUpRight, ArrowDownRight } from 'lucide-react';
import { PageHeader, StatCard, DataTable, StatusBadge } from '../../components/common';
import { Card, Button } from '../../components/ui';
import { earningsData, transactions, settlements } from '../../utils/dummyData';
import { formatCurrency, formatDate } from '../../utils/formatters';
import toast from 'react-hot-toast';

const Earnings = () => {
  const [requesting, setRequesting] = useState(false);

  const handlePayoutRequest = () => {
    setRequesting(true);
    setTimeout(() => {
      setRequesting(false);
      toast.success('Payout request submitted successfully!');
    }, 1000);
  };

  const columns = [
    { key: 'id', label: 'Transaction ID', render: (val) => <span className="font-mono text-xs">{val}</span> },
    { key: 'type', label: 'Type', render: (val) => (
      <span className={`inline-flex items-center gap-1 text-xs font-semibold ${
        val === 'payout' ? 'text-red-600' : 'text-green-600'
      }`}>
        {val === 'payout' ? <ArrowDownRight size={14} /> : <ArrowUpRight size={14} />}
        {val === 'payout' ? 'Withdrawal' : 'Sale'}
      </span>
    )},
    { key: 'amount', label: 'Amount', render: (val, row) => (
      <span className={`text-sm font-semibold ${row.type === 'payout' ? 'text-red-600' : 'text-green-600'}`}>
        {row.type === 'payout' ? '-' : '+'}{formatCurrency(val)}
      </span>
    )},
    { key: 'status', label: 'Status', render: (val) => <StatusBadge status={val} size="sm" /> },
    { key: 'createdAt', label: 'Date & Time', render: (val) => <span className="text-xs text-gray-500">{formatDate(val, 'short')}</span> }
  ];

  return (
    <div className="space-y-6 pb-8">
      <PageHeader title="Earnings & Payouts" subtitle="Track your wallet balance, recent settlements, and withdrawal transactions" />

      {/* Main Balance Info */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <Card className="md:col-span-2">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 p-2">
            <div className="flex items-center gap-4">
              <div className="p-4 bg-blue-50 text-blue-600 rounded-2xl">
                <Wallet size={32} />
              </div>
              <div>
                <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Available Balance</p>
                <h2 className="text-3xl font-extrabold text-gray-900 mt-1">{formatCurrency(earningsData.availableBalance)}</h2>
              </div>
            </div>
            <Button
              onClick={handlePayoutRequest}
              loading={requesting}
              icon={RefreshCw}
              disabled={earningsData.availableBalance <= 0}
            >
              Withdraw to Bank
            </Button>
          </div>
        </Card>

        <StatCard
          title="Total Withdrawn"
          value={formatCurrency(earningsData.totalWithdrawn)}
          subtitle="Lifetime payouts transferred"
          icon={Landmark}
          iconBg="bg-green-50"
          iconColor="text-green-600"
        />
      </div>

      {/* Settlements Breakdown */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Transaction History */}
        <div className="lg:col-span-2">
          <Card title="Transaction History" subtitle="Detailed credit and debit transactions list">
            <DataTable
              columns={columns}
              data={transactions}
              pageSize={5}
              emptyIcon="default"
              emptyTitle="No transactions found"
            />
          </Card>
        </div>

        {/* Bank Account Info & Payouts */}
        <div className="space-y-6">
          <Card title="Settlement Bank Account">
            <div className="mt-4 p-4 bg-gray-50 rounded-xl space-y-3">
              <div className="flex items-center gap-3">
                <Landmark size={20} className="text-gray-400" />
                <div>
                  <p className="text-sm font-semibold text-gray-900">{earningsData.bankDetails.bankName}</p>
                  <p className="text-xs text-gray-400">Account: *******{earningsData.bankDetails.accountNumber.slice(-4)}</p>
                </div>
              </div>
              <div className="border-t border-gray-100 pt-3 text-xs text-gray-500 space-y-1">
                <div className="flex justify-between"><span>IFSC Code:</span><span className="font-semibold text-gray-700">{earningsData.bankDetails.ifsc}</span></div>
                <div className="flex justify-between"><span>Beneficiary:</span><span className="font-semibold text-gray-700">{earningsData.bankDetails.holderName}</span></div>
              </div>
            </div>
          </Card>

          <Card title="Settlements Log" subtitle="Recent batch bank transfers">
            <div className="space-y-3 mt-4">
              {settlements.map((s) => (
                <div key={s.id} className="flex justify-between items-center py-2 border-b border-gray-50 last:border-0">
                  <div>
                    <p className="text-xs font-semibold text-gray-900">{s.id}</p>
                    <p className="text-[10px] text-gray-400">{formatDate(s.date)}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-bold text-gray-900">{formatCurrency(s.amount)}</p>
                    <StatusBadge status={s.status} size="sm" />
                  </div>
                </div>
              ))}
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
};

export default Earnings;

/**
 * Inventory Manager Page
 */
import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Package, AlertTriangle, TrendingDown, Archive, ArrowUpDown } from 'lucide-react';
import { PageHeader, StatCard, SearchFilter, DataTable, StatusBadge } from '../../components/common';
import { Card, Button } from '../../components/ui';
import { products, inventoryAlerts, stockHistory } from '../../utils/dummyData';
import { formatDate } from '../../utils/formatters';
import toast from 'react-hot-toast';

const InventoryManager = () => {
  const [searchQuery, setSearchQuery] = useState('');
  const inStock = products.filter((p) => p.stock > 10).length;
  const lowStock = products.filter((p) => p.stock > 0 && p.stock <= 10).length;
  const outOfStock = products.filter((p) => p.stock === 0).length;

  const filtered = searchQuery
    ? products.filter((p) => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    : products;

  const columns = [
    { key: 'title', label: 'Product', render: (_, row) => (
      <div className="flex items-center gap-3">
        <div className="w-10 h-10 bg-gray-50 rounded-lg flex items-center justify-center"><Package size={18} className="text-gray-300" /></div>
        <div>
          <p className="text-sm font-semibold text-gray-900 line-clamp-1">{row.title}</p>
          <p className="text-[10px] text-gray-400">SKU: {row.sku}</p>
        </div>
      </div>
    )},
    { key: 'stock', label: 'Stock', render: (val) => (
      <div className="flex items-center gap-2">
        <span className={`text-sm font-bold ${val === 0 ? 'text-red-500' : val < 10 ? 'text-amber-500' : 'text-green-600'}`}>{val}</span>
        <div className="w-20 h-1.5 bg-gray-100 rounded-full overflow-hidden">
          <div className={`h-full rounded-full ${val === 0 ? 'bg-red-500' : val < 10 ? 'bg-amber-400' : 'bg-green-500'}`}
               style={{ width: `${Math.min((val / 200) * 100, 100)}%` }} />
        </div>
      </div>
    )},
    { key: 'status', label: 'Status', align: 'center', render: (val, row) => {
      if (row.stock === 0) return <StatusBadge status="out_of_stock" size="sm" />;
      if (row.stock < 10) return <StatusBadge status="warning" size="sm" />;
      return <StatusBadge status="active" size="sm" />;
    }},
    { key: 'sales', label: 'Sold', render: (val) => <span className="text-sm text-gray-600">{val}</span> },
    { key: 'actions', label: '', sortable: false, render: (_, row) => (
      <Button size="xs" variant="outline" onClick={() => toast.success(`Stock updated for ${row.title}`)}>Restock</Button>
    )},
  ];

  return (
    <div className="space-y-6 pb-8">
      <PageHeader title="Inventory" subtitle="Manage your product stock levels" />

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-5">
        <StatCard title="In Stock" value={inStock} icon={Package} iconBg="bg-green-50" iconColor="text-green-600" delay={0} />
        <StatCard title="Low Stock" value={lowStock} icon={AlertTriangle} iconBg="bg-amber-50" iconColor="text-amber-500" delay={1} />
        <StatCard title="Out of Stock" value={outOfStock} icon={TrendingDown} iconBg="bg-red-50" iconColor="text-red-500" delay={2} />
      </div>

      {/* Inventory Alerts */}
      {inventoryAlerts.length > 0 && (
        <Card title="⚠️ Inventory Alerts" subtitle={`${inventoryAlerts.length} items need attention`}>
          <div className="space-y-2 mt-4">
            {inventoryAlerts.map((alert) => (
              <div key={alert.productId} className={`flex items-center justify-between p-3 rounded-xl ${alert.status === 'out' ? 'bg-red-50' : 'bg-amber-50'}`}>
                <div>
                  <p className="text-sm font-medium text-gray-900">{alert.title}</p>
                  <p className="text-xs text-gray-500">{alert.stock === 0 ? 'Out of stock' : `${alert.stock} units left (threshold: ${alert.threshold})`}</p>
                </div>
                <Button size="xs" variant={alert.status === 'out' ? 'danger' : 'primary'} onClick={() => toast.success('Restock request sent')}>Restock</Button>
              </div>
            ))}
          </div>
        </Card>
      )}

      <SearchFilter searchValue={searchQuery} onSearchChange={setSearchQuery} placeholder="Search products..." />
      <DataTable columns={columns} data={filtered} emptyIcon="products" emptyTitle="No products in inventory" />

      {/* Stock History */}
      <Card title="Stock History" subtitle="Recent stock changes">
        <div className="space-y-2 mt-4">
          {stockHistory.map((entry, i) => (
            <div key={i} className="flex items-center justify-between py-2.5 border-b border-gray-50 last:border-0">
              <div className="flex items-center gap-3">
                <div className={`p-1.5 rounded-lg ${entry.type === 'restock' ? 'bg-green-50' : 'bg-red-50'}`}>
                  <ArrowUpDown size={14} className={entry.type === 'restock' ? 'text-green-500' : 'text-red-500'} />
                </div>
                <div>
                  <p className="text-sm text-gray-700">{entry.title}</p>
                  <p className="text-xs text-gray-400">{formatDate(entry.date)}</p>
                </div>
              </div>
              <span className={`text-sm font-semibold ${entry.change > 0 ? 'text-green-600' : 'text-red-500'}`}>
                {entry.change > 0 ? '+' : ''}{entry.change}
              </span>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
};

export default InventoryManager;

/**
 * Notifications Page
 */
import React, { useState, useMemo } from 'react';
import { motion } from 'framer-motion';
import { Bell, ShoppingCart, RotateCcw, Star, Package, DollarSign, CheckCheck, Check } from 'lucide-react';
import { PageHeader } from '../../components/common';
import { Button, Badge } from '../../components/ui';
import { notifications as allNotifications } from '../../utils/dummyData';
import { getRelativeTime } from '../../utils/formatters';
import toast from 'react-hot-toast';

const typeConfig = {
  order: { icon: ShoppingCart, bg: 'bg-blue-50', color: 'text-blue-600' },
  return: { icon: RotateCcw, bg: 'bg-orange-50', color: 'text-orange-600' },
  review: { icon: Star, bg: 'bg-amber-50', color: 'text-amber-600' },
  inventory: { icon: Package, bg: 'bg-red-50', color: 'text-red-600' },
  payment: { icon: DollarSign, bg: 'bg-green-50', color: 'text-green-600' },
};

const tabs = ['all', 'order', 'return', 'review', 'inventory', 'payment'];

const Notifications = () => {
  const [activeTab, setActiveTab] = useState('all');
  const [notifications, setNotifications] = useState(allNotifications);

  const filtered = useMemo(() => {
    if (activeTab === 'all') return notifications;
    return notifications.filter((n) => n.type === activeTab);
  }, [activeTab, notifications]);

  const unreadCount = notifications.filter((n) => !n.read).length;

  const markAsRead = (id) => {
    setNotifications((prev) => prev.map((n) => n.id === id ? { ...n, read: true } : n));
  };

  const markAllRead = () => {
    setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
    toast.success('All notifications marked as read');
  };

  return (
    <div className="space-y-6 pb-8">
      <PageHeader title="Notifications" subtitle={`${unreadCount} unread notifications`}>
        {unreadCount > 0 && (
          <Button variant="secondary" icon={CheckCheck} size="sm" onClick={markAllRead}>Mark All Read</Button>
        )}
      </PageHeader>

      {/* Type Tabs */}
      <div className="flex gap-2 overflow-x-auto">
        {tabs.map((tab) => (
          <button key={tab} onClick={() => setActiveTab(tab)}
            className={`px-4 py-2 rounded-xl text-sm font-medium capitalize whitespace-nowrap transition-all ${
              activeTab === tab ? 'bg-[#2563EB] text-white shadow-sm' : 'bg-white border border-gray-200 text-gray-500 hover:bg-gray-50'}`}>
            {tab}
            {tab === 'all' && unreadCount > 0 && (
              <span className="ml-2 bg-red-500 text-white text-[10px] font-bold px-1.5 py-0.5 rounded-full">{unreadCount}</span>
            )}
          </button>
        ))}
      </div>

      {/* Notification List */}
      <div className="space-y-2">
        {filtered.map((notif, i) => {
          const config = typeConfig[notif.type] || typeConfig.order;
          const Icon = config.icon;
          return (
            <motion.div
              key={notif.id}
              initial={{ opacity: 0, y: 5 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.03 }}
              onClick={() => markAsRead(notif.id)}
              className={`flex items-start gap-4 p-4 rounded-xl border transition-all cursor-pointer ${
                notif.read ? 'bg-white border-gray-100 hover:bg-gray-50' : 'bg-blue-50/30 border-blue-100 hover:bg-blue-50/50'
              }`}
            >
              <div className={`p-2.5 rounded-xl ${config.bg} flex-shrink-0`}>
                <Icon size={18} className={config.color} />
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-start justify-between gap-2">
                  <p className={`text-sm ${notif.read ? 'text-gray-600' : 'text-gray-900 font-semibold'}`}>{notif.title}</p>
                  {!notif.read && <span className="w-2 h-2 bg-blue-500 rounded-full flex-shrink-0 mt-1.5" />}
                </div>
                <p className="text-xs text-gray-500 mt-0.5 line-clamp-2">{notif.message}</p>
                <p className="text-[10px] text-gray-400 mt-1.5">{getRelativeTime(new Date(notif.createdAt))}</p>
              </div>
              {!notif.read && (
                <button onClick={(e) => { e.stopPropagation(); markAsRead(notif.id); }}
                  className="p-1.5 rounded-lg hover:bg-blue-100 text-blue-400 flex-shrink-0" title="Mark as read">
                  <Check size={14} />
                </button>
              )}
            </motion.div>
          );
        })}

        {filtered.length === 0 && (
          <div className="text-center py-16">
            <Bell size={40} className="text-gray-200 mx-auto mb-4" />
            <p className="text-gray-500">No notifications</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Notifications;

/**
 * Order Detail Page
 * Full order details with timeline, customer info, products, and invoice.
 */
import React from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowLeft, Printer, Package, MapPin, CreditCard, User, Clock, CheckCircle2, Truck, ShoppingBag } from 'lucide-react';
import { PageHeader, StatusBadge } from '../../components/common';
import { Button, Card } from '../../components/ui';
import { orders } from '../../utils/dummyData';
import { formatCurrency, formatDate } from '../../utils/formatters';

const OrderDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const order = orders.find((o) => o.id === id);

  if (!order) {
    return (
      <div className="text-center py-20">
        <p className="text-gray-500">Order not found</p>
        <Button variant="secondary" onClick={() => navigate('/seller/orders')} className="mt-4">Go Back</Button>
      </div>
    );
  }

  const timelineSteps = [
    { label: 'Order Placed', date: order.placedAt, icon: ShoppingBag, done: true },
    { label: 'Confirmed', date: order.confirmedAt, icon: CheckCircle2, done: !!order.confirmedAt },
    { label: 'Packed', date: order.packedAt, icon: Package, done: !!order.packedAt },
    { label: 'Shipped', date: order.shippedAt, icon: Truck, done: !!order.shippedAt },
    { label: 'Delivered', date: order.deliveredAt, icon: CheckCircle2, done: !!order.deliveredAt },
  ];

  const handlePrint = () => window.print();

  return (
    <div className="space-y-6 pb-8">
      <PageHeader title={`Order #${order.id}`} subtitle={`Placed on ${formatDate(order.placedAt, 'long')}`}>
        <Button variant="secondary" icon={ArrowLeft} onClick={() => navigate('/seller/orders')}>Back</Button>
        <Button variant="secondary" icon={Printer} onClick={handlePrint}>Print Invoice</Button>
      </PageHeader>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Content */}
        <div className="lg:col-span-2 space-y-6">
          {/* Order Timeline */}
          <Card title="Order Timeline">
            <div className="flex items-center justify-between mt-4 relative">
              {/* Progress Line */}
              <div className="absolute top-5 left-0 right-0 h-0.5 bg-gray-100 z-0" />
              <div className="absolute top-5 left-0 h-0.5 bg-[#2563EB] z-0"
                   style={{ width: `${(timelineSteps.filter(s => s.done).length - 1) / (timelineSteps.length - 1) * 100}%` }} />

              {timelineSteps.map((step, i) => (
                <div key={step.label} className="flex flex-col items-center relative z-10">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 ${
                    step.done ? 'bg-[#2563EB] border-[#2563EB] text-white' : 'bg-white border-gray-200 text-gray-300'
                  }`}>
                    <step.icon size={18} />
                  </div>
                  <p className={`text-xs font-medium mt-2 ${step.done ? 'text-gray-900' : 'text-gray-400'}`}>{step.label}</p>
                  {step.date && <p className="text-[10px] text-gray-400 mt-0.5">{formatDate(step.date, 'short')}</p>}
                </div>
              ))}
            </div>
          </Card>

          {/* Products */}
          <Card title="Products">
            <div className="space-y-3 mt-4">
              {order.products.map((product) => (
                <div key={product.id} className="flex items-center justify-between p-4 bg-gray-50 rounded-xl">
                  <div className="flex items-center gap-3">
                    <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center border border-gray-100">
                      <Package size={20} className="text-gray-300" />
                    </div>
                    <div>
                      <p className="text-sm font-semibold text-gray-900">{product.title}</p>
                      <p className="text-xs text-gray-400">Qty: {product.qty}</p>
                    </div>
                  </div>
                  <p className="text-sm font-semibold text-gray-900">{formatCurrency(product.price * product.qty)}</p>
                </div>
              ))}
            </div>

            {/* Price Summary */}
            <div className="mt-4 pt-4 border-t border-gray-100 space-y-2">
              <div className="flex justify-between text-sm"><span className="text-gray-500">Subtotal</span><span className="text-gray-900">{formatCurrency(order.totalAmount)}</span></div>
              <div className="flex justify-between text-sm"><span className="text-gray-500">Shipping</span><span className="text-gray-900">{order.shippingCharge ? formatCurrency(order.shippingCharge) : 'Free'}</span></div>
              {order.discount > 0 && <div className="flex justify-between text-sm"><span className="text-gray-500">Discount</span><span className="text-green-600">-{formatCurrency(order.discount)}</span></div>}
              <div className="flex justify-between text-base font-bold pt-2 border-t border-gray-100"><span>Total</span><span>{formatCurrency(order.finalAmount)}</span></div>
            </div>
          </Card>

          {/* Invoice Print Area */}
          <div className="seller-print-area hidden">
            <h2 className="text-xl font-bold mb-4">Invoice — #{order.id}</h2>
            <p>Date: {formatDate(order.placedAt, 'long')}</p>
            <p>Customer: {order.customer.name}</p>
            <p>Total: {formatCurrency(order.finalAmount)}</p>
          </div>
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          {/* Status */}
          <Card title="Status">
            <div className="mt-3">
              <StatusBadge status={order.status} size="lg" />
              {order.trackingId && (
                <p className="text-xs text-gray-400 mt-3">Tracking ID: <span className="font-mono text-gray-600">{order.trackingId}</span></p>
              )}
            </div>
          </Card>

          {/* Customer */}
          <Card title="Customer Details">
            <div className="mt-3 space-y-3">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-blue-50 rounded-xl flex items-center justify-center">
                  <User size={18} className="text-blue-600" />
                </div>
                <div>
                  <p className="text-sm font-semibold text-gray-900">{order.customer.name}</p>
                  <p className="text-xs text-gray-400">{order.customer.email}</p>
                </div>
              </div>
              <p className="text-xs text-gray-500">📞 {order.customer.phone}</p>
            </div>
          </Card>

          {/* Shipping Address */}
          <Card title="Shipping Address">
            <div className="mt-3 flex items-start gap-3">
              <MapPin size={16} className="text-gray-400 mt-0.5 flex-shrink-0" />
              <div className="text-sm text-gray-600 leading-relaxed">
                {order.address.line1}, {order.address.city}, {order.address.state} — {order.address.pincode}
              </div>
            </div>
          </Card>

          {/* Payment */}
          <Card title="Payment">
            <div className="mt-3 space-y-2">
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Method</span>
                <span className="font-medium text-gray-900">{order.payment.method}</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Status</span>
                <StatusBadge status={order.payment.status} size="sm" />
              </div>
              {order.payment.transactionId && (
                <div className="flex justify-between text-sm">
                  <span className="text-gray-500">Txn ID</span>
                  <span className="font-mono text-xs text-gray-600">{order.payment.transactionId}</span>
                </div>
              )}
            </div>
          </Card>

          {/* Notes */}
          {order.notes && (
            <Card title="Notes">
              <p className="text-sm text-gray-600 mt-3">{order.notes}</p>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
};

export default OrderDetail;

/**
 * Order List Page
 * Tabbed order management with search, filters, and status actions.
 */
import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { ShoppingCart, Eye } from 'lucide-react';
import { PageHeader, StatusBadge, SearchFilter, DataTable } from '../../components/common';
import { orders } from '../../utils/dummyData';
import { formatCurrency, formatDate } from '../../utils/formatters';
import useDebounce from '../../hooks/useDebounce';
import toast from 'react-hot-toast';

const tabs = [
  { key: 'all', label: 'All Orders' },
  { key: 'pending', label: 'Pending' },
  { key: 'packed', label: 'Packed' },
  { key: 'shipped', label: 'Shipped' },
  { key: 'delivered', label: 'Delivered' },
  { key: 'cancelled', label: 'Cancelled' },
  { key: 'returned', label: 'Returned' },
];

const OrderList = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const debouncedSearch = useDebounce(searchQuery);

  const filteredOrders = useMemo(() => {
    let result = [...orders];
    if (activeTab !== 'all') result = result.filter((o) => o.status === activeTab);
    if (debouncedSearch) {
      const q = debouncedSearch.toLowerCase();
      result = result.filter((o) => o.id.toLowerCase().includes(q) || o.customer.name.toLowerCase().includes(q));
    }
    return result;
  }, [activeTab, debouncedSearch]);

  const getTabCount = (tab) => tab === 'all' ? orders.length : orders.filter((o) => o.status === tab).length;

  const handleStatusUpdate = (orderId, newStatus) => {
    toast.success(`Order #${orderId} status updated to ${newStatus}`);
  };

  const columns = [
    { key: 'id', label: 'Order ID', render: (val) => <span className="text-sm font-semibold text-blue-600">#{val}</span> },
    { key: 'customer', label: 'Customer', render: (val) => (
      <div>
        <p className="text-sm font-medium text-gray-900">{val.name}</p>
        <p className="text-xs text-gray-400">{val.phone}</p>
      </div>
    )},
    { key: 'products', label: 'Items', render: (val) => (
      <div>
        <p className="text-sm text-gray-700">{val[0]?.title?.substring(0, 30)}...</p>
        {val.length > 1 && <p className="text-xs text-gray-400">+{val.length - 1} more</p>}
      </div>
    )},
    { key: 'finalAmount', label: 'Total', render: (val) => <span className="text-sm font-semibold text-gray-900">{formatCurrency(val)}</span> },
    { key: 'payment', label: 'Payment', render: (val) => (
      <div>
        <p className="text-xs font-medium text-gray-600">{val.method}</p>
        <StatusBadge status={val.status} size="sm" />
      </div>
    )},
    { key: 'status', label: 'Status', align: 'center', render: (val) => <StatusBadge status={val} /> },
    { key: 'placedAt', label: 'Date', render: (val) => <span className="text-xs text-gray-500">{formatDate(val)}</span> },
    { key: 'actions', label: '', sortable: false, render: (_, row) => (
      <button onClick={(e) => { e.stopPropagation(); navigate(`/seller/orders/${row.id}`); }}
              className="p-2 rounded-lg hover:bg-blue-50 text-gray-400 hover:text-blue-600 transition-colors" title="View Details">
        <Eye size={16} />
      </button>
    )},
  ];

  return (
    <div className="space-y-6 pb-8">
      <PageHeader title="Orders" subtitle={`${filteredOrders.length} orders found`} />

      {/* Status Tabs */}
      <div className="flex overflow-x-auto gap-1 bg-white rounded-xl border border-gray-100 p-1">
        {tabs.map((tab) => (
          <button key={tab.key} onClick={() => setActiveTab(tab.key)}
            className={`flex items-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium whitespace-nowrap transition-all ${
              activeTab === tab.key ? 'bg-[#2563EB] text-white shadow-sm' : 'text-gray-500 hover:bg-gray-50'
            }`}
          >
            {tab.label}
            <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded-full ${
              activeTab === tab.key ? 'bg-white/20 text-white' : 'bg-gray-100 text-gray-400'
            }`}>
              {getTabCount(tab.key)}
            </span>
          </button>
        ))}
      </div>

      <SearchFilter searchValue={searchQuery} onSearchChange={setSearchQuery} placeholder="Search by order ID or customer..." />

      <DataTable
        columns={columns}
        data={filteredOrders}
        onRowClick={(row) => navigate(`/seller/orders/${row.id}`)}
        emptyIcon="orders"
        emptyTitle="No orders found"
        emptyDescription="Orders will appear here once customers make purchases."
      />
    </div>
  );
};

export default OrderList;

/**
 * Add/Edit Product Page
 * Multi-section form with image upload, specifications, and SEO fields.
 */
import React, { useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useForm } from 'react-hook-form';
import { motion } from 'framer-motion';
import { Save, ArrowLeft, Eye, FileText, Package, DollarSign, Image, Settings, Globe } from 'lucide-react';
import { PageHeader } from '../../components/common';
import { ImageUploader } from '../../components/common';
import { Button } from '../../components/ui';
import { products } from '../../utils/dummyData';
import { CATEGORIES } from '../../constants';
import toast from 'react-hot-toast';

const AddProduct = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const isEdit = !!id;
  const existingProduct = isEdit ? products.find((p) => p.id === id) : null;

  const [activeSection, setActiveSection] = useState('basic');
  const [images, setImages] = useState([]);
  const [specifications, setSpecifications] = useState(existingProduct?.specifications || [{ key: '', value: '' }]);

  const { register, handleSubmit, formState: { errors }, watch } = useForm({
    defaultValues: existingProduct || {
      title: '', shortDescription: '', description: '', category: '', subcategory: '',
      brand: '', sku: '', price: '', discountPrice: '', gst: '', stock: '',
      weight: '', tags: '', warranty: '', returnPolicy: '', shippingInfo: '',
      seoTitle: '', seoDescription: '',
    },
  });

  const sections = [
    { id: 'basic', label: 'Basic Info', icon: Package },
    { id: 'pricing', label: 'Pricing & Stock', icon: DollarSign },
    { id: 'media', label: 'Media', icon: Image },
    { id: 'specs', label: 'Specifications', icon: Settings },
    { id: 'seo', label: 'SEO & Shipping', icon: Globe },
  ];

  const onSubmit = (data) => {
    toast.success(isEdit ? 'Product updated successfully!' : 'Product created successfully!');
    navigate('/seller/products');
  };

  const onSaveDraft = () => {
    toast.success('Saved as draft');
  };

  const inputClass = "w-full px-4 py-2.5 text-sm bg-white border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-100 focus:border-blue-300 transition-all";
  const labelClass = "block text-sm font-medium text-gray-700 mb-1.5";

  return (
    <div className="space-y-6 pb-8">
      <PageHeader title={isEdit ? 'Edit Product' : 'Add New Product'} subtitle={isEdit ? `Editing: ${existingProduct?.title}` : 'Fill in the product details'}>
        <Button variant="secondary" icon={ArrowLeft} onClick={() => navigate('/seller/products')}>Back</Button>
      </PageHeader>

      <div className="flex flex-col lg:flex-row gap-6">
        {/* Section Navigation */}
        <div className="lg:w-56 flex-shrink-0">
          <div className="bg-white rounded-xl border border-gray-100 p-2 sticky top-24">
            {sections.map((section) => (
              <button
                key={section.id}
                onClick={() => setActiveSection(section.id)}
                className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-all ${
                  activeSection === section.id ? 'bg-blue-50 text-blue-600' : 'text-gray-500 hover:bg-gray-50'
                }`}
              >
                <section.icon size={16} />
                {section.label}
              </button>
            ))}
          </div>
        </div>

        {/* Form Content */}
        <div className="flex-1">
          <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
            {/* Basic Info */}
            {activeSection === 'basic' && (
              <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} className="bg-white rounded-2xl border border-gray-100 p-6 space-y-5">
                <h3 className="text-base font-semibold text-gray-900">Basic Information</h3>

                <div>
                  <label className={labelClass}>Product Title *</label>
                  <input {...register('title', { required: 'Title is required' })} placeholder="Enter product title" className={inputClass} />
                  {errors.title && <p className="text-xs text-red-500 mt-1">{errors.title.message}</p>}
                </div>

                <div>
                  <label className={labelClass}>Short Description</label>
                  <input {...register('shortDescription')} placeholder="Brief description (one liner)" className={inputClass} />
                </div>

                <div>
                  <label className={labelClass}>Full Description *</label>
                  <textarea {...register('description', { required: 'Description is required' })} rows={5} placeholder="Detailed product description" className={inputClass} />
                  {errors.description && <p className="text-xs text-red-500 mt-1">{errors.description.message}</p>}
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className={labelClass}>Category *</label>
                    <select {...register('category', { required: 'Category is required' })} className={inputClass}>
                      <option value="">Select category</option>
                      {CATEGORIES.map((c) => <option key={c.id} value={c.name}>{c.name}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className={labelClass}>Subcategory</label>
                    <select {...register('subcategory')} className={inputClass}>
                      <option value="">Select subcategory</option>
                      {CATEGORIES.find((c) => c.name === watch('category'))?.subcategories.map((s) => (
                        <option key={s} value={s}>{s}</option>
                      ))}
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className={labelClass}>Brand</label>
                    <input {...register('brand')} placeholder="Brand name" className={inputClass} />
                  </div>
                  <div>
                    <label className={labelClass}>SKU *</label>
                    <input {...register('sku', { required: 'SKU is required' })} placeholder="MH-XX-001" className={inputClass} />
                    {errors.sku && <p className="text-xs text-red-500 mt-1">{errors.sku.message}</p>}
                  </div>
                </div>

                <div>
                  <label className={labelClass}>Tags</label>
                  <input {...register('tags')} placeholder="Comma-separated tags (e.g., handmade, organic)" className={inputClass} />
                </div>
              </motion.div>
            )}

            {/* Pricing & Stock */}
            {activeSection === 'pricing' && (
              <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} className="bg-white rounded-2xl border border-gray-100 p-6 space-y-5">
                <h3 className="text-base font-semibold text-gray-900">Pricing & Inventory</h3>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                  <div>
                    <label className={labelClass}>Price (₹) *</label>
                    <input type="number" {...register('price', { required: 'Price is required', min: { value: 0, message: 'Must be positive' } })} placeholder="0" className={inputClass} />
                    {errors.price && <p className="text-xs text-red-500 mt-1">{errors.price.message}</p>}
                  </div>
                  <div>
                    <label className={labelClass}>Discount Price (₹)</label>
                    <input type="number" {...register('discountPrice')} placeholder="0" className={inputClass} />
                  </div>
                  <div>
                    <label className={labelClass}>GST (%)</label>
                    <select {...register('gst')} className={inputClass}>
                      <option value="">No GST</option>
                      <option value="0">0%</option>
                      <option value="5">5%</option>
                      <option value="12">12%</option>
                      <option value="18">18%</option>
                      <option value="28">28%</option>
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                  <div>
                    <label className={labelClass}>Stock *</label>
                    <input type="number" {...register('stock', { required: 'Stock is required', min: 0 })} placeholder="0" className={inputClass} />
                  </div>
                  <div>
                    <label className={labelClass}>Weight (kg)</label>
                    <input type="number" step="0.01" {...register('weight')} placeholder="0.5" className={inputClass} />
                  </div>
                  <div>
                    <label className={labelClass}>Dimensions (LxWxH cm)</label>
                    <input {...register('dimensions')} placeholder="40x30x0.5" className={inputClass} />
                  </div>
                </div>

                <div>
                  <label className={labelClass}>Warranty</label>
                  <input {...register('warranty')} placeholder="e.g., 1 year against manufacturing defects" className={inputClass} />
                </div>
              </motion.div>
            )}

            {/* Media */}
            {activeSection === 'media' && (
              <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} className="bg-white rounded-2xl border border-gray-100 p-6 space-y-5">
                <h3 className="text-base font-semibold text-gray-900">Product Images</h3>
                <p className="text-sm text-gray-500">Upload high-quality images. First image will be the thumbnail.</p>
                <ImageUploader images={images} onChange={setImages} maxImages={8} label="" />
              </motion.div>
            )}

            {/* Specifications */}
            {activeSection === 'specs' && (
              <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} className="bg-white rounded-2xl border border-gray-100 p-6 space-y-5">
                <h3 className="text-base font-semibold text-gray-900">Specifications & Highlights</h3>

                <div>
                  <label className={labelClass}>Specifications</label>
                  <div className="space-y-3">
                    {specifications.map((spec, i) => (
                      <div key={i} className="flex items-center gap-3">
                        <input value={spec.key} onChange={(e) => { const s = [...specifications]; s[i].key = e.target.value; setSpecifications(s); }}
                               placeholder="Attribute (e.g., Material)" className={`${inputClass} flex-1`} />
                        <input value={spec.value} onChange={(e) => { const s = [...specifications]; s[i].value = e.target.value; setSpecifications(s); }}
                               placeholder="Value (e.g., Cotton)" className={`${inputClass} flex-1`} />
                        {specifications.length > 1 && (
                          <button type="button" onClick={() => setSpecifications(specifications.filter((_, j) => j !== i))} className="text-red-400 hover:text-red-600 p-1">✕</button>
                        )}
                      </div>
                    ))}
                    <button type="button" onClick={() => setSpecifications([...specifications, { key: '', value: '' }])}
                            className="text-sm text-blue-600 font-medium hover:text-blue-700">+ Add Specification</button>
                  </div>
                </div>

                <div>
                  <label className={labelClass}>Highlights</label>
                  <textarea {...register('highlights')} rows={3} placeholder="Enter product highlights, one per line" className={inputClass} />
                </div>
              </motion.div>
            )}

            {/* SEO & Shipping */}
            {activeSection === 'seo' && (
              <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} className="bg-white rounded-2xl border border-gray-100 p-6 space-y-5">
                <h3 className="text-base font-semibold text-gray-900">SEO & Shipping</h3>

                <div>
                  <label className={labelClass}>SEO Title</label>
                  <input {...register('seoTitle')} placeholder="SEO-friendly title" className={inputClass} />
                </div>
                <div>
                  <label className={labelClass}>SEO Description</label>
                  <textarea {...register('seoDescription')} rows={3} placeholder="Meta description for search engines" className={inputClass} />
                </div>
                <div>
                  <label className={labelClass}>Return Policy</label>
                  <input {...register('returnPolicy')} placeholder="e.g., 7-day return if damaged" className={inputClass} />
                </div>
                <div>
                  <label className={labelClass}>Shipping Info</label>
                  <textarea {...register('shippingInfo')} rows={2} placeholder="Shipping details and estimated delivery" className={inputClass} />
                </div>
              </motion.div>
            )}

            {/* Action Buttons */}
            <div className="flex items-center gap-3 justify-end sticky bottom-4 bg-white/80 backdrop-blur-sm p-4 rounded-xl border border-gray-100">
              <Button variant="secondary" onClick={onSaveDraft} icon={FileText}>Save as Draft</Button>
              <Button variant="primary" type="submit" icon={Save}>{isEdit ? 'Update Product' : 'Publish Product'}</Button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default AddProduct;

/**
 * Product List Page
 * Grid/Table view with search, filter, sort, pagination.
 */
import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Plus, Grid3X3, List, Edit3, Trash2, Copy, Eye, Package, MoreVertical, Star } from 'lucide-react';
import { PageHeader, StatusBadge, SearchFilter, ConfirmModal, DataTable } from '../../components/common';
import { Button, EmptyState } from '../../components/ui';
import { products } from '../../utils/dummyData';
import { formatCurrency } from '../../utils/formatters';
import usePagination from '../../hooks/usePagination';
import useDebounce from '../../hooks/useDebounce';
import toast from 'react-hot-toast';

const ProductList = () => {
  const navigate = useNavigate();
  const [viewMode, setViewMode] = useState('table');
  const [searchQuery, setSearchQuery] = useState('');
  const [filters, setFilters] = useState({});
  const [deleteModal, setDeleteModal] = useState({ open: false, product: null });
  const debouncedSearch = useDebounce(searchQuery);

  // Filter and search products
  const filteredProducts = useMemo(() => {
    let result = [...products];
    if (debouncedSearch) {
      const q = debouncedSearch.toLowerCase();
      result = result.filter((p) => p.title.toLowerCase().includes(q) || p.sku.toLowerCase().includes(q) || p.category.toLowerCase().includes(q));
    }
    if (filters.status && filters.status !== 'all') {
      result = result.filter((p) => p.status === filters.status);
    }
    if (filters.category && filters.category !== 'all') {
      result = result.filter((p) => p.category === filters.category);
    }
    return result;
  }, [debouncedSearch, filters]);

  const { paginatedData, currentPage, totalPages, pageSize, goToPage, changePageSize } = usePagination(filteredProducts, 10);

  const handleDelete = (product) => {
    setDeleteModal({ open: true, product });
  };

  const confirmDelete = () => {
    toast.success(`"${deleteModal.product?.title}" deleted successfully`);
    setDeleteModal({ open: false, product: null });
  };

  const handleDuplicate = (product) => {
    toast.success(`"${product.title}" duplicated`);
  };

  const filterConfig = [
    { key: 'status', label: 'Status', options: [
      { value: 'active', label: 'Active' }, { value: 'inactive', label: 'Inactive' },
      { value: 'out_of_stock', label: 'Out of Stock' }, { value: 'draft', label: 'Draft' },
    ]},
    { key: 'category', label: 'Category', options: [
      { value: 'Handicraft', label: 'Handicraft' }, { value: 'Food & Grocery', label: 'Food & Grocery' },
      { value: 'Clothing', label: 'Clothing' }, { value: 'Home & Living', label: 'Home & Living' },
    ]},
  ];

  // Table columns
  const columns = [
    { key: 'title', label: 'Product', render: (_, row) => (
      <div className="flex items-center gap-3 min-w-[200px]">
        <div className="w-11 h-11 bg-gray-50 rounded-xl flex items-center justify-center flex-shrink-0 border border-gray-100">
          <Package size={20} className="text-gray-300" />
        </div>
        <div>
          <p className="text-sm font-semibold text-gray-900 line-clamp-1">{row.title}</p>
          <p className="text-[11px] text-gray-400">SKU: {row.sku}</p>
        </div>
      </div>
    )},
    { key: 'category', label: 'Category', render: (val) => (
      <span className="text-xs font-medium text-gray-600 bg-gray-50 px-2.5 py-1 rounded-lg">{val}</span>
    )},
    { key: 'price', label: 'Price', render: (_, row) => (
      <div>
        <p className="text-sm font-semibold text-gray-900">{formatCurrency(row.discountPrice || row.price)}</p>
        {row.discountPrice && <p className="text-xs text-gray-400 line-through">{formatCurrency(row.price)}</p>}
      </div>
    )},
    { key: 'stock', label: 'Stock', render: (val) => (
      <div className="flex items-center gap-2">
        <span className={`text-sm font-semibold ${val === 0 ? 'text-red-500' : val < 10 ? 'text-amber-500' : 'text-gray-900'}`}>{val}</span>
        <div className="w-16 h-1.5 bg-gray-100 rounded-full overflow-hidden">
          <div className={`h-full rounded-full ${val === 0 ? 'bg-red-500' : val < 10 ? 'bg-amber-500' : 'bg-blue-500'}`}
               style={{ width: `${Math.min((val / 200) * 100, 100)}%` }} />
        </div>
      </div>
    )},
    { key: 'status', label: 'Status', align: 'center', render: (val) => <StatusBadge status={val} size="sm" /> },
    { key: 'sales', label: 'Sales', render: (val) => <span className="text-sm font-medium text-gray-600">{val}</span> },
    { key: 'actions', label: 'Actions', sortable: false, align: 'center', render: (_, row) => (
      <div className="flex items-center gap-1 justify-center">
        <button onClick={(e) => { e.stopPropagation(); navigate(`/seller/products/edit/${row.id}`); }}
                className="p-2 rounded-lg hover:bg-blue-50 text-gray-400 hover:text-blue-600 transition-colors" title="Edit">
          <Edit3 size={16} />
        </button>
        <button onClick={(e) => { e.stopPropagation(); handleDuplicate(row); }}
                className="p-2 rounded-lg hover:bg-gray-100 text-gray-400 hover:text-gray-600 transition-colors" title="Duplicate">
          <Copy size={16} />
        </button>
        <button onClick={(e) => { e.stopPropagation(); handleDelete(row); }}
                className="p-2 rounded-lg hover:bg-red-50 text-gray-400 hover:text-red-500 transition-colors" title="Delete">
          <Trash2 size={16} />
        </button>
      </div>
    )},
  ];

  return (
    <div className="space-y-6 pb-8">
      <PageHeader title="Products" subtitle={`${filteredProducts.length} products in your store`}>
        <div className="flex items-center gap-2">
          <div className="flex bg-gray-100 rounded-lg p-0.5">
            <button onClick={() => setViewMode('table')} className={`p-2 rounded-md transition-colors ${viewMode === 'table' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400'}`}>
              <List size={16} />
            </button>
            <button onClick={() => setViewMode('grid')} className={`p-2 rounded-md transition-colors ${viewMode === 'grid' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400'}`}>
              <Grid3X3 size={16} />
            </button>
          </div>
          <Button icon={Plus} onClick={() => navigate('/seller/products/add')}>Add Product</Button>
        </div>
      </PageHeader>

      <SearchFilter
        searchValue={searchQuery}
        onSearchChange={setSearchQuery}
        placeholder="Search products, SKU, category..."
        filters={filterConfig}
        activeFilters={filters}
        onFilterChange={(key, value) => setFilters((prev) => ({ ...prev, [key]: value }))}
      />

      {/* Table View */}
      {viewMode === 'table' && (
        <DataTable
          columns={columns}
          data={filteredProducts}
          onRowClick={(row) => navigate(`/seller/products/edit/${row.id}`)}
          emptyIcon="products"
          emptyTitle="No products found"
          emptyDescription="Add your first product to start selling."
        />
      )}

      {/* Grid View */}
      {viewMode === 'grid' && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5">
          <AnimatePresence>
            {filteredProducts.map((product, i) => (
              <motion.div
                key={product.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.05 }}
                onClick={() => navigate(`/seller/products/edit/${product.id}`)}
                className="bg-white rounded-2xl border border-gray-100 overflow-hidden hover:shadow-lg hover:border-blue-100 transition-all cursor-pointer group"
              >
                <div className="h-40 bg-gray-50 flex items-center justify-center relative">
                  <Package size={40} className="text-gray-200" />
                  <div className="absolute top-3 right-3"><StatusBadge status={product.status} size="sm" /></div>
                </div>
                <div className="p-4">
                  <p className="text-sm font-semibold text-gray-900 line-clamp-1 group-hover:text-blue-600 transition-colors">{product.title}</p>
                  <p className="text-xs text-gray-400 mt-1">{product.category} • SKU: {product.sku}</p>
                  <div className="flex items-center justify-between mt-3">
                    <div>
                      <p className="text-base font-bold text-gray-900">{formatCurrency(product.discountPrice || product.price)}</p>
                      {product.discountPrice && <p className="text-xs text-gray-400 line-through">{formatCurrency(product.price)}</p>}
                    </div>
                    <div className="flex items-center gap-1 text-xs text-gray-400">
                      <Star size={12} className="text-amber-400 fill-amber-400" />
                      <span>{product.rating}</span>
                    </div>
                  </div>
                  <div className="flex items-center justify-between mt-3 pt-3 border-t border-gray-50">
                    <span className={`text-xs font-medium ${product.stock === 0 ? 'text-red-500' : product.stock < 10 ? 'text-amber-500' : 'text-gray-500'}`}>
                      {product.stock === 0 ? 'Out of stock' : `${product.stock} in stock`}
                    </span>
                    <span className="text-xs text-gray-400">{product.sales} sold</span>
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>
      )}

      {filteredProducts.length === 0 && (
        <EmptyState icon="products" title="No products found" description="Try adjusting your search or filters." actionLabel="Add Product" onAction={() => navigate('/seller/products/add')} />
      )}

      <ConfirmModal
        isOpen={deleteModal.open}
        onClose={() => setDeleteModal({ open: false, product: null })}
        onConfirm={confirmDelete}
        type="delete"
        title="Delete Product"
        message={`Are you sure you want to delete "${deleteModal.product?.title}"? This action cannot be undone.`}
        confirmLabel="Delete Product"
      />
    </div>
  );
};

export default ProductList;

/**
 * Return Management Page
 */
import React, { useState, useMemo } from 'react';
import { motion } from 'framer-motion';
import { CheckCircle, XCircle, Clock, RotateCcw } from 'lucide-react';
import { PageHeader, StatusBadge, SearchFilter } from '../../components/common';
import { Card, Button } from '../../components/ui';
import { ConfirmModal } from '../../components/common';
import { returns } from '../../utils/dummyData';
import { formatCurrency, formatDate, getRelativeTime } from '../../utils/formatters';
import toast from 'react-hot-toast';

const tabs = [
  { key: 'all', label: 'All', icon: RotateCcw },
  { key: 'pending', label: 'Pending', icon: Clock },
  { key: 'approved', label: 'Approved', icon: CheckCircle },
  { key: 'rejected', label: 'Rejected', icon: XCircle },
];

const ReturnList = () => {
  const [activeTab, setActiveTab] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [confirmAction, setConfirmAction] = useState({ open: false, type: null, item: null });

  const filtered = useMemo(() => {
    let result = [...returns];
    if (activeTab !== 'all') result = result.filter((r) => r.status === activeTab);
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      result = result.filter((r) => r.orderId.toLowerCase().includes(q) || r.customer.name.toLowerCase().includes(q));
    }
    return result;
  }, [activeTab, searchQuery]);

  const handleAction = (type, item) => setConfirmAction({ open: true, type, item });

  const confirmHandler = () => {
    const action = confirmAction.type === 'approve' ? 'approved' : 'rejected';
    toast.success(`Return #${confirmAction.item?.id} has been ${action}`);
    setConfirmAction({ open: false, type: null, item: null });
  };

  return (
    <div className="space-y-6 pb-8">
      <PageHeader title="Returns & Refunds" subtitle={`${returns.length} return requests`} />

      <div className="flex gap-2 overflow-x-auto">
        {tabs.map((tab) => (
          <button key={tab.key} onClick={() => setActiveTab(tab.key)}
            className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-medium whitespace-nowrap transition-all ${
              activeTab === tab.key ? 'bg-[#2563EB] text-white shadow-sm' : 'bg-white text-gray-500 border border-gray-200 hover:bg-gray-50'}`}>
            <tab.icon size={16} /> {tab.label}
          </button>
        ))}
      </div>

      <SearchFilter searchValue={searchQuery} onSearchChange={setSearchQuery} placeholder="Search by order ID or customer..." />

      <div className="space-y-4">
        {filtered.map((ret, i) => (
          <motion.div key={ret.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
            <Card className="hover:border-gray-200 transition-colors">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-2">
                    <span className="text-sm font-bold text-blue-600">#{ret.id}</span>
                    <StatusBadge status={ret.status} />
                    <span className="text-xs text-gray-400">Order #{ret.orderId}</span>
                  </div>
                  <p className="text-sm font-medium text-gray-900">{ret.product.title}</p>
                  <p className="text-xs text-gray-500 mt-1">Customer: {ret.customer.name} • Requested: {getRelativeTime(new Date(ret.requestedAt))}</p>
                  <p className="text-xs text-gray-500 mt-1">Reason: <span className="text-gray-700">{ret.reason}</span></p>
                  <p className="text-sm font-semibold text-gray-900 mt-2">Refund: {formatCurrency(ret.refundAmount)}</p>
                </div>
                {ret.status === 'pending' && (
                  <div className="flex items-center gap-2">
                    <Button variant="success" size="sm" icon={CheckCircle} onClick={() => handleAction('approve', ret)}>Approve</Button>
                    <Button variant="danger" size="sm" icon={XCircle} onClick={() => handleAction('reject', ret)}>Reject</Button>
                  </div>
                )}
              </div>

              {/* Timeline */}
              {ret.timeline && ret.timeline.length > 0 && (
                <div className="mt-4 pt-4 border-t border-gray-50">
                  <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Timeline</p>
                  <div className="space-y-2">
                    {ret.timeline.map((entry, j) => (
                      <div key={j} className="flex items-center gap-3 text-xs">
                        <span className="w-1.5 h-1.5 rounded-full bg-blue-400" />
                        <span className="text-gray-500">{formatDate(entry.date, 'long')}</span>
                        <span className="text-gray-700">{entry.event}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </Card>
          </motion.div>
        ))}

        {filtered.length === 0 && (
          <div className="text-center py-16">
            <RotateCcw size={40} className="text-gray-200 mx-auto mb-4" />
            <p className="text-gray-500">No return requests found</p>
          </div>
        )}
      </div>

      <ConfirmModal
        isOpen={confirmAction.open}
        onClose={() => setConfirmAction({ open: false, type: null, item: null })}
        onConfirm={confirmHandler}
        type={confirmAction.type === 'approve' ? 'save' : 'warning'}
        title={confirmAction.type === 'approve' ? 'Approve Return' : 'Reject Return'}
        message={`Are you sure you want to ${confirmAction.type} this return request?`}
        confirmLabel={confirmAction.type === 'approve' ? 'Approve' : 'Reject'}
      />
    </div>
  );
};

