/* ─────────────────────────────────────────────
   Category list — project ki actual categories
   ───────────────────────────────────────────── */
const CATEGORIES = [
  { id: 'for-you',     label: 'You Buy',     Svg: IconForYou     },
  { id: 'beauty',      label: 'Beauty',      Svg: IconBeauty     },
  { id: 'gifting',     label: 'Gifting',     Svg: IconGifting    },
  { id: 'electronics', label: 'Electronics', Svg: IconElectronics},
  { id: 'jewellery',   label: 'Jewellery',   Svg: IconJewellery  },
  { id: 'toys',        label: 'Toys',        Svg: IconToys       },
  { id: 'stationery',  label: 'Stationery',  Svg: IconStationery },
  { id: 'fashion',     label: 'Fashion',     Svg: IconFashion    },
  { id: 'electrical',  label: 'Electrical',  Svg: IconElectrical },
];

const getMithilakartHeaderBg = (category) => {
  switch (category) {
    case 'Beauty':
      return 'bg-[#F9A8D4]'; // Soft Rose Pink
    case 'Gifting':
      return 'bg-[#D8B4FE]'; // Soft Purple
    case 'Electronics':
      return 'bg-[#93C5FD]'; // Soft Blue
    case 'Jewellery':
      return 'bg-[#FDBA74]'; // Soft Orange/Peach
    case 'Toys':
      return 'bg-[#99F6E4]'; // Soft Teal
    case 'Stationery':
      return 'bg-[#C7D2FE]'; // Soft Indigo
    case 'Fashion':
      return 'bg-[#FCA5A5]'; // Soft Red
    case 'Electrical':
      return 'bg-[#FEF08A]'; // Soft Yellow
    case 'You Buy':
    default:
      return 'bg-primary-green'; // Default Green (Mithilakart default brand color)
  }
};

const getMithilakartActiveTextColor = (category) => {
  switch (category) {
    case 'Beauty':
      return 'text-[#A2396B]';
    case 'Gifting':
      return 'text-[#5E32A6]';
    case 'Electronics':
      return 'text-[#1C4E9C]';
    case 'Jewellery':
      return 'text-[#A04E15]';
    case 'Toys':
      return 'text-[#0D7F77]';
    case 'Stationery':
      return 'text-[#3B4CA8]';
    case 'Fashion':
      return 'text-[#B62626]';
    case 'Electrical':
      return 'text-[#9B7C16]';
    default:
      return 'text-[#3E5A44]';
  }
};

import { useTranslation } from 'react-i18next';

const CategoryNavbar = ({ selectedCategory, setSelectedCategory }) => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const location = useLocation();

  const handleSelect = (cat) => {
    setSelectedCategory(cat.label);
    if (cat.id === 'toys') {
      navigate('/toys');
      return;
    }
    if (cat.id === 'beauty') {
      navigate('/beauty');
      return;
    }
    if (!location.pathname.includes('/home')) {
      navigate('/home');
    }
  };

  return (
    <div
      className={`flex items-center overflow-x-auto no-scrollbar pt-0.5 pb-1.5 px-2 gap-1 md:pt-1 md:pb-2 md:px-3 md:gap-1.5 transition-colors duration-300 ${getMithilakartHeaderBg(selectedCategory)}`}
      role="navigation"
      aria-label="Product categories"
    >
      {CATEGORIES.map((cat) => {
        const isActive = selectedCategory === cat.label;

        return (
          <motion.button
            key={cat.id}
            onClick={() => handleSelect(cat)}
            whileTap={{ scale: 0.92 }}
            className={`flex flex-col items-center justify-center flex-shrink-0 w-[48px] h-[52px] md:w-[58px] md:h-[64px] rounded-[8px] md:rounded-[12px] transition-all duration-200 focus:outline-none ${
              isActive 
                ? 'bg-white/85 backdrop-blur-md shadow-[inset_0_1.5px_2px_rgba(255,255,255,0.6),0_3px_8px_rgba(8,66,36,0.05)] border border-white' 
                : 'bg-white/35 border border-white/10'
            }`}
            aria-pressed={isActive}
            aria-label={cat.label}
          >
            {/* SVG Icon */}
            <div
              className={`mb-0.5 md:mb-1 leading-none transition-colors duration-200 ${
                isActive ? getMithilakartActiveTextColor(selectedCategory) : 'text-primary-dark/80'
              }`}
            >
              <cat.Svg size={18} active={isActive} className="w-[14px] h-[14px] md:w-[18px] md:h-[18px]" />
            </div>

            {/* Label */}
            <span
              className={`text-[8px] md:text-[9.5px] tracking-tight whitespace-nowrap leading-tight text-center transition-colors duration-200 ${
                isActive ? `font-black ${getMithilakartActiveTextColor(selectedCategory)}` : 'font-extrabold text-primary-dark/80'
              }`}
            >
              {t(`categories.${cat.id}`)}
            </span>
          </motion.button>
        );
      })}
    </div>
  );
};

export default CategoryNavbar;

import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Plane, Zap, Truck } from 'lucide-react';
import { useTranslation } from 'react-i18next';

const HeaderTabs = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const location = useLocation();

  const isMithilakFlow = localStorage.getItem('isMithilakFlow') === 'true';
  const isQuickShopActive = location.pathname.includes('/quick-shop') && !isMithilakFlow;
  const isMithilakActive = location.pathname.includes('/mithilak') || (location.pathname.includes('/quick-shop') && isMithilakFlow);
  const isFreshGroceryActive = location.pathname.includes('/fresh-grocery');
  const isMithilakartActive = !isQuickShopActive && !isMithilakActive && !isFreshGroceryActive;

  const isHeaderLight = isMithilakartActive || isFreshGroceryActive;

  const handleTabClick = (path, isQuick) => {
    localStorage.setItem('isQuickShopFlow', isQuick ? 'true' : 'false');
    if (path === '/mithilak') {
      localStorage.setItem('isMithilakFlow', 'true');
    } else {
      localStorage.setItem('isMithilakFlow', 'false');
    }
    if (path === '/fresh-grocery') {
      localStorage.setItem('isFreshGroceryFlow', 'true');
    } else {
      localStorage.setItem('isFreshGroceryFlow', 'false');
    }
    navigate(path);
  };

  return (
    <div className="px-2 pt-1 pb-0.5 md:px-4 md:pt-4 md:pb-2.5 grid grid-cols-4 gap-1.5 md:gap-3">
      {/* ── Tab 1: Mithilakart ── */}
      <motion.div
        whileTap={{ scale: 0.95 }}
        onClick={() => handleTabClick('/home', false)}
        className={`flex flex-col items-center justify-center py-1 md:py-1.5 rounded-lg border min-h-[42px] md:min-h-[60px] h-auto gap-0.5 md:gap-1.5 cursor-pointer transition-all duration-300 ${
          isMithilakartActive
            ? 'bg-white text-[#3E5A44] border-white shadow-md scale-102 z-10'
            : isFreshGroceryActive
              ? 'bg-white/35 text-[#7A3E17]/85 border-white/15 hover:bg-white/45'
              : isHeaderLight
                ? 'bg-black/5 text-[#3E5A44]/80 border-black/5 hover:bg-black/10'
                : 'bg-white/15 text-white/90 border-white/10 hover:bg-white/25'
        }`}
      >
        <div className="w-[32px] h-[14px] md:w-[48px] md:h-[22px] flex items-center justify-center">
          <img
            src="/mthibg.png"
            alt="Icon"
            className={`h-full w-full object-contain transition-all duration-300 ${
              isMithilakartActive 
                ? 'brightness-0' 
                : isFreshGroceryActive 
                  ? 'brightness-0' 
                  : isHeaderLight 
                    ? 'brightness-50' 
                    : 'brightness-0'
            }`}
          />
        </div>
        <span className={`font-extrabold text-[11px] md:text-[14px] italic tracking-tight leading-none mb-0.5 transition-colors duration-300 ${
          isMithilakartActive 
            ? 'text-[#3E5A44]' 
            : isFreshGroceryActive
              ? 'text-[#7A3E17]/85'
              : isHeaderLight 
                ? 'text-[#3E5A44]/80' 
                : 'text-white'
        }`}>
          {t('home.title')}
        </span>
      </motion.div>

      {/* ── Tab 2: Quick Shop ── */}
      <motion.div
        whileTap={{ scale: 0.95 }}
        onClick={() => handleTabClick('/quick-shop', true)}
        className={`flex flex-col items-center justify-center py-1 md:py-1.5 rounded-lg border min-h-[42px] md:min-h-[60px] h-auto gap-0.5 md:gap-1.5 cursor-pointer transition-all duration-300 ${
          isQuickShopActive
            ? 'bg-white text-[#d6186d] border-white shadow-md scale-102 z-10'
            : isFreshGroceryActive
              ? 'bg-white/35 text-[#7A3E17]/85 border-white/15 hover:bg-white/45'
              : isMithilakartActive
                ? 'bg-white/20 text-white border-white/10 hover:bg-white/30'
                : isHeaderLight
                  ? 'bg-black/5 text-[#d6186d]/85 border-black/5 hover:bg-black/10'
                  : 'bg-white/15 text-white/90 border-white/10 hover:bg-white/25'
        }`}
      >
        <div
          className={`w-[16px] h-[16px] md:w-[26px] md:h-[26px] rounded-full flex items-center justify-center shadow-xs transition-all duration-300 ${
            isQuickShopActive 
              ? 'bg-[#d6186d] text-white' 
              : isFreshGroceryActive
                ? 'bg-[#7A3E17]/15 text-[#7A3E17]'
                : isMithilakartActive
                  ? 'bg-white/30 text-white'
                  : isHeaderLight
                    ? 'bg-[#d6186d]/15 text-[#d6186d]'
                    : 'bg-white text-[#d6186d]'
          }`}
        >
          <Truck size={10} className="w-[10px] h-[10px] md:w-[13px] md:h-[13px]" />
        </div>
        <span
          className={`text-[10px] md:text-[14px] font-extrabold tracking-tight leading-none text-center px-0.5 mb-0.5 transition-colors duration-300 ${
            isQuickShopActive 
              ? 'text-[#d6186d]' 
              : isFreshGroceryActive
                ? 'text-[#7A3E17]/85'
                : isMithilakartActive
                  ? 'text-white/90'
                  : isHeaderLight 
                    ? 'text-[#d6186d]/85' 
                    : 'text-white'
          }`}
        >
          {t('nav.quickShop')}
        </span>
      </motion.div>

      {/* ── Tab 3: Mithilak ── */}
      <motion.div
        whileTap={{ scale: 0.95 }}
        onClick={() => handleTabClick('/mithilak', false)}
        className={`flex flex-col items-center justify-center py-1 md:py-1.5 rounded-lg border min-h-[42px] md:min-h-[60px] h-auto gap-0.5 md:gap-1.5 cursor-pointer transition-all duration-300 ${
          isMithilakActive
            ? 'bg-white text-[#207C8A] border-white shadow-md scale-102 z-10'
            : isFreshGroceryActive
              ? 'bg-white/35 text-[#7A3E17]/85 border-white/15 hover:bg-white/45'
              : isMithilakartActive
                ? 'bg-white/20 text-white border-white/10 hover:bg-white/30'
                : isHeaderLight
                  ? 'bg-black/5 text-[#207C8A]/80 border-black/5 hover:bg-black/10'
                  : 'bg-white/15 text-white/90 border-white/10 hover:bg-white/25'
        }`}
      >
        <div className="flex items-center justify-center">
          <Plane 
            size={22} 
            className={`w-[14px] h-[14px] md:w-[22px] md:h-[22px] transition-all duration-300 ${
              isMithilakActive 
                ? "text-[#207C8A] fill-[#207C8A]/20" 
                : isFreshGroceryActive
                  ? "text-[#7A3E17]/85"
                  : isMithilakartActive
                    ? "text-white/90"
                    : isHeaderLight 
                      ? "text-[#207C8A]" 
                      : "text-white"
            }`} 
          />
        </div>
        <span className={`text-[11px] md:text-[14px] font-extrabold tracking-tight leading-none mb-0.5 transition-colors duration-300 ${
          isMithilakActive 
            ? 'text-[#207C8A]' 
            : isFreshGroceryActive
              ? 'text-[#7A3E17]/85'
              : isMithilakartActive
                ? 'text-white/90'
                : isHeaderLight 
                  ? 'text-[#207C8A]/80' 
                  : 'text-white'
        }`}>
          {t('nav.mithilak')}
        </span>
      </motion.div>

      {/* ── Tab 4: Fresh/Grocery ── */}
      <motion.div
        whileTap={{ scale: 0.95 }}
        onClick={() => handleTabClick('/fresh-grocery', true)}
        className={`flex flex-col items-center justify-center py-0.5 md:py-1 rounded-lg border min-h-[42px] md:min-h-[60px] h-auto cursor-pointer transition-all duration-300 ${
          isFreshGroceryActive
            ? 'bg-white text-[#7A3E17] border-white shadow-md scale-102 z-10'
            : isMithilakartActive
              ? 'bg-white/20 text-white border-white/10 hover:bg-white/30'
              : isHeaderLight
                ? 'bg-black/5 text-[#7A3E17]/85 border-black/5 hover:bg-black/10'
                : 'bg-white/15 text-white/90 border-white/10 hover:bg-white/25'
        }`}
      >
        <span className={`text-[10px] md:text-[13.5px] font-extrabold tracking-tight leading-tight text-center px-0.5 transition-colors duration-300 flex flex-col items-center justify-center ${
          isFreshGroceryActive 
            ? 'text-[#7A3E17]' 
            : isMithilakartActive
              ? 'text-white/90'
              : isHeaderLight
                ? 'text-[#7A3E17]'
                : 'text-white'
        }`}>
          {t('nav.groceriesAndFresh').split(' ').map((word, idx) => (
            <span key={idx} className="block leading-none">{word}</span>
          ))}
        </span>
      </motion.div>
    </div>
  );
};

export default HeaderTabs;

import React from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Bell, Heart, ShoppingCart } from 'lucide-react';

const HeaderTop = ({ cartCount = 0 }) => {
  return (
    <div className="px-3 py-1 flex items-center justify-between">
      {/* ── Logo ── */}
      <Link to="/vendor/home" className="flex items-center flex-shrink-0">
        <motion.img
          src="/mthibg.png"
          alt="Mithilakart"
          className="h-10 w-28 object-contain object-left"
          whileTap={{ scale: 0.95 }}
        />
      </Link>

      {/* ── Action Icons ── */}
      <div className="flex items-center gap-0 flex-shrink-0">
        <motion.div whileTap={{ scale: 0.82 }}>
          <Link to="/vendor/notifications" aria-label="Notifications" className="p-1.5 block">
            <Bell size={20} strokeWidth={1.8} className="text-primary-dark" />
          </Link>
        </motion.div>

        <motion.div whileTap={{ scale: 0.82 }}>
          <Link to="/vendor/wishlist" aria-label="Wishlist" className="p-1.5 block">
            <Heart size={20} strokeWidth={1.8} className="text-primary-dark" />
