      <div className={`sticky top-0 z-50 backdrop-blur-md border-b p-3 transition-all ${isDarkMode ? 'bg-black/90 border-[var(--color-gold)]/20' : 'bg-white/90 border-gray-200 shadow-sm'}`}>
