          <button onClick={() => navigate(-1)} className={isDarkMode ? 'text-[var(--color-gold)]' : 'text-slate-800'}>
            <ArrowLeft size={24} />
          </button>
          <div className="flex-1">
            <SearchInput
              type="text"
              placeholder="Search items, brands, categories..."
              rightElement={
                <div className="flex items-center gap-3 text-gray-550">
                  <Camera 
                    size={18} 
                    className="cursor-pointer hover:text-slate-750 transition-colors" 
                    onClick={() => {
                      toast.loading("Analyzing image search...", { id: "deals-img" });
                      setTimeout(() => {
                        toast.dismiss("deals-img");
                        toast.success("Image search completed!");
                        navigate('/search?q=Handicraft');
                      }, 1500);
                    }}
                  />
                  <Mic size={18} className="cursor-pointer hover:text-slate-750" />
                  <Scan 
                    size={18} 
                    className="cursor-pointer hover:text-slate-750 transition-colors"
                    onClick={() => {
                      toast.loading("Simulating barcode scanner...", { id: "deals-scan" });
                      setTimeout(() => {
                        toast.dismiss("deals-scan");
                        toast.success("Barcode recognized successfully!");
                        navigate('/search?q=Painting');
                      }, 1500);
                    }}
                  />
                </div>
              }
            />
          </div>
        </div>

        {/* Adaptive Page Title */}
        <div className="mt-4 px-1">
           <h1 className={`text-lg font-black uppercase tracking-[2px] ${isDarkMode ? 'text-[var(--color-gold)]' : 'text-slate-900'}`}>{sectionTitle}</h1>
           <div className={`w-10 h-1 mt-1 rounded-full ${isDarkMode ? 'bg-[var(--color-gold)] shadow-[0_0_10px_rgba(226,167,80,0.5)]' : 'bg-primary-dark shadow-sm'}`}></div>
        </div>
      </div>

      {/* Product List - Adaptive Grid */}
      <div className={`grid grid-cols-2 gap-px border-b ${isDarkMode ? 'bg-[var(--card-border)]/20 border-[var(--card-border)]/20' : 'bg-gray-200 border-gray-200'}`}>
         {products.map((product) => (
           <div 
             key={product.id} 
             onClick={() => navigate('/vendor/product-detail', { state: { product } })}
             className={`p-4 flex flex-col relative group border-[0.5px] transition-all ${isDarkMode ? 'bg-black border-[var(--card-border)]/10' : 'bg-white border-gray-100'}`}
           >
              {/* Adaptive Wishlist Button */}
              <button 
                onClick={(e) => toggleWishlist(product.id, e)}
                className={`absolute top-3 right-3 z-10 p-2 rounded-full backdrop-blur-md border shadow-lg active:scale-90 transition-all ${isDarkMode ? 'bg-black/40 border-white/5' : 'bg-white/80 border-gray-100'}`}
              >
                 <Heart size={18} className={wishlisted[product.id] ? "fill-red-500 text-red-500" : (isDarkMode ? "text-white/60" : "text-gray-400")} />
              </button>

              {/* Adaptive Image Container */}
              <div className={`aspect-square w-full mb-4 flex items-center justify-center p-4 relative rounded-2xl border overflow-hidden transition-all ${isDarkMode ? 'bg-[#0a0a0a] border-white/5' : 'bg-gray-50 border-gray-200/50'}`}>
                 <img src={product.image} alt={product.name} className={`w-full h-full object-contain group-hover:scale-110 transition-transform duration-500 ${isDarkMode ? 'mix-blend-lighten' : ''}`} />
                 
                 {/* Adaptive Quick Add Button */}
                 <button 
                   onClick={(e) => handleAddToCart(product, e)}
                   className={`absolute bottom-2 right-2 w-10 h-10 rounded-full flex items-center justify-center shadow-lg active:scale-90 transition-all hover:scale-110 z-20 ${isDarkMode ? 'bg-[var(--color-gold)] shadow-[0_5px_15px_rgba(226,167,80,0.4)]' : 'bg-primary-dark text-white shadow-[0_5px_15px_rgba(37,99,235,0.3)]'}`}
                 >
                    <Plus size={24} className={isDarkMode ? "text-black" : "text-white"} />
                 </button>
              </div>

              {/* Info */}
              <div className="space-y-1.5 px-1">
                 <div className="flex items-center gap-2">
                    <span className="bg-[#cc0c39] text-white text-[9px] font-black px-2 py-0.5 rounded-sm uppercase tracking-tighter shadow-md">{product.discount}</span>
                    <span className={`text-[9px] font-black uppercase tracking-widest ${isDarkMode ? 'text-[var(--color-gold)]' : 'text-primary-dark'}`}>{product.label}</span>
                 </div>

                 <div className="flex items-baseline gap-2">
                    <span className="text-[10px] font-black text-gray-500 mt-1 uppercase">₹</span>
                    <span className={`text-xl font-black tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{product.price}</span>
                    <span className="text-[10px] text-gray-500 line-through font-bold">₹{product.mrp}</span>
                 </div>

                 <h3 className={`text-[12px] font-black line-clamp-2 leading-relaxed h-[36px] tracking-tight ${isDarkMode ? 'text-white/90' : 'text-slate-700'}`}>
                    {product.name}
                 </h3>

                 <button className={`text-[11px] font-black transition-colors uppercase tracking-widest mt-1 ${isDarkMode ? 'text-blue-400 hover:text-blue-300' : 'text-primary-dark hover:text-blue-700'}`}>
                    Shop {product.brand} deals
                 </button>

                 <div className={`flex items-center justify-between mt-2 pt-2 border-t ${isDarkMode ? 'border-white/5' : 'border-gray-100'}`}>
                    <div className="flex items-center gap-1">
                       <div className="flex gap-0.5">
                          {[1,2,3,4].map(i => <Star key={i} size={10} className={`${isDarkMode ? 'text-[var(--color-gold)] fill-[var(--color-gold)]' : 'text-orange-400 fill-orange-400'} shadow-sm`} />)}
                          <Star size={10} className="text-gray-300 fill-gray-300" />
                       </div>
                       <span className="text-[10px] text-gray-500 font-black">({product.reviews})</span>
                    </div>
                 </div>
              </div>
           </div>
         ))}
      </div>
    </motion.div>
  );
};

export default DealsPage;

import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { X, Mail, Phone } from 'lucide-react';
import { motion } from 'framer-motion';

const ForgotPassword = () => {
  const navigate = useNavigate();
  const [inputVal, setInputVal] = useState('');
  const [useEmail, setUseEmail] = useState(true);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!inputVal.trim()) {
      setError(useEmail ? 'Please enter your email address' : 'Please enter your phone number');
      return;
    }
    setError('');
    setSubmitted(true);
  };

  // Inline SVG pattern for background (matching Login.jsx)
  const backgroundPattern = `data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path d="M10 20c2-3 5-5 8-5s6 2 8 5-2 8-5 8-6-2-8-5zm30 20c2-3 5-5 8-5s6 2 8 5-2 8-5 8-6-2-8-5zM25 45c1-2 3-3 5-3s4 1 5 3-1 4-3 4-4-1-5-3zM45 15c1-2 3-3 5-3s4 1 5 3-1 4-3 4-4-1-5-3z" fill="%23ffffff" fill-opacity="0.12" fill-rule="evenodd"/></svg>`;

  return (
    <div className="min-h-screen flex flex-col items-center justify-between p-4 md:p-6 bg-[#f7f4eb] relative overflow-hidden">
      {/* Background Image with lower opacity */}
      <div 
        className="absolute inset-0 bg-cover bg-center bg-no-repeat opacity-25 pointer-events-none"
        style={{ backgroundImage: `url('/login_signup_bg.png')` }}
      />

      {/* Top Header Row */}
      <div className="w-full max-w-[420px] flex items-center justify-between z-10">
        <button 
          onClick={() => navigate('/login')}
          className="bg-[#F26522]/10 hover:bg-[#F26522]/20 text-[#F26522] p-2 rounded-full backdrop-blur-md active:scale-95 transition-all"
        >
          <X size={20} strokeWidth={2.5} />
        </button>
        <div className="flex items-center gap-2">
          <img src="/logomith-removebg-preview.png" alt="Mithilakart" className="h-8 w-auto object-contain" />
          <span className="text-[#F26522] font-bold tracking-wider text-sm">MITHILAKART</span>
        </div>
        <div className="w-9"></div> {/* Spacer for symmetry */}
      </div>

      {/* Main card */}
      <div className="w-full max-w-[420px] bg-[#FFF5EE]/95 rounded-[32px] px-6 py-8 shadow-2xl border border-white/40 backdrop-blur-md z-10 my-6">
        <div className="text-center mb-8">
          <h2 className="text-3xl font-extrabold text-[#F26522]">
            Reset Password
          </h2>
          <p className="text-[#F26522]/80 text-[13px] font-semibold mt-1">
            {submitted ? 'Check your instructions below' : 'Enter your details to receive a recovery link'}
          </p>
        </div>

        {!submitted ? (
          <form onSubmit={handleSubmit} className="space-y-5">
            {error && (
              <div className="bg-red-50 border border-red-100 text-red-500 text-[11px] font-bold p-3.5 rounded-2xl text-center uppercase tracking-wider">
                {error}
              </div>
            )}

            {/* Input Box */}
            <div className="space-y-2">
              <label className="text-[12px] font-black text-[#F26522] uppercase tracking-wider pl-1 block">
                {useEmail ? 'Email Address' : 'Phone Number'}
              </label>
              <div className="relative">
                <span className="absolute inset-y-0 left-0 pl-4.5 flex items-center text-[#F26522]/70">
                  {useEmail ? <Mail size={18} /> : <Phone size={18} />}
                </span>
                <input 
                  type={useEmail ? 'email' : 'tel'}
                  value={inputVal}
                  onChange={(e) => setInputVal(e.target.value)}
                  placeholder={useEmail ? 'Enter your email address' : 'Enter your phone number'}
                  className="w-full pl-12 pr-4.5 py-4 bg-[#FFF5EE] border border-[#F26522]/35 text-slate-800 rounded-2xl focus:outline-none focus:ring-2 focus:ring-[#F26522] focus:border-transparent transition-all placeholder-[#F26522]/40 text-[14.5px] font-bold shadow-2xs"
                />
              </div>
            </div>

            {/* Submit Button */}
            <motion.button
              type="submit"
              whileTap={{ scale: 0.98 }}
              className="w-full bg-[#F26522] text-white hover:bg-[#d45014] py-4 rounded-2xl font-black text-[13.5px] uppercase tracking-wider transition-all flex items-center justify-center gap-2.5 shadow-md active:scale-[0.98] cursor-pointer"
            >
              Send Reset Link
            </motion.button>

            {/* Toggle Input Type Link */}
            <div className="text-right px-1">
              <button
                type="button"
                onClick={() => {
                  setUseEmail(!useEmail);
                  setInputVal('');
                  setError('');
                }}
                className="text-[12px] font-bold text-[#F26522] hover:underline"
              >
                {useEmail ? 'Use Phone Number Instead' : 'Use Email Address Instead'}
              </button>
            </div>
          </form>
        ) : (
          <div className="space-y-6 text-center">
            <div className="bg-[#FFF5EE] border border-[#F26522]/35 p-5 rounded-2xl text-[14px] font-bold text-[#F26522] leading-relaxed">
              We've sent a recovery link to <span className="underline">{inputVal}</span>. Please check your inbox and follow the instructions to set a new password.
            </div>

            <motion.button
              onClick={() => navigate('/login')}
              whileTap={{ scale: 0.98 }}
              className="w-full bg-[#F26522] text-white hover:bg-[#d45014] py-4 rounded-2xl font-black text-[13.5px] uppercase tracking-wider transition-all flex items-center justify-center gap-2.5 shadow-md active:scale-[0.98] cursor-pointer"
            >
              Return to Login
            </motion.button>
          </div>
        )}

        <div className="text-center mt-5 text-[12px] font-bold text-[#F26522]/80">
          Remembered your password?{' '}
          <Link to="/login" className="text-[#F26522] hover:underline">
            Log in here!
          </Link>
        </div>
      </div>

      {/* Footer Logo & Styling */}
      <div className="flex flex-col items-center gap-1 my-4 z-10">
        <img 
          src="/mthibg.png" 
          alt="Mithilakart" 
          className="h-16 w-auto object-contain"
        />
        <div className="flex items-center text-[14px] font-bold text-black tracking-wide italic">
          Mithilakart<span className="text-[10px] align-super ml-0.5">™</span>
        </div>
      </div>
    </div>
  );
};

export default ForgotPassword;

