    return {
      'Home': homeBanners,
      'Toys': homeBanners,
      'Beauty': homeBanners,
      'Art. Jewellery': homeBanners,
      '1g Gold': homeBanners,
      'Cosmetics': homeBanners,
      'Fashion': homeBanners
    };
  }, []);

  const data = useMemo(() => ({
    ratings: [
      { name: 'SONATA...', fullName: 'SONATA NP7987YM06W So...', date: 'Delivered on Apr 13, 2026', img: JewelleryImg },
