      let nextS = s - 1;
      let nextM = m;
      let nextH = h;
      
      if (nextS < 0) {
        nextS = 59;
        nextM -= 1;
      }
      if (nextM < 0) {
        nextM = 59;
        nextH -= 1;
      }
      if (nextH < 0) {
        nextH = 2;
        nextM = 45;
        nextS = 12;
      }

      setTimeLeft({
        h: String(nextH).padStart(2, '0'),
        m: String(nextM).padStart(2, '0'),
        s: String(nextS).padStart(2, '0')
      });
    }, 1000);
