        </div>
      </div>
      <label className="flex items-center gap-2 cursor-pointer">
        <input
          type="checkbox"
          checked={formData.active}
          onChange={e => setFormData(p => ({ ...p, active: e.target.checked }))}
          className="accent-blue-500 w-4 h-4"
        />
