                    <input 
                      type="text" 
                      readOnly={!isEditing}
                      value={formData[field.key] || ''}
                      onChange={(e) => handleChange(e, field.key)}
                      className={`flex-1 bg-transparent text-sm font-bold outline-none ${isEditing ? 'text-slate-900' : 'text-slate-500'}`}
                    />
