  useEffect(() => {
    const handler = (e) => {
      if (notifRef.current && !notifRef.current.contains(e.target)) setShowNotifications(false);
      if (profileRef.current && !profileRef.current.contains(e.target)) setShowProfile(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  // Build breadcrumb
  const getBreadcrumb = () => {
    const path = location.pathname.replace('/seller/', '').replace('/seller', '');
    if (!path || path === 'dashboard') return null;
    const parts = path.split('/').filter(Boolean);
    return parts.map((p) => p.charAt(0).toUpperCase() + p.slice(1).replace(/-/g, ' '));
  };

  // Get current page title
  const getPageTitle = () => {
    const path = location.pathname;
    for (const group of SIDEBAR_MENU) {
      for (const item of group.items) {
        if (item.path === path) return item.name;
      }
    }
    return 'Dashboard';
  };

  // Search navigation links
  const allLinks = SIDEBAR_MENU.flatMap((g) => g.items).filter((i) => i.path !== '#logout');
  const filteredLinks = searchQuery
    ? allLinks.filter((l) => l.name.toLowerCase().includes(searchQuery.toLowerCase()))
    : [];

  return (
    <header className="sticky top-0 z-30 h-16 bg-[var(--seller-topbar-bg,#fff)] border-b border-[var(--seller-border-light,#F3F4F6)] px-4 sm:px-6 lg:px-8 flex items-center justify-between gap-4">
      {/* Left: Menu + Title */}
      <div className="flex items-center gap-4">
        {/* Mobile Menu Toggle */}
        <button
          onClick={onMenuClick}
          className="lg:hidden p-2 rounded-xl hover:bg-gray-100 transition-colors"
          aria-label="Open menu"
        >
          <Menu size={20} className="text-gray-600" />
        </button>

        {/* Page Title + Breadcrumb */}
        <div className="hidden sm:block">
          <h2 className="text-base font-semibold text-[var(--seller-text,#111827)]">{getPageTitle()}</h2>
          {getBreadcrumb() && (
            <div className="flex items-center gap-1.5 text-[11px] text-[var(--seller-subtext,#6B7280)]">
              <span className="hover:text-blue-600 cursor-pointer" onClick={() => navigate('/seller/dashboard')}>Home</span>
              {getBreadcrumb().map((part, i) => (
                <React.Fragment key={i}>
                  <ChevronRight size={10} />
                  <span className={i === getBreadcrumb().length - 1 ? 'text-[var(--seller-text,#111827)] font-medium' : ''}>{part}</span>
                </React.Fragment>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Right: Search + Actions */}
      <div className="flex items-center gap-2 sm:gap-3">
        {/* Search */}
        <div className="relative hidden md:block">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => { setSearchQuery(e.target.value); setShowSearch(e.target.value.length > 0); }}
            onFocus={() => searchQuery.length > 0 && setShowSearch(true)}
            onBlur={() => setTimeout(() => setShowSearch(false), 200)}
            placeholder="Quick navigate..."
            className="w-52 lg:w-72 pl-9 pr-8 py-2 text-sm bg-[var(--seller-sidebar-hover,#F3F4F6)] border border-transparent
                       rounded-xl focus:ring-2 focus:ring-blue-100 focus:border-blue-200 focus:bg-white
                       outline-none transition-all placeholder:text-gray-400"
          />
          {searchQuery && (
            <button onClick={() => { setSearchQuery(''); setShowSearch(false); }} className="absolute right-2.5 top-1/2 -translate-y-1/2">
              <X size={14} className="text-gray-400" />
            </button>
          )}

          {/* Search Dropdown */}
          <AnimatePresence>
            {showSearch && (
              <motion.div
                initial={{ opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: 8 }}
                className="absolute top-full left-0 right-0 mt-2 bg-white border border-gray-200 rounded-xl shadow-lg z-50 overflow-hidden"
              >
                {filteredLinks.length > 0 ? filteredLinks.map((link) => (
                  <button
                    key={link.path}
                    onClick={() => { navigate(link.path); setSearchQuery(''); setShowSearch(false); }}
                    className="w-full flex items-center gap-3 px-4 py-3 text-sm text-gray-700 hover:bg-blue-50 transition-colors text-left"
                  >
                    <Search size={14} className="text-gray-400" />
                    {link.name}
                  </button>
                )) : (
                  <p className="px-4 py-6 text-sm text-gray-400 text-center">No results found</p>
                )}
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Theme Toggle */}
        <button
          onClick={toggleTheme}
          className="p-2.5 rounded-xl hover:bg-gray-100 transition-colors"
          aria-label={`Switch to ${theme === 'light' ? 'dark' : 'light'} mode`}
        >
          {theme === 'light' ? <Moon size={18} className="text-gray-500" /> : <Sun size={18} className="text-amber-400" />}
        </button>

        {/* Notifications */}
        <div className="relative" ref={notifRef}>
          <button
            onClick={() => { setShowNotifications(!showNotifications); setShowProfile(false); }}
            className={`relative p-2.5 rounded-xl transition-colors ${
              showNotifications ? 'bg-blue-50 text-blue-600' : 'hover:bg-gray-100 text-gray-500'
            }`}
            aria-label="Notifications"
          >
            <Bell size={18} />
            {unreadCount > 0 && (
              <span className="absolute -top-0.5 -right-0.5 w-5 h-5 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center border-2 border-white">
                {unreadCount > 9 ? '9+' : unreadCount}
              </span>
            )}
          </button>

          <AnimatePresence>
            {showNotifications && (
              <motion.div
                initial={{ opacity: 0, scale: 0.95, y: 8 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: 8 }}
                className="absolute right-0 top-full mt-2 w-80 bg-white border border-gray-200 rounded-2xl shadow-xl z-50 overflow-hidden"
              >
                <div className="flex items-center justify-between px-5 py-3.5 border-b border-gray-100">
                  <h4 className="text-sm font-semibold text-gray-900">Notifications</h4>
                  <span className="text-[10px] font-semibold text-blue-600 bg-blue-50 px-2 py-0.5 rounded-full">
                    {unreadCount} new
                  </span>
                </div>
                <div className="max-h-[360px] overflow-y-auto">
                  {dummyNotifications.slice(0, 5).map((n) => (
                    <div
                      key={n.id}
                      className={`px-5 py-3.5 border-b border-gray-50 last:border-0 hover:bg-gray-50 transition-colors cursor-pointer ${
                        !n.read ? 'bg-blue-50/30' : ''
                      }`}
                    >
                      <div className="flex items-start gap-3">
                        <div className={`w-2 h-2 mt-1.5 rounded-full flex-shrink-0 ${n.read ? 'bg-gray-200' : 'bg-blue-500'}`} />
                        <div>
                          <p className={`text-sm ${n.read ? 'text-gray-500' : 'text-gray-900 font-medium'}`}>{n.title}</p>
                          <p className="text-xs text-gray-400 mt-0.5 line-clamp-1">{n.message}</p>
                          <span className="text-[10px] text-gray-400 mt-1 block">{getRelativeTime(new Date(n.createdAt))}</span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
                <button
                  onClick={() => { navigate('/seller/notifications'); setShowNotifications(false); }}
                  className="w-full py-3 text-xs font-semibold text-blue-600 hover:bg-blue-50 transition-colors border-t border-gray-100"
                >
                  View All Notifications
                </button>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Profile Menu */}
        <div className="relative" ref={profileRef}>
          <button
            onClick={() => { setShowProfile(!showProfile); setShowNotifications(false); }}
            className="flex items-center gap-2.5 p-1.5 rounded-xl hover:bg-gray-100 transition-colors"
          >
            <div className="w-8 h-8 bg-gradient-to-br from-blue-600 to-indigo-600 rounded-xl flex items-center justify-center shadow-sm">
              <span className="text-white text-xs font-bold">
                {seller?.name?.charAt(0) || 'S'}
              </span>
            </div>
            <span className="hidden lg:block text-sm font-medium text-[var(--seller-text,#111827)]">
              {seller?.name?.split(' ')[0] || 'Seller'}
            </span>
          </button>

          <AnimatePresence>
            {showProfile && (
              <motion.div
                initial={{ opacity: 0, scale: 0.95, y: 8 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: 8 }}
                className="absolute right-0 top-full mt-2 w-56 bg-white border border-gray-200 rounded-xl shadow-xl z-50 overflow-hidden"
              >
                <div className="px-4 py-3 border-b border-gray-100">
                  <p className="text-sm font-semibold text-gray-900">{seller?.name || 'Seller'}</p>
                  <p className="text-xs text-gray-400">{seller?.email || 'seller@example.com'}</p>
                </div>
                <div className="p-1.5">
                  <button
                    onClick={() => { navigate('/seller/settings'); setShowProfile(false); }}
                    className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-gray-600 hover:bg-gray-50 rounded-lg transition-colors"
                  >
                    <User size={16} /> Profile
                  </button>
                  <button
                    onClick={() => { navigate('/seller/settings'); setShowProfile(false); }}
                    className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-gray-600 hover:bg-gray-50 rounded-lg transition-colors"
                  >
                    <Settings size={16} /> Settings
                  </button>
                  <button
                    onClick={async () => { await logout(); navigate('/seller/login'); }}
                    className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                  >
                    <LogOut size={16} /> Logout
                  </button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    </header>
  );
};

export default Topbar;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Store, Eye, EyeOff, Lock, Mail, X } from 'lucide-react';
import toast from 'react-hot-toast';
import { useSellerAuth } from '../../context/SellerAuthContext';

const SellerLogin = () => {
  const navigate = useNavigate();
  const { login } = useSellerAuth();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    if (email !== '9111966732' || password !== '123456') {
      toast.error('Invalid credentials');
      return;
    }
    
    setIsLoading(true);
    try {
      const result = await login('9111966732', '123456');
      if (result.success) {
        toast.success('Welcome back! Login successful.');
        navigate('/seller/dashboard');
      } else {
        toast.error(result.message || 'Login failed');
      }
    } catch {
      toast.error('Something went wrong');
    } finally {
      setIsLoading(false);
    }
  };

  // Inline SVG pattern for background
  const backgroundPattern = `data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path d="M10 20c2-3 5-5 8-5s6 2 8 5-2 8-5 8-6-2-8-5zm30 20c2-3 5-5 8-5s6 2 8 5-2 8-5 8-6-2-8-5zM25 45c1-2 3-3 5-3s4 1 5 3-1 4-3 4-4-1-5-3zM45 15c1-2 3-3 5-3s4 1 5 3-1 4-3 4-4-1-5-3z" fill="%23ffffff" fill-opacity="0.12" fill-rule="evenodd"/></svg>`;

  return (
    <div 
      className="min-h-screen flex flex-col items-center justify-between p-4 md:p-6 bg-gradient-to-br from-[#77eba3] to-[#42c585] relative overflow-hidden"
      style={{ backgroundImage: `radial-gradient(circle at 20% 30%, #77eba3 0%, #42c585 100%), url('${backgroundPattern}')` }}
    >
      {/* Background organic elements */}
      <div className="absolute top-10 left-10 opacity-20 pointer-events-none">
        <svg width="100" height="100" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M50 0C35 25 15 35 0 50C15 65 35 75 50 100C65 75 85 65 100 50C85 35 65 25 50 0Z" fill="white" />
        </svg>
      </div>
      <div className="absolute bottom-20 right-10 opacity-15 pointer-events-none">
        <svg width="140" height="140" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M20 80C40 80 60 60 80 20C60 20 40 40 20 80Z" fill="white" />
          <circle cx="50" cy="50" r="10" fill="white" />
        </svg>
      </div>

      {/* Top Header Row */}
      <div className="w-full max-w-[420px] flex items-center justify-between z-10">
        <button 
          onClick={() => navigate('/')}
          className="bg-white/20 hover:bg-white/30 text-white p-2 rounded-full backdrop-blur-md active:scale-95 transition-all"
        >
          <X size={20} strokeWidth={2.5} />
        </button>
        <div className="flex items-center gap-2">
          <img src="/logomith-removebg-preview.png" alt="Mithilakart" className="h-8 w-auto object-contain" />
          <span className="text-white font-bold tracking-wider text-sm">SELLER HUB</span>
        </div>
        <div className="w-9"></div>
      </div>

      {/* Main card */}
      <div className="w-full max-w-[420px] bg-[#f2fff5] rounded-[32px] px-6 py-8 shadow-2xl border border-white/40 z-10 my-6">
        <div className="text-center mb-8">
          <h2 className="text-3xl font-extrabold text-[#0a4a17]">
            Welcome back
          </h2>
          <p className="text-[#3b8a53] text-[13px] font-semibold mt-1">
            Grow Your Business with Mithilakart
          </p>
        </div>

        <form onSubmit={handleLoginSubmit} className="space-y-5">
          {/* Email / Username Field */}
          <div>
            <label className="block text-[12px] font-bold text-[#1f592c] mb-1.5 px-1 uppercase tracking-wider">
              Seller Username / Phone
            </label>
            <div className="relative">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-[#3b8a53]">
                <Mail size={18} />
              </span>
              <input
                type="text"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="e.g. 9111966732"
                className="w-full pl-11 pr-4 py-3 bg-[#e8fced] border-2 border-transparent focus:border-[#42c585] rounded-[16px] text-[14px] font-semibold text-[#0a4a17] placeholder-[#81b29a] focus:outline-none transition-all shadow-inner"
                required
              />
            </div>
          </div>

          {/* Password Field */}
          <div>
            <label className="block text-[12px] font-bold text-[#1f592c] mb-1.5 px-1 uppercase tracking-wider">
              Password
            </label>
            <div className="relative">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-[#3b8a53]">
                <Lock size={18} />
              </span>
              <input
                type={showPassword ? 'text' : 'password'}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••••••"
                className="w-full pl-11 pr-11 py-3 bg-[#e8fced] border-2 border-transparent focus:border-[#42c585] rounded-[16px] text-[14px] font-semibold text-[#0a4a17] placeholder-[#81b29a] focus:outline-none transition-all shadow-inner"
                required
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-4 top-1/2 -translate-y-1/2 text-[#3b8a53] hover:text-[#0a4a17] transition-colors"
              >
                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
              </button>
            </div>
          </div>

          {/* Sign In Button */}
          <motion.button
            type="submit"
            disabled={isLoading}
            whileTap={{ scale: 0.97 }}
            className="w-full py-4 bg-[#0c5c20] hover:bg-[#073f15] text-white rounded-[16px] text-[15px] font-bold uppercase tracking-wider shadow-lg hover:shadow-xl transition-all cursor-pointer flex items-center justify-center gap-2"
          >
            {isLoading ? (
              <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
            ) : (
              'Sign In to Seller Hub'
            )}
          </motion.button>
        </form>
      </div>

      {/* Footer Logo & Styling */}
      <div className="flex flex-col items-center gap-1 my-4 z-10">
        <img 
          src="/mthibg.png" 
          alt="Mithilakart" 
          className="h-10 w-auto object-contain"
        />
        <div className="flex items-center text-[18px] font-bold text-white tracking-wide italic">
          <span className="opacity-90">Mithila</span><span className="text-[#073f15]">kart</span>
        </div>
      </div>
    </div>
  );
};

export default SellerLogin;

/**
 * Coupon Management Page (List + Create inline)
 */
import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { motion } from 'framer-motion';
import { Plus, Ticket, Edit3, Trash2, Calendar, Percent, DollarSign, X } from 'lucide-react';
import { PageHeader, ConfirmModal, StatusBadge } from '../../components/common';
import { Card, Button, Badge } from '../../components/ui';
import { coupons } from '../../utils/dummyData';
import { formatCurrency, formatDate } from '../../utils/formatters';
import toast from 'react-hot-toast';

const CouponList = () => {
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [deleteModal, setDeleteModal] = useState({ open: false, coupon: null });
  const { register, handleSubmit, reset, formState: { errors } } = useForm();

  const onCreateCoupon = (data) => {
    toast.success(`Coupon "${data.code}" created successfully!`);
    setShowCreateForm(false);
    reset();
  };

  const inputClass = "w-full px-4 py-2.5 text-sm bg-white border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-100 focus:border-blue-300 transition-all";

  return (
    <div className="space-y-6 pb-8">
      <PageHeader title="Coupons" subtitle={`${coupons.length} coupons created`}>
        <Button icon={showCreateForm ? X : Plus} variant={showCreateForm ? 'secondary' : 'primary'}
                onClick={() => setShowCreateForm(!showCreateForm)}>
          {showCreateForm ? 'Cancel' : 'Create Coupon'}
        </Button>
      </PageHeader>

      {/* Create Coupon Form */}
      {showCreateForm && (
        <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }}>
          <Card title="Create New Coupon">
            <form onSubmit={handleSubmit(onCreateCoupon)} className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 mt-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Code *</label>
                <input {...register('code', { required: 'Code is required' })} placeholder="SALE50" className={inputClass} style={{ textTransform: 'uppercase' }} />
                {errors.code && <p className="text-xs text-red-500 mt-1">{errors.code.message}</p>}
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Type *</label>
                <select {...register('type', { required: true })} className={inputClass}>
                  <option value="percentage">Percentage (%)</option>
                  <option value="flat">Flat Amount (₹)</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Value *</label>
                <input type="number" {...register('value', { required: 'Value is required', min: 1 })} placeholder="50" className={inputClass} />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Min Order (₹)</label>
                <input type="number" {...register('minOrder')} placeholder="500" className={inputClass} />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Max Discount (₹)</label>
                <input type="number" {...register('maxDiscount')} placeholder="200" className={inputClass} />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Expiry Date *</label>
                <input type="date" {...register('expiryDate', { required: true })} className={inputClass} />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Usage Limit</label>
                <input type="number" {...register('usageLimit')} placeholder="100" className={inputClass} />
              </div>
              <div className="sm:col-span-2 lg:col-span-2 flex items-end">
                <Button type="submit" icon={Plus} fullWidth>Create Coupon</Button>
              </div>
            </form>
          </Card>
        </motion.div>
      )}

      {/* Coupon Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
        {coupons.map((coupon, i) => (
          <motion.div key={coupon.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
            <Card hover className="relative overflow-hidden">
              {/* Decorative stripe */}
              <div className={`absolute top-0 left-0 right-0 h-1 ${coupon.status === 'active' ? 'bg-[#2563EB]' : 'bg-gray-300'}`} />

              <div className="flex items-start justify-between mb-4">
                <div className="flex items-center gap-3">
                  <div className={`p-2.5 rounded-xl ${coupon.type === 'percentage' ? 'bg-purple-50' : 'bg-green-50'}`}>
                    {coupon.type === 'percentage' ? <Percent size={20} className="text-purple-600" /> : <DollarSign size={20} className="text-green-600" />}
                  </div>
                  <div>
                    <p className="text-lg font-bold text-gray-900 font-mono tracking-wider">{coupon.code}</p>
                    <p className="text-xs text-gray-400">{coupon.type === 'percentage' ? `${coupon.value}% off` : `₹${coupon.value} off`}</p>
                  </div>
                </div>
                <StatusBadge status={coupon.status} size="sm" />
              </div>

              <div className="space-y-2 text-sm">
                <div className="flex justify-between"><span className="text-gray-400">Min Order</span><span className="text-gray-700 font-medium">{formatCurrency(coupon.minOrder)}</span></div>
                <div className="flex justify-between"><span className="text-gray-400">Max Discount</span><span className="text-gray-700 font-medium">{formatCurrency(coupon.maxDiscount)}</span></div>
                <div className="flex justify-between"><span className="text-gray-400">Usage</span><span className="text-gray-700 font-medium">{coupon.usageCount}/{coupon.usageLimit}</span></div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-400 flex items-center gap-1"><Calendar size={12} /> Expires</span>
                  <span className="text-gray-700 font-medium">{formatDate(coupon.expiryDate)}</span>
                </div>
              </div>

              {/* Usage Bar */}
              <div className="mt-4">
                <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                  <div className="h-full bg-[#2563EB] rounded-full transition-all" style={{ width: `${(coupon.usageCount / coupon.usageLimit) * 100}%` }} />
                </div>
              </div>

              {/* Actions */}
              <div className="flex items-center gap-2 mt-4 pt-4 border-t border-gray-50">
                <Button size="xs" variant="ghost" icon={Edit3} onClick={() => toast.success('Edit coupon')}>Edit</Button>
                <Button size="xs" variant="ghost" icon={Trash2} className="text-red-500 hover:bg-red-50"
                        onClick={() => setDeleteModal({ open: true, coupon })}>Delete</Button>
              </div>
            </Card>
          </motion.div>
        ))}
      </div>

      <ConfirmModal
        isOpen={deleteModal.open}
        onClose={() => setDeleteModal({ open: false, coupon: null })}
        onConfirm={() => { toast.success('Coupon deleted'); setDeleteModal({ open: false, coupon: null }); }}
        type="delete" title="Delete Coupon"
        message={`Delete coupon "${deleteModal.coupon?.code}"? This cannot be undone.`}
        confirmLabel="Delete Coupon"
      />
    </div>
  );
};

export default CouponList;

/**
 * Add/Edit Product Page
 * Multi-section form with image upload, specifications, and SEO fields.
 */
import React, { useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useForm } from 'react-hook-form';
import { motion } from 'framer-motion';
import { Save, ArrowLeft, Eye, FileText, Package, DollarSign, Image, Settings, Globe } from 'lucide-react';
import { PageHeader } from '../../components/common';
import { ImageUploader } from '../../components/common';
import { Button } from '../../components/ui';
import { products } from '../../utils/dummyData';
import { CATEGORIES } from '../../constants';
import toast from 'react-hot-toast';

const AddProduct = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const isEdit = !!id;
  const existingProduct = isEdit ? products.find((p) => p.id === id) : null;

  const [activeSection, setActiveSection] = useState('basic');
  const [images, setImages] = useState([]);
  const [specifications, setSpecifications] = useState(existingProduct?.specifications || [{ key: '', value: '' }]);

  const { register, handleSubmit, formState: { errors }, watch } = useForm({
    defaultValues: existingProduct || {
      title: '', shortDescription: '', description: '', category: '', subcategory: '',
      brand: '', sku: '', price: '', discountPrice: '', gst: '', stock: '',
      weight: '', tags: '', warranty: '', returnPolicy: '', shippingInfo: '',
      seoTitle: '', seoDescription: '',
    },
  });

  const sections = [
    { id: 'basic', label: 'Basic Info', icon: Package },
    { id: 'pricing', label: 'Pricing & Stock', icon: DollarSign },
    { id: 'media', label: 'Media', icon: Image },
    { id: 'specs', label: 'Specifications', icon: Settings },
    { id: 'seo', label: 'SEO & Shipping', icon: Globe },
  ];

  const onSubmit = (data) => {
    toast.success(isEdit ? 'Product updated successfully!' : 'Product created successfully!');
    navigate('/seller/products');
  };

  const onSaveDraft = () => {
    toast.success('Saved as draft');
  };

  const inputClass = "w-full px-4 py-2.5 text-sm bg-white border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-100 focus:border-blue-300 transition-all";
  const labelClass = "block text-sm font-medium text-gray-700 mb-1.5";

  return (
    <div className="space-y-6 pb-8">
      <PageHeader title={isEdit ? 'Edit Product' : 'Add New Product'} subtitle={isEdit ? `Editing: ${existingProduct?.title}` : 'Fill in the product details'}>
        <Button variant="secondary" icon={ArrowLeft} onClick={() => navigate('/seller/products')}>Back</Button>
      </PageHeader>

      <div className="flex flex-col lg:flex-row gap-6">
        {/* Section Navigation */}
        <div className="lg:w-56 flex-shrink-0">
          <div className="bg-white rounded-xl border border-gray-100 p-2 sticky top-24">
            {sections.map((section) => (
              <button
                key={section.id}
                onClick={() => setActiveSection(section.id)}
                className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-all ${
                  activeSection === section.id ? 'bg-blue-50 text-blue-600' : 'text-gray-500 hover:bg-gray-50'
                }`}
              >
                <section.icon size={16} />
                {section.label}
              </button>
            ))}
          </div>
        </div>

        {/* Form Content */}
        <div className="flex-1">
          <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
            {/* Basic Info */}
            {activeSection === 'basic' && (
              <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} className="bg-white rounded-2xl border border-gray-100 p-6 space-y-5">
                <h3 className="text-base font-semibold text-gray-900">Basic Information</h3>

                <div>
                  <label className={labelClass}>Product Title *</label>
                  <input {...register('title', { required: 'Title is required' })} placeholder="Enter product title" className={inputClass} />
                  {errors.title && <p className="text-xs text-red-500 mt-1">{errors.title.message}</p>}
                </div>

                <div>
                  <label className={labelClass}>Short Description</label>
                  <input {...register('shortDescription')} placeholder="Brief description (one liner)" className={inputClass} />
                </div>

                <div>
                  <label className={labelClass}>Full Description *</label>
                  <textarea {...register('description', { required: 'Description is required' })} rows={5} placeholder="Detailed product description" className={inputClass} />
                  {errors.description && <p className="text-xs text-red-500 mt-1">{errors.description.message}</p>}
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className={labelClass}>Category *</label>
                    <select {...register('category', { required: 'Category is required' })} className={inputClass}>
                      <option value="">Select category</option>
                      {CATEGORIES.map((c) => <option key={c.id} value={c.name}>{c.name}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className={labelClass}>Subcategory</label>
                    <select {...register('subcategory')} className={inputClass}>
                      <option value="">Select subcategory</option>
                      {CATEGORIES.find((c) => c.name === watch('category'))?.subcategories.map((s) => (
                        <option key={s} value={s}>{s}</option>
                      ))}
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className={labelClass}>Brand</label>
                    <input {...register('brand')} placeholder="Brand name" className={inputClass} />
                  </div>
                  <div>
                    <label className={labelClass}>SKU *</label>
                    <input {...register('sku', { required: 'SKU is required' })} placeholder="MH-XX-001" className={inputClass} />
                    {errors.sku && <p className="text-xs text-red-500 mt-1">{errors.sku.message}</p>}
                  </div>
                </div>

                <div>
                  <label className={labelClass}>Tags</label>
                  <input {...register('tags')} placeholder="Comma-separated tags (e.g., handmade, organic)" className={inputClass} />
                </div>
              </motion.div>
            )}

            {/* Pricing & Stock */}
            {activeSection === 'pricing' && (
              <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} className="bg-white rounded-2xl border border-gray-100 p-6 space-y-5">
                <h3 className="text-base font-semibold text-gray-900">Pricing & Inventory</h3>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                  <div>
                    <label className={labelClass}>Price (₹) *</label>
                    <input type="number" {...register('price', { required: 'Price is required', min: { value: 0, message: 'Must be positive' } })} placeholder="0" className={inputClass} />
                    {errors.price && <p className="text-xs text-red-500 mt-1">{errors.price.message}</p>}
                  </div>
                  <div>
                    <label className={labelClass}>Discount Price (₹)</label>
                    <input type="number" {...register('discountPrice')} placeholder="0" className={inputClass} />
                  </div>
                  <div>
                    <label className={labelClass}>GST (%)</label>
                    <select {...register('gst')} className={inputClass}>
                      <option value="">No GST</option>
                      <option value="0">0%</option>
                      <option value="5">5%</option>
                      <option value="12">12%</option>
                      <option value="18">18%</option>
                      <option value="28">28%</option>
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                  <div>
                    <label className={labelClass}>Stock *</label>
                    <input type="number" {...register('stock', { required: 'Stock is required', min: 0 })} placeholder="0" className={inputClass} />
                  </div>
                  <div>
                    <label className={labelClass}>Weight (kg)</label>
                    <input type="number" step="0.01" {...register('weight')} placeholder="0.5" className={inputClass} />
                  </div>
                  <div>
                    <label className={labelClass}>Dimensions (LxWxH cm)</label>
                    <input {...register('dimensions')} placeholder="40x30x0.5" className={inputClass} />
                  </div>
                </div>

                <div>
                  <label className={labelClass}>Warranty</label>
                  <input {...register('warranty')} placeholder="e.g., 1 year against manufacturing defects" className={inputClass} />
                </div>
              </motion.div>
            )}

            {/* Media */}
            {activeSection === 'media' && (
              <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} className="bg-white rounded-2xl border border-gray-100 p-6 space-y-5">
                <h3 className="text-base font-semibold text-gray-900">Product Images</h3>
                <p className="text-sm text-gray-500">Upload high-quality images. First image will be the thumbnail.</p>
                <ImageUploader images={images} onChange={setImages} maxImages={8} label="" />
              </motion.div>
            )}

            {/* Specifications */}
            {activeSection === 'specs' && (
              <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} className="bg-white rounded-2xl border border-gray-100 p-6 space-y-5">
                <h3 className="text-base font-semibold text-gray-900">Specifications & Highlights</h3>

                <div>
                  <label className={labelClass}>Specifications</label>
                  <div className="space-y-3">
                    {specifications.map((spec, i) => (
                      <div key={i} className="flex items-center gap-3">
                        <input value={spec.key} onChange={(e) => { const s = [...specifications]; s[i].key = e.target.value; setSpecifications(s); }}
                               placeholder="Attribute (e.g., Material)" className={`${inputClass} flex-1`} />
                        <input value={spec.value} onChange={(e) => { const s = [...specifications]; s[i].value = e.target.value; setSpecifications(s); }}
                               placeholder="Value (e.g., Cotton)" className={`${inputClass} flex-1`} />
                        {specifications.length > 1 && (
                          <button type="button" onClick={() => setSpecifications(specifications.filter((_, j) => j !== i))} className="text-red-400 hover:text-red-600 p-1">✕</button>
                        )}
                      </div>
                    ))}
                    <button type="button" onClick={() => setSpecifications([...specifications, { key: '', value: '' }])}
                            className="text-sm text-blue-600 font-medium hover:text-blue-700">+ Add Specification</button>
                  </div>
                </div>

                <div>
                  <label className={labelClass}>Highlights</label>
                  <textarea {...register('highlights')} rows={3} placeholder="Enter product highlights, one per line" className={inputClass} />
                </div>
              </motion.div>
            )}

            {/* SEO & Shipping */}
            {activeSection === 'seo' && (
              <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} className="bg-white rounded-2xl border border-gray-100 p-6 space-y-5">
                <h3 className="text-base font-semibold text-gray-900">SEO & Shipping</h3>

                <div>
                  <label className={labelClass}>SEO Title</label>
                  <input {...register('seoTitle')} placeholder="SEO-friendly title" className={inputClass} />
                </div>
                <div>
                  <label className={labelClass}>SEO Description</label>
                  <textarea {...register('seoDescription')} rows={3} placeholder="Meta description for search engines" className={inputClass} />
                </div>
                <div>
                  <label className={labelClass}>Return Policy</label>
                  <input {...register('returnPolicy')} placeholder="e.g., 7-day return if damaged" className={inputClass} />
                </div>
                <div>
                  <label className={labelClass}>Shipping Info</label>
                  <textarea {...register('shippingInfo')} rows={2} placeholder="Shipping details and estimated delivery" className={inputClass} />
                </div>
              </motion.div>
            )}

            {/* Action Buttons */}
            <div className="flex items-center gap-3 justify-end sticky bottom-4 bg-white/80 backdrop-blur-sm p-4 rounded-xl border border-gray-100">
              <Button variant="secondary" onClick={onSaveDraft} icon={FileText}>Save as Draft</Button>
              <Button variant="primary" type="submit" icon={Save}>{isEdit ? 'Update Product' : 'Publish Product'}</Button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default AddProduct;

/**
 * Review List Page
 */
import React, { useState, useMemo } from 'react';
import { Star, MessageSquare, Flag, EyeOff, Send } from 'lucide-react';
import { motion } from 'framer-motion';
import { PageHeader, SearchFilter } from '../../components/common';
import { Card, Button, Badge } from '../../components/ui';
import { reviews } from '../../utils/dummyData';
import { getRelativeTime } from '../../utils/formatters';
import toast from 'react-hot-toast';

const ReviewList = () => {
  const [searchQuery, setSearchQuery] = useState('');
  const [ratingFilter, setRatingFilter] = useState('all');
  const [replyBoxId, setReplyBoxId] = useState(null);
  const [replyText, setReplyText] = useState('');

  const filtered = useMemo(() => {
    let result = [...reviews];
    if (ratingFilter !== 'all') result = result.filter((r) => r.rating === parseInt(ratingFilter));
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      result = result.filter((r) => r.customer.toLowerCase().includes(q) || r.productTitle.toLowerCase().includes(q) || r.text.toLowerCase().includes(q));
    }
    return result;
  }, [searchQuery, ratingFilter]);

  const avgRating = (reviews.reduce((a, r) => a + r.rating, 0) / reviews.length).toFixed(1);
  const ratingDist = [5, 4, 3, 2, 1].map((r) => ({ rating: r, count: reviews.filter((rv) => rv.rating === r).length }));

  const handleReply = (id) => {
    if (!replyText.trim()) return;
    toast.success('Reply posted successfully');
    setReplyBoxId(null);
    setReplyText('');
  };

  return (
    <div className="space-y-6 pb-8">
      <PageHeader title="Reviews" subtitle={`${reviews.length} reviews across your products`} />

      {/* Rating Overview */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <Card className="flex items-center gap-6 p-6">
          <div className="text-center">
            <p className="text-4xl font-bold text-gray-900">{avgRating}</p>
            <div className="flex gap-0.5 mt-1 justify-center">
              {[1, 2, 3, 4, 5].map((s) => <Star key={s} size={14} className={s <= Math.round(avgRating) ? 'text-amber-400 fill-amber-400' : 'text-gray-200'} />)}
            </div>
            <p className="text-xs text-gray-400 mt-1">{reviews.length} reviews</p>
          </div>
          <div className="flex-1 space-y-1.5">
            {ratingDist.map((d) => (
              <div key={d.rating} className="flex items-center gap-2">
                <span className="text-xs text-gray-500 w-3">{d.rating}</span>
                <Star size={10} className="text-amber-400 fill-amber-400" />
                <div className="flex-1 h-2 bg-gray-100 rounded-full overflow-hidden">
                  <div className="h-full bg-amber-400 rounded-full" style={{ width: `${(d.count / reviews.length) * 100}%` }} />
                </div>
                <span className="text-xs text-gray-400 w-4">{d.count}</span>
              </div>
            ))}
          </div>
        </Card>

        <div className="md:col-span-2">
          <SearchFilter searchValue={searchQuery} onSearchChange={setSearchQuery} placeholder="Search reviews..." />
          <div className="flex gap-2 mt-3">
            {['all', '5', '4', '3', '2', '1'].map((r) => (
              <button key={r} onClick={() => setRatingFilter(r)}
                className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${ratingFilter === r ? 'bg-[#2563EB] text-white' : 'bg-white border border-gray-200 text-gray-500 hover:bg-gray-50'}`}>
                {r === 'all' ? 'All' : `${r} ★`}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Review Cards */}
      <div className="space-y-4">
        {filtered.map((review, i) => (
          <motion.div key={review.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
            <Card className="hover:border-gray-200 transition-colors">
              <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-3">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-2">
                    <div className="flex gap-0.5">{[1, 2, 3, 4, 5].map((s) => <Star key={s} size={14} className={s <= review.rating ? 'text-amber-400 fill-amber-400' : 'text-gray-200'} />)}</div>
                    <span className="text-xs text-gray-400">{getRelativeTime(new Date(review.createdAt))}</span>
                  </div>
                  <p className="text-sm text-gray-700 leading-relaxed">{review.text}</p>
                  <div className="flex items-center gap-2 mt-3">
                    <span className="text-xs font-semibold text-gray-900">{review.customer}</span>
                    <span className="text-xs text-gray-300">•</span>
                    <span className="text-xs text-gray-400">{review.productTitle}</span>
                  </div>

                  {/* Existing Reply */}
                  {review.reply && (
                    <div className="mt-3 p-3 bg-blue-50 rounded-lg border-l-3 border-blue-400">
                      <p className="text-xs font-semibold text-blue-700 mb-1">Your Reply</p>
                      <p className="text-xs text-blue-600">{review.reply}</p>
                    </div>
                  )}

                  {/* Reply Input */}
                  {replyBoxId === review.id && (
                    <div className="mt-3 flex gap-2">
                      <input value={replyText} onChange={(e) => setReplyText(e.target.value)} placeholder="Write a reply..."
                        className="flex-1 px-3 py-2 text-sm border border-gray-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-100" />
                      <Button size="sm" icon={Send} onClick={() => handleReply(review.id)}>Send</Button>
                    </div>
                  )}
                </div>

                <div className="flex items-center gap-1 flex-shrink-0">
                  {!review.reply && (
                    <button onClick={() => setReplyBoxId(replyBoxId === review.id ? null : review.id)}
                      className="p-2 rounded-lg hover:bg-blue-50 text-gray-400 hover:text-blue-600 transition-colors" title="Reply">
                      <MessageSquare size={16} />
                    </button>
                  )}
                  <button onClick={() => toast.success('Review hidden')}
                    className="p-2 rounded-lg hover:bg-gray-100 text-gray-400 hover:text-gray-600 transition-colors" title="Hide">
                    <EyeOff size={16} />
                  </button>
                  <button onClick={() => toast.success('Review reported')}
                    className="p-2 rounded-lg hover:bg-red-50 text-gray-400 hover:text-red-500 transition-colors" title="Report">
                    <Flag size={16} />
                  </button>
                </div>
              </div>
            </Card>
          </motion.div>
        ))}
      </div>
    </div>
  );
};

export default ReviewList;

/**
 * Settings Page
 * Manage Store profile, Bank details, Password, and Notification Preferences.
 */
import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { Store, Landmark, Shield, Bell, Save, ArrowLeft } from 'lucide-react';
import { PageHeader } from '../../components/common';
import { Card, Button, Toggle } from '../../components/ui';
import { sellerProfile } from '../../utils/dummyData';
import toast from 'react-hot-toast';

const Settings = () => {
  const [activeTab, setActiveTab] = useState('profile');
  const [notifications, setNotifications] = useState({
    orderAlerts: true,
    outOfStock: true,
    customerReviews: false,
    weeklyDigest: true,
  });

  const { register: registerProfile, handleSubmit: handleProfileSubmit } = useForm({ defaultValues: sellerProfile });
  const { register: registerBank, handleSubmit: handleBankSubmit } = useForm({ defaultValues: sellerProfile.bankDetails });
  const { register: registerPassword, handleSubmit: handlePasswordSubmit, reset: resetPassword } = useForm();

  const onUpdateProfile = (data) => {
    toast.success('Profile updated successfully!');
  };

  const onUpdateBank = (data) => {
    toast.success('Bank details updated successfully!');
  };

  const onChangePassword = (data) => {
    if (data.newPassword !== data.confirmPassword) {
      toast.error("New passwords don't match!");
      return;
    }
    toast.success('Password updated successfully!');
    resetPassword();
  };

  const inputClass = "w-full px-4 py-2.5 text-sm bg-white border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-100 focus:border-blue-300 transition-all";
  const labelClass = "block text-sm font-medium text-gray-700 mb-1.5";

  return (
    <div className="space-y-6 pb-8">
