import React, { useState, useRef } from 'react';
import { ArrowLeft, Camera, User, Mail, Phone, MapPin, Calendar, Users, X } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import useAccountStore from '../../../../store/useAccountStore';
import toast from 'react-hot-toast';

const EditProfile = () => {
  const navigate = useNavigate();
  const fileInputRef = useRef(null);
  const { userProfile, updateProfile } = useAccountStore();
  
  const [formData, setFormData] = useState({ ...userProfile });
  const [errors, setErrors] = useState({});

  const validate = () => {
    let newErrors = {};
    if (!formData.name.trim()) newErrors.name = 'Name is required';
    
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!formData.email.trim()) newErrors.email = 'Email is required';
    else if (!emailRegex.test(formData.email)) newErrors.email = 'Invalid email format';
    
    if (!formData.phone.trim()) newErrors.phone = 'Phone is required';
    else if (formData.phone.length < 10) newErrors.phone = 'Invalid phone number';
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSave = () => {
    if (validate()) {
      updateProfile(formData);
      toast.success('Profile Updated Successfully');
      setTimeout(() => navigate(-1), 1500);
    } else {
      toast.error('Please fix the errors');
    }
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        toast.error('Image size should be less than 2MB');
        return;
      }
      
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, avatar: reader.result }));
        toast.success('Photo updated locally');
      };
      reader.readAsDataURL(file);
    }
  };

  const isQuickShopFlow = localStorage.getItem('isQuickShopFlow') === 'true';
  const isMithilakFlow = localStorage.getItem('isMithilakFlow') === 'true';
  const isFreshGroceryFlow = localStorage.getItem('isFreshGroceryFlow') === 'true';

  const pageBg = isMithilakFlow ? 'bg-gradient-to-b from-[#f3e8ff]/60 via-[#faf5ff] to-[#f5f3ff]' : isFreshGroceryFlow ? 'bg-gradient-to-b from-[#FFF0A0]/25 via-[#FFFDF3] to-[#FFF]' : (isQuickShopFlow ? 'bg-[#fff5f7]' : 'bg-bg-cream');
  const headerBg = isMithilakFlow ? 'bg-gradient-to-r from-[#8b5cf6] to-[#6366f1]' : isFreshGroceryFlow ? 'bg-[#FFF0A0]' : (isQuickShopFlow ? 'bg-gradient-to-r from-[#ff2a5f] to-[#ff7e5f]' : 'bg-[#FCF7EE] border-b border-[#F3E3CD]/60');
  const headerTextColor = (isMithilakFlow || isQuickShopFlow) ? 'text-white' : (isFreshGroceryFlow ? 'text-black' : 'text-[#3C2415]');

  return (
    <motion.div 
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: -20 }}
      className={`${pageBg} min-h-screen text-slate-800 font-sans relative transition-colors duration-300`}
    >
      {/* Global Repeating Mithila Art Page Background Texture */}
      {!(isMithilakFlow || isQuickShopFlow || isFreshGroceryFlow) && (
        <div 
          className="fixed inset-0 pointer-events-none z-0 bg-repeat opacity-[0.03] select-none"
          style={{
            backgroundImage: "url('/Screenshot 2026-07-17 130906.png')",
            backgroundSize: '360px',
          }}
        />
      )}

      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleImageChange} 
        accept="image/*" 
        className="hidden" 
      />

      {/* Header */}
      <div className={`sticky top-0 z-50 p-4 flex items-center justify-between relative z-10 transition-colors duration-300 ${headerBg}`}>
        <div className="flex items-center gap-3">
          <button onClick={() => navigate(-1)} className={`p-1 rounded-full hover:bg-slate-50 transition-colors ${headerTextColor}`} aria-label="Go back">
            <ArrowLeft size={22} />
          </button>
          <h1 className={`text-[17px] font-black uppercase tracking-widest ${headerTextColor}`}>Edit Profile</h1>
        </div>
        <button onClick={handleSave} className="bg-[#3E5A44] text-white font-black text-xs uppercase tracking-widest px-5 py-2 rounded-xl shadow-sm hover:bg-[#06331b] active:scale-95 transition-all">
          Save
        </button>
      </div>

      <div className="container mx-auto px-4 py-8 w-full space-y-8 relative z-10">
        {/* Profile Picture */}
        <div className="flex flex-col items-center">
          <div className="relative group">
            <div 
              onClick={() => fileInputRef.current.click()}
              className="w-32 h-32 bg-emerald-50 rounded-full flex items-center justify-center text-[#3E5A44] font-black text-5xl shadow-md border-4 border-white overflow-hidden cursor-pointer active:scale-95 transition-transform"
            >
              {formData.avatar ? (
                <img src={formData.avatar} alt="Profile" className="w-full h-full object-cover" />
              ) : (
                formData.name ? formData.name.charAt(0).toUpperCase() : 'H'
              )}
            </div>
            <button 
              onClick={() => fileInputRef.current.click()}
              className="absolute bottom-0 right-0 bg-[#3E5A44] border-2 border-white p-2.5 rounded-full text-white shadow-md hover:bg-[#06331b] transition-all active:scale-90"
            >
              <Camera size={18} />
            </button>
          </div>
          <button 
            onClick={() => fileInputRef.current.click()}
            className="mt-4 text-[10px] font-black text-[#3E5A44] uppercase tracking-[3px] hover:opacity-70 transition-opacity"
          >
            Change Photo
          </button>
        </div>

        {/* Form Fields */}
        <div className="space-y-6">
          {/* Full Name */}
          <div className="space-y-2">
            <label className="text-[10px] font-black text-[#3E5A44] uppercase tracking-[3px] ml-1">Full Name</label>
            <div className={`relative ${errors.name ? 'animate-shake' : ''}`}>
              <User size={18} className={`absolute left-4 top-1/2 -translate-y-1/2 ${errors.name ? 'text-red-500' : 'text-slate-400'}`} />
              <input 
                type="text" 
                value={formData.name}
                onChange={(e) => setFormData({...formData, name: e.target.value})}
                className={`w-full bg-white border ${errors.name ? 'border-red-500' : 'border-slate-200'} rounded-2xl py-4 pl-12 pr-4 text-sm font-semibold text-slate-800 focus:outline-none focus:border-[#3E5A44]/50 transition-all shadow-sm`}
              />
            </div>
            {errors.name && <p className="text-[10px] text-red-500 font-black uppercase tracking-wider ml-1">{errors.name}</p>}
          </div>

          {/* Email */}
          <div className="space-y-2">
            <label className="text-[10px] font-black text-[#3E5A44] uppercase tracking-[3px] ml-1">Email Address</label>
            <div className={`relative ${errors.email ? 'animate-shake' : ''}`}>
              <Mail size={18} className={`absolute left-4 top-1/2 -translate-y-1/2 ${errors.email ? 'text-red-500' : 'text-slate-400'}`} />
              <input 
                type="email" 
                value={formData.email}
                onChange={(e) => setFormData({...formData, email: e.target.value})}
                className={`w-full bg-white border ${errors.email ? 'border-red-500' : 'border-slate-200'} rounded-2xl py-4 pl-12 pr-4 text-sm font-semibold text-slate-800 focus:outline-none focus:border-[#3E5A44]/50 transition-all shadow-sm`}
              />
            </div>
            {errors.email && <p className="text-[10px] text-red-500 font-black uppercase tracking-wider ml-1">{errors.email}</p>}
          </div>

          {/* Phone */}
          <div className="space-y-2">
            <label className="text-[10px] font-black text-[#3E5A44] uppercase tracking-[3px] ml-1">Phone Number</label>
            <div className={`relative ${errors.phone ? 'animate-shake' : ''}`}>
              <Phone size={18} className={`absolute left-4 top-1/2 -translate-y-1/2 ${errors.phone ? 'text-red-500' : 'text-slate-400'}`} />
              <input 
                type="tel" 
                value={formData.phone}
                onChange={(e) => setFormData({...formData, phone: e.target.value})}
                className={`w-full bg-white border ${errors.phone ? 'border-red-500' : 'border-slate-200'} rounded-2xl py-4 pl-12 pr-4 text-sm font-semibold text-slate-800 focus:outline-none focus:border-[#3E5A44]/50 transition-all shadow-sm`}
              />
            </div>
            {errors.phone && <p className="text-[10px] text-red-500 font-black uppercase tracking-wider ml-1">{errors.phone}</p>}
          </div>

          {/* Gender & DOB Row */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-[#3E5A44] uppercase tracking-[3px] ml-1">Gender</label>
              <div className="relative">
                <Users size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                <select 
                  value={formData.gender}
                  onChange={(e) => setFormData({...formData, gender: e.target.value})}
                  className="w-full bg-white border border-slate-200 rounded-2xl py-4 pl-12 pr-4 text-sm font-semibold text-slate-800 focus:outline-none focus:border-[#3E5A44]/50 transition-all appearance-none shadow-sm"
                >
                  <option value="Male">Male</option>
                  <option value="Female">Female</option>
                  <option value="Other">Other</option>
                </select>
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-[#3E5A44] uppercase tracking-[3px] ml-1">Date of Birth</label>
              <div className="relative">
                <Calendar size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                <input 
                  type="date" 
                  value={formData.dob}
                  onChange={(e) => setFormData({...formData, dob: e.target.value})}
                  className="w-full bg-white border border-slate-200 rounded-2xl py-4 pl-12 pr-4 text-xs font-semibold text-slate-800 focus:outline-none focus:border-[#3E5A44]/50 transition-all shadow-sm"
                />
              </div>
            </div>
          </div>
        </div>

        <div className="pt-8 pb-12">
          <button 
            onClick={handleSave}
            className="w-full bg-[#3E5A44] text-white py-4 rounded-2xl font-black uppercase tracking-[3px] shadow-lg shadow-emerald-100 hover:scale-[1.02] transition-all active:scale-95 group relative overflow-hidden"
          >
            <span className="relative z-10">Save Changes</span>
            <div className="absolute inset-0 bg-white/20 translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-500"></div>
          </button>
        </div>
      </div>
    </motion.div>
  );
};

export default EditProfile;

import React, { useState, useEffect } from 'react';
import { 
  ArrowLeft, ChevronRight, Search, ListFilter, Star, 
  Edit3, ShoppingBag, X, Check, Calendar, Package, Filter, MessageSquare
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import useAccountStore from '../../../../store/useAccountStore';
import SearchInput from '../../../../shared/components/SearchInput';

// Real Images from Assets
// Real Images from Assets
import ImageBanner1 from '../../../../assets/TopBanner/ImageBanner1.jpg';
import ImageBanner2 from '../../../../assets/TopBanner/ImageBanner2.jpg';
import ImageBanner3 from '../../../../assets/TopBanner/ImageBanner3.webp';
import ImageBanner4 from '../../../../assets/TopBanner/ImageBanner4.jpg';

const BannerCarousel = () => {
  const [currentBanner, setCurrentBanner] = useState(0);
  const [isBannerLoaded, setIsBannerLoaded] = useState(false);

  const banners = [
    { 
      image: ImageBanner1, 
      title: "Super Saver Days", 
      desc: "Up to 80% Off on Electronics", 
      label: "SALE"
    },
    { 
      image: ImageBanner2, 
      title: "Fashion Carnival", 
      desc: "Extra 20% Off for Plus Members", 
      label: "OFFER"
    },
    { 
      image: ImageBanner3, 
      title: "Tech Spotlight", 
      desc: "Latest Gadgets at Best Prices", 
      label: "NEW"
    },
    { 
      image: ImageBanner4, 
      title: "Grocery Offers", 
      desc: "Best Quality Groceries", 
      label: "SALE"
    }
  ];

  useEffect(() => {
    const timer = setInterval(() => {
      setIsBannerLoaded(false);
      setCurrentBanner((prev) => (prev + 1) % banners.length);
    }, 5000);
    return () => clearInterval(timer);
  }, [banners.length]);

  return (
    <div className="p-4">
      <div className="rounded-2xl relative overflow-hidden h-44 shadow-lg group bg-gray-100">
        <AnimatePresence mode="wait">
          <motion.div 
            key={currentBanner}
            initial={{ opacity: 0 }}
            animate={{ opacity: isBannerLoaded ? 1 : 0 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.5 }}
            className="absolute inset-0 w-full h-full"
          >
            <img 
              src={banners[currentBanner].image} 
              className="w-full h-full object-cover" 
              alt="banner" 
              onLoad={() => setIsBannerLoaded(true)}
            />
            <div className="absolute inset-0 bg-gradient-to-r from-black/70 via-black/30 to-transparent" />
          </motion.div>
        </AnimatePresence>

        {!isBannerLoaded && (
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-8 h-8 border-4 border-blue-200 border-t-blue-500 rounded-full animate-spin" />
          </div>
        )}

        <AnimatePresence>
          {isBannerLoaded && (
            <motion.div 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="relative z-10 px-8 h-full flex flex-col justify-center"
            >
              <motion.div 
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  className="flex items-center gap-2 mb-2"
              >
                  <div className="bg-[#ffc107] text-slate-900 px-2 py-0.5 rounded text-[10px] font-black uppercase tracking-wider">{banners[currentBanner].label}</div>
              </motion.div>
              <motion.h2 
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: 0.1 }}
                  className="text-white text-[24px] font-black leading-tight drop-shadow-lg"
                >
                  {banners[currentBanner].title}
                </motion.h2>
              <motion.p 
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: 0.2 }}
                  className="text-white/90 text-[15px] font-medium mt-1 drop-shadow-md"
                >
                  {banners[currentBanner].desc}
                </motion.p>
              <button className="mt-5 w-fit bg-white text-slate-900 px-8 py-2.5 rounded-full text-[12px] font-black uppercase tracking-widest shadow-xl active:scale-95 transition-transform">
                Shop Now
              </button>
            </motion.div>
          )}
        </AnimatePresence>

        <div className="absolute bottom-5 right-8 flex gap-2.5">
          {banners.map((_, i) => (
            <button 
              key={i} 
              onClick={() => {
                if (i !== currentBanner) {
                  setIsBannerLoaded(false);
                  setCurrentBanner(i);
                }
              }}
              className={`h-1.5 rounded-full transition-all duration-300 ${i === currentBanner ? 'w-8 bg-white' : 'w-2 bg-white/40'}`} 
            />
          ))}
        </div>
      </div>
    </div>
  );
};

const MyOrders = () => {
  const navigate = useNavigate();
  const orders = useAccountStore((state) => state.orders);
  const [searchQuery, setSearchQuery] = useState('');
  const [showFilterSheet, setShowFilterSheet] = useState(false);
  const [showReviewModal, setShowReviewModal] = useState(null); 
  const [ratings, setRatings] = useState({}); 
  
  const [activeFilters, setActiveFilters] = useState({
    status: 'All',
    time: 'Anytime'
  });

  const filteredOrders = orders.filter(order => {
    const matchesSearch = 
      order.items.some(item => item.name.toLowerCase().includes(searchQuery.toLowerCase())) ||
      order.id.toLowerCase().includes(searchQuery.toLowerCase());
    
    const matchesStatus = activeFilters.status === 'All' || order.status.toLowerCase() === activeFilters.status.toLowerCase();
    const matchesTime = activeFilters.time === 'Anytime' || true; 

    return matchesSearch && matchesStatus && matchesTime;
  });

  const statusOptions = ['All', 'Delivered', 'Cancelled', 'Confirmed', 'Shipped', 'Returned'];
  const timeOptions = ['Anytime', 'Last 30 days', '2026', '2025', 'Older'];

  const OrderCard = ({ order }) => {
    const mainItem = order.items[0];
    const statusColor = order.status === 'Delivered' ? 'text-green-600' : order.status === 'Cancelled' ? 'text-red-600' : 'text-primary-dark';
    const currentOrderRating = ratings[order.id] || { rating: 0, review: '' };

    return (
      <motion.div 
        layout
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        className="bg-white mx-3 my-2 rounded-xl shadow-sm border border-gray-100 p-3 active:bg-gray-50 transition-all cursor-pointer group"
      >
        <div className="flex gap-3" onClick={() => navigate(`/vendor/profile/orders/${order.id}`)}>
          {/* Compact Image */}
          <div className="w-16 h-20 bg-gray-50 rounded-lg overflow-hidden flex-shrink-0 flex items-center justify-center p-1.5 border border-gray-100">
            <img src={mainItem.image} alt={mainItem.name} className="w-full h-full object-contain mix-blend-multiply" />
          </div>

          <div className="flex-1 min-w-0 flex flex-col justify-between py-0.5">
            <div className="flex justify-between items-start">
              <div className="flex-1 pr-2">
                <p className={`text-[13px] font-bold mb-0.5 ${statusColor}`}>
                  {order.status} on {order.date}
                </p>
                <h3 className="text-[12px] text-gray-500 line-clamp-1 leading-tight font-medium">
                  {mainItem.name}
                </h3>
              </div>
              <ChevronRight size={16} className="text-gray-300 mt-0.5 flex-shrink-0 group-hover:text-primary-dark group-hover:translate-x-1 transition-all" />
            </div>

            {/* Compact Bottom Section */}
            <div className="mt-2 flex items-center justify-between" onClick={(e) => e.stopPropagation()}>
              <div className="flex items-center gap-1.5">
                <span className="text-[10px] text-gray-400 font-bold uppercase tracking-tight">
                  {currentOrderRating.rating > 0 ? 'Your Rating' : 'Rate & Review'}
                </span>
                <div className="flex gap-0.5">
                  {[1, 2, 3, 4, 5].map((star) => (
                    <Star 
                      key={star} 
                      size={14} 
                      onClick={() => setRatings(prev => ({ ...prev, [order.id]: { ...currentOrderRating, rating: star } }))}
                      className={`cursor-pointer transition-colors ${star <= currentOrderRating.rating ? 'text-green-600 fill-green-600' : 'text-gray-200'}`} 
                    />
                  ))}
                </div>
              </div>
              {order.status === 'Delivered' && (
                <button 
                  onClick={() => setShowReviewModal(order.id)}
                  className="flex items-center gap-1 px-2.5 py-1.5 border border-primary-green/30 bg-primary-light/50 rounded-lg text-primary-dark text-[10px] font-black uppercase tracking-tight active:scale-95 transition-transform"
                >
                  <Edit3 size={11} />
                  Write Review
                </button>
              )}
            </div>
            {currentOrderRating.review && (
              <p className="mt-1.5 text-[11px] text-gray-500 italic line-clamp-1 border-l-2 border-green-500 pl-2">
                "{currentOrderRating.review}"
              </p>
            )}
          </div>
        </div>
      </motion.div>
    );
  };

  const isQuickShopFlow = localStorage.getItem('isQuickShopFlow') === 'true';
  const isMithilakFlow = localStorage.getItem('isMithilakFlow') === 'true';
  const isFreshGroceryFlow = localStorage.getItem('isFreshGroceryFlow') === 'true';

  const pageBg = isMithilakFlow ? 'bg-gradient-to-b from-[#f3e8ff]/60 via-[#faf5ff] to-[#f5f3ff]' : isFreshGroceryFlow ? 'bg-gradient-to-b from-[#FFF0A0]/25 via-[#FFFDF3] to-[#FFF]' : (isQuickShopFlow ? 'bg-[#fff5f7]' : 'bg-bg-cream');
  const headerBg = isMithilakFlow ? 'bg-gradient-to-r from-[#8b5cf6] to-[#6366f1]' : isFreshGroceryFlow ? 'bg-[#FFF0A0]' : (isQuickShopFlow ? 'bg-gradient-to-r from-[#ff2a5f] to-[#ff7e5f]' : 'bg-[#FCF7EE] border-b border-[#F3E3CD]/60');
  const headerTextColor = (isMithilakFlow || isQuickShopFlow) ? 'text-white' : (isFreshGroceryFlow ? 'text-black' : 'text-[#3C2415]');
  const filterBg = isMithilakFlow ? 'bg-[#faf5ff]/80' : isFreshGroceryFlow ? 'bg-[#FFFDF3]/80' : (isQuickShopFlow ? 'bg-[#fff5f7]/80' : 'bg-bg-cream/80');

  return (
    <div className={`min-h-screen font-nunito pb-20 relative transition-colors duration-300 ${pageBg}`}>
      {/* Global Repeating Mithila Art Page Background Texture */}
      {!(isMithilakFlow || isQuickShopFlow || isFreshGroceryFlow) && (
        <div 
          className="fixed inset-0 pointer-events-none z-0 bg-repeat opacity-[0.03] select-none"
          style={{
            backgroundImage: "url('/Screenshot 2026-07-17 130906.png')",
            backgroundSize: '360px',
          }}
        />
      )}

      {/* Header */}
      <div className={`sticky top-0 z-50 px-4 py-4 flex items-center gap-4 shadow-sm relative z-10 transition-colors duration-300 ${headerBg}`}>
        <button onClick={() => navigate(-1)} className={`p-1 -ml-1 active:scale-90 transition-transform ${headerTextColor}`}>
          <ArrowLeft size={24} />
        </button>
        <h1 className={`text-[18px] font-bold font-montserrat ${headerTextColor}`}>My Orders</h1>
      </div>

      <div className="w-full mx-auto relative z-10">
        {/* Working Banner Carousel - Optimized for Performance */}
        <BannerCarousel />

        {/* Search & Filters */}
        <div className={`px-4 pb-4 sticky top-[68px] z-40 backdrop-blur-md transition-colors ${filterBg}`}>
           <div className="flex gap-3">
              <SearchInput
                type="text" 
                placeholder="Search your order here" 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                rightElement={
                  searchQuery && (
                    <button onClick={() => setSearchQuery('')} className="text-gray-400 hover:text-slate-600">
                      <X size={16} />
                    </button>
                  )
                }
              />
              <button 
                onClick={() => setShowFilterSheet(true)}
                className={`bg-white border border-gray-200 rounded-xl px-4 flex items-center gap-2 shadow-sm active:scale-95 transition-all ${activeFilters.status !== 'All' ? 'border-blue-500 bg-primary-light' : ''}`}
              >
                 <ListFilter size={18} className={activeFilters.status !== 'All' ? 'text-primary-dark' : 'text-gray-600'} />
                 <span className={`text-[13px] font-bold ${activeFilters.status !== 'All' ? 'text-primary-dark' : 'text-gray-700'}`}>Filters</span>
                 {activeFilters.status !== 'All' && <div className="w-2 h-2 bg-primary-dark rounded-full" />}
              </button>
           </div>
        </div>

        {/* Orders List */}
        <div className="bg-white shadow-sm mt-2 border-t border-gray-100">
           <AnimatePresence mode="popLayout">
              {filteredOrders.length > 0 ? (
                filteredOrders.map((order) => (
                  <OrderCard key={order.id} order={order} />
                ))
              ) : (
                <motion.div 
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  className="flex flex-col items-center justify-center py-24 px-10 text-center bg-white"
                >
                  <div className="w-24 h-24 bg-gray-50 rounded-full flex items-center justify-center text-gray-200 mb-8">
                    <ShoppingBag size={48} />
                  </div>
                  <h3 className="text-[20px] font-black text-slate-800 uppercase tracking-tight">No Orders Found</h3>
                  <p className="text-[14px] text-gray-400 mt-3 max-w-[240px] mx-auto font-medium leading-relaxed">
                    {searchQuery ? "We couldn't find anything matching your search." : "Looks like you haven't placed any orders recently."}
                  </p>
                  <button 
                    onClick={() => navigate('/vendor/home')}
                    className="mt-10 bg-[#3E5A44] text-white px-12 py-4 rounded-2xl font-black uppercase tracking-widest text-[12px] shadow-xl shadow-blue-100 active:scale-95 transition-transform"
                  >
                    Start Shopping
                  </button>
                </motion.div>
              )}
           </AnimatePresence>
        </div>
      </div>

      {/* Review Modal */}
      <AnimatePresence>
        {showReviewModal && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center px-4">
             <motion.div 
               initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
               onClick={() => setShowReviewModal(null)}
               className="absolute inset-0 bg-black/60 backdrop-blur-sm"
             />
             <motion.div 
               initial={{ scale: 0.9, opacity: 0 }}
               animate={{ scale: 1, opacity: 1 }}
               exit={{ scale: 0.9, opacity: 0 }}
               className="relative w-full max-w-md bg-white rounded-[24px] overflow-hidden shadow-2xl p-6"
             >
                <div className="flex justify-between items-center mb-6">
                   <h3 className="text-[18px] font-black text-slate-900 uppercase tracking-tight">Write a Review</h3>
                   <button onClick={() => setShowReviewModal(null)} className="p-2 bg-gray-100 rounded-full">
                      <X size={18} className="text-gray-500" />
                   </button>
                </div>
                
                <div className="flex flex-col items-center mb-8">
                   <div className="flex gap-2 mb-3">
                      {[1, 2, 3, 4, 5].map((star) => (
                        <Star 
                          key={star} 
                          size={32} 
                          onClick={() => setRatings(prev => ({ ...prev, [showReviewModal]: { ...prev[showReviewModal], rating: star } }))}
                          className={`cursor-pointer transition-all active:scale-125 ${star <= (ratings[showReviewModal]?.rating || 0) ? 'text-green-600 fill-green-600 shadow-sm' : 'text-gray-200'}`} 
                        />
                      ))}
                   </div>
                   <p className="text-[13px] font-bold text-gray-400 uppercase tracking-widest">
                     {(ratings[showReviewModal]?.rating === 5 && 'Excellent!') || 
                      (ratings[showReviewModal]?.rating === 4 && 'Very Good!') || 
                      (ratings[showReviewModal]?.rating === 3 && 'Good') || 
                      (ratings[showReviewModal]?.rating === 2 && 'Fair') || 
                      (ratings[showReviewModal]?.rating === 1 && 'Bad') || 'Select Rating'}
                   </p>
                </div>

                <div className="bg-gray-50 rounded-2xl p-4 border border-gray-100 mb-6">
                   <textarea 
                    placeholder="Share your experience with this product..."
                    className="w-full bg-transparent border-none outline-none text-[14px] text-slate-800 placeholder:text-gray-400 min-h-[120px] resize-none"
                    value={ratings[showReviewModal]?.review || ''}
                    onChange={(e) => setRatings(prev => ({ ...prev, [showReviewModal]: { ...prev[showReviewModal], review: e.target.value } }))}
                   />
                </div>

                <button 
                  onClick={() => setShowReviewModal(null)}
                  className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black uppercase tracking-widest text-[13px] shadow-xl active:scale-[0.98] transition-transform flex items-center justify-center gap-2"
                >
                   <MessageSquare size={18} />
                   Submit Review
                </button>
             </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Filter Bottom Sheet */}
      <AnimatePresence>
        {showFilterSheet && (
          <div className="fixed inset-0 z-[100] flex items-end justify-center">
             <motion.div 
               initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
               onClick={() => setShowFilterSheet(false)}
               className="absolute inset-0 bg-black/40 backdrop-blur-sm"
             />
             <motion.div 
               initial={{ y: "100%" }}
               animate={{ y: 0 }}
               exit={{ y: "100%" }}
               transition={{ type: "spring", damping: 25, stiffness: 300 }}
               className="relative w-full w-full bg-white rounded-t-[32px] overflow-hidden shadow-2xl"
             >
                <div className="p-6">
                   <div className="flex justify-between items-center mb-8">
                      <div className="flex items-center gap-3">
                         <div className="w-10 h-10 bg-primary-light rounded-xl flex items-center justify-center">
                            <Filter size={20} className="text-primary-dark" />
                         </div>
                         <h2 className="text-[20px] font-black text-slate-900 uppercase tracking-tight">Filter Orders</h2>
                      </div>
                      <button onClick={() => setShowFilterSheet(false)} className="bg-gray-100 p-2 rounded-full active:scale-90 transition-transform">
                         <X size={20} className="text-gray-500" />
                      </button>
                   </div>

                   <div className="mb-8">
                      <p className="text-[11px] font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                        <Package size={14} /> Order Status
                      </p>
                      <div className="flex flex-wrap gap-2.5">
                         {statusOptions.map(opt => (
                            <button 
                              key={opt}
                              onClick={() => setActiveFilters(prev => ({ ...prev, status: opt }))}
                              className={`px-5 py-2.5 rounded-xl text-[13px] font-bold transition-all ${
                                activeFilters.status === opt 
                                ? 'bg-[#3E5A44] text-white shadow-lg shadow-blue-100 scale-105' 
                                : 'bg-gray-50 text-slate-600 border border-gray-100'
                              }`}
                            >
                               {opt}
                            </button>
                         ))}
                      </div>
                   </div>

                   <div className="mb-10">
                      <p className="text-[11px] font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                        <Calendar size={14} /> Timeframe
                      </p>
                      <div className="flex flex-wrap gap-2.5">
                         {timeOptions.map(opt => (
                            <button 
                              key={opt}
                              onClick={() => setActiveFilters(prev => ({ ...prev, time: opt }))}
                              className={`px-5 py-2.5 rounded-xl text-[13px] font-bold transition-all ${
                                activeFilters.time === opt 
                                ? 'bg-[#3E5A44] text-white shadow-lg shadow-blue-100 scale-105' 
                                : 'bg-gray-50 text-slate-600 border border-gray-100'
                              }`}
                            >
                               {opt}
                            </button>
                         ))}
                      </div>
                   </div>

                   <div className="flex gap-4">
                      <button 
                        onClick={() => {
                          setActiveFilters({ status: 'All', time: 'Anytime' });
                          setShowFilterSheet(false);
                        }}
                        className="flex-1 py-4 border border-gray-200 rounded-2xl text-[13px] font-black uppercase tracking-widest text-slate-500 active:bg-gray-50 transition-colors"
                      >
                         Clear All
                      </button>
                      <button 
                        onClick={() => setShowFilterSheet(false)}
                        className="flex-[2] py-4 bg-slate-900 text-white rounded-2xl text-[13px] font-black uppercase tracking-widest shadow-xl active:scale-[0.98] transition-transform"
                      >
