         <Package size={80} className="text-white/10" />
         
         <AnimatePresence>
           {flashing && (
             <motion.div 
               initial={{ opacity: 0 }}
               animate={{ opacity: 1 }}
               exit={{ opacity: 0 }}
               className="absolute inset-0 bg-white z-50"
