/**
 * MobileMenu Component
 * Slide-out drawer sidebar for mobile devices.
 */
import React from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Store, LayoutDashboard, Package, PlusCircle, Warehouse,
  ShoppingCart, RotateCcw, Users, Star, Ticket, Bell,
  BarChart3, Wallet, Settings, LogOut } from 'lucide-react';
import { useSellerAuth } from '../../context/SellerAuthContext';
import { SIDEBAR_MENU } from '../../constants';

const iconComponents = {
  LayoutDashboard, Package, PlusCircle, Warehouse, ShoppingCart,
  RotateCcw, Users, Star, Ticket, Bell, BarChart3, Wallet,
  Settings, LogOut, Store,
};

const MobileMenu = ({ isOpen, onClose }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const { seller, logout } = useSellerAuth();

  const handleLogout = async () => {
    await logout();
    navigate('/seller/login');
    onClose();
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          {/* Backdrop */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/40 backdrop-blur-sm z-50 lg:hidden"
          />

          {/* Drawer */}
          <motion.aside
            initial={{ x: '-100%' }}
            animate={{ x: 0 }}
            exit={{ x: '-100%' }}
            transition={{ type: 'spring', damping: 25, stiffness: 200 }}
            className="fixed inset-y-0 left-0 w-72 bg-slate-950 z-50 flex flex-col shadow-2xl lg:hidden border-r border-slate-900 text-slate-200"
          >
            {/* Header */}
            <div className="h-16 flex items-center justify-between px-5 border-b border-slate-900">
              <div className="flex items-center gap-3">
                <img 
                  src="/logomith-removebg-preview.png" 
                  alt="Mithilakart" 
                  className="h-10 w-auto object-contain"
                />
              </div>
              <button onClick={onClose} className="p-2 rounded-lg hover:bg-slate-900 transition-colors" aria-label="Close menu">
                <X size={20} className="text-slate-400" />
              </button>
            </div>

            {/* Navigation */}
            <nav className="flex-1 py-4 px-3 overflow-y-auto">
              {SIDEBAR_MENU.map((group, gIdx) => (
                <div key={gIdx} className={gIdx > 0 ? 'mt-5' : ''}>
                  <p className="px-3 mb-2 text-[10px] font-semibold text-slate-500 uppercase tracking-widest">
                    {group.group}
                  </p>
                  <div className="space-y-1">
                    {group.items.map((item) => {
                      const IconComponent = iconComponents[item.icon];
                      const active = location.pathname === item.path;

                      if (item.path === '#logout') {
                        return (
                          <button
                            key={item.name}
                            onClick={handleLogout}
                            className="w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium text-red-400 hover:bg-red-950/30 hover:text-red-500"
                          >
                            {IconComponent && <IconComponent size={20} />}
                            <span>{item.name}</span>
                          </button>
                        );
                      }

                      return (
                        <Link
                          key={item.path}
                          to={item.path}
                          onClick={onClose}
                          className={`
                            flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium transition-all
                            ${active
                              ? 'bg-slate-800 text-white border border-slate-700'
                              : 'text-slate-400 hover:bg-slate-900/60 hover:text-white'
                            }
                          `}
                        >
                          {IconComponent && <IconComponent size={20} className={active ? 'text-white' : 'text-slate-500'} />}
                          <span>{item.name}</span>
                        </Link>
                      );
                    })}
                  </div>
                </div>
              ))}
            </nav>

            {/* Footer */}
            <div className="border-t border-slate-900 p-4">
              <div className="flex items-center gap-3 p-3 bg-slate-900/60 rounded-xl">
                <div className="w-9 h-9 bg-slate-800 rounded-xl flex items-center justify-center">
                  <span className="text-sm font-bold text-white">{seller?.name?.charAt(0) || 'S'}</span>
                </div>
                <div>
                  <p className="text-xs font-semibold text-slate-200">{seller?.storeName || 'Seller Store'}</p>
                  <p className="text-[10px] text-slate-400">{seller?.email || 'seller@example.com'}</p>
                </div>
              </div>
            </div>
          </motion.aside>
        </>
      )}
    </AnimatePresence>
  );
};

export default MobileMenu;

/**
 * SellerLayout Component
 * Main layout wrapper with sidebar, topbar, and content area.
 * Completely independent — does NOT reuse AdminLayout.
 */
import React, { useState } from 'react';
import { Outlet } from 'react-router-dom';
import { AnimatePresence, motion } from 'framer-motion';
import Sidebar from './Sidebar';
import Topbar from './Topbar';
import MobileMenu from './MobileMenu';
import { useTheme } from '../../context/ThemeContext';
import '../../styles/seller.css';

const SellerLayout = () => {
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const { theme } = useTheme();

  return (
    <div className={`seller-module min-h-screen flex`}
         style={{ backgroundColor: 'var(--seller-bg)' }}>
      {/* Desktop Sidebar */}
      <Sidebar
        collapsed={sidebarCollapsed}
        onToggle={() => setSidebarCollapsed(!sidebarCollapsed)}
      />

      {/* Mobile Sidebar Drawer */}
      <MobileMenu
        isOpen={mobileMenuOpen}
        onClose={() => setMobileMenuOpen(false)}
      />

      {/* Main Content Area */}
      <div
        className={`flex-1 flex flex-col min-h-screen transition-all duration-300 ease-in-out ${
          sidebarCollapsed ? 'lg:ml-20' : 'lg:ml-[272px]'
        }`}
      >
        {/* Top Navbar */}
        <Topbar
          onMenuClick={() => setMobileMenuOpen(true)}
          sidebarCollapsed={sidebarCollapsed}
        />

        {/* Page Content */}
        <main className="flex-1 p-4 sm:p-6 lg:p-8 max-w-[1600px] w-full mx-auto">
          <AnimatePresence mode="wait">
            <motion.div
              key={location.pathname}
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -8 }}
              transition={{ duration: 0.2 }}
            >
              <Outlet />
            </motion.div>
          </AnimatePresence>
        </main>
      </div>
    </div>
  );
};

export default SellerLayout;

/**
 * Coupon Management Page (List + Create inline)
 */
import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { motion } from 'framer-motion';
import { Plus, Ticket, Edit3, Trash2, Calendar, Percent, DollarSign, X } from 'lucide-react';
import { PageHeader, ConfirmModal, StatusBadge } from '../../components/common';
import { Card, Button, Badge } from '../../components/ui';
import { coupons } from '../../utils/dummyData';
import { formatCurrency, formatDate } from '../../utils/formatters';
import toast from 'react-hot-toast';

const CouponList = () => {
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [deleteModal, setDeleteModal] = useState({ open: false, coupon: null });
  const { register, handleSubmit, reset, formState: { errors } } = useForm();

  const onCreateCoupon = (data) => {
    toast.success(`Coupon "${data.code}" created successfully!`);
    setShowCreateForm(false);
    reset();
  };

  const inputClass = "w-full px-4 py-2.5 text-sm bg-white border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-100 focus:border-blue-300 transition-all";

  return (
    <div className="space-y-6 pb-8">
      <PageHeader title="Coupons" subtitle={`${coupons.length} coupons created`}>
        <Button icon={showCreateForm ? X : Plus} variant={showCreateForm ? 'secondary' : 'primary'}
                onClick={() => setShowCreateForm(!showCreateForm)}>
          {showCreateForm ? 'Cancel' : 'Create Coupon'}
        </Button>
      </PageHeader>

      {/* Create Coupon Form */}
      {showCreateForm && (
        <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }}>
          <Card title="Create New Coupon">
            <form onSubmit={handleSubmit(onCreateCoupon)} className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 mt-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Code *</label>
                <input {...register('code', { required: 'Code is required' })} placeholder="SALE50" className={inputClass} style={{ textTransform: 'uppercase' }} />
                {errors.code && <p className="text-xs text-red-500 mt-1">{errors.code.message}</p>}
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Type *</label>
                <select {...register('type', { required: true })} className={inputClass}>
                  <option value="percentage">Percentage (%)</option>
                  <option value="flat">Flat Amount (₹)</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Value *</label>
                <input type="number" {...register('value', { required: 'Value is required', min: 1 })} placeholder="50" className={inputClass} />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Min Order (₹)</label>
                <input type="number" {...register('minOrder')} placeholder="500" className={inputClass} />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Max Discount (₹)</label>
                <input type="number" {...register('maxDiscount')} placeholder="200" className={inputClass} />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Expiry Date *</label>
                <input type="date" {...register('expiryDate', { required: true })} className={inputClass} />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Usage Limit</label>
                <input type="number" {...register('usageLimit')} placeholder="100" className={inputClass} />
              </div>
              <div className="sm:col-span-2 lg:col-span-2 flex items-end">
                <Button type="submit" icon={Plus} fullWidth>Create Coupon</Button>
              </div>
            </form>
          </Card>
        </motion.div>
      )}

      {/* Coupon Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
        {coupons.map((coupon, i) => (
          <motion.div key={coupon.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
            <Card hover className="relative overflow-hidden">
              {/* Decorative stripe */}
              <div className={`absolute top-0 left-0 right-0 h-1 ${coupon.status === 'active' ? 'bg-[#2563EB]' : 'bg-gray-300'}`} />

              <div className="flex items-start justify-between mb-4">
                <div className="flex items-center gap-3">
                  <div className={`p-2.5 rounded-xl ${coupon.type === 'percentage' ? 'bg-purple-50' : 'bg-green-50'}`}>
                    {coupon.type === 'percentage' ? <Percent size={20} className="text-purple-600" /> : <DollarSign size={20} className="text-green-600" />}
                  </div>
                  <div>
                    <p className="text-lg font-bold text-gray-900 font-mono tracking-wider">{coupon.code}</p>
                    <p className="text-xs text-gray-400">{coupon.type === 'percentage' ? `${coupon.value}% off` : `₹${coupon.value} off`}</p>
                  </div>
                </div>
                <StatusBadge status={coupon.status} size="sm" />
              </div>

              <div className="space-y-2 text-sm">
                <div className="flex justify-between"><span className="text-gray-400">Min Order</span><span className="text-gray-700 font-medium">{formatCurrency(coupon.minOrder)}</span></div>
                <div className="flex justify-between"><span className="text-gray-400">Max Discount</span><span className="text-gray-700 font-medium">{formatCurrency(coupon.maxDiscount)}</span></div>
                <div className="flex justify-between"><span className="text-gray-400">Usage</span><span className="text-gray-700 font-medium">{coupon.usageCount}/{coupon.usageLimit}</span></div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-400 flex items-center gap-1"><Calendar size={12} /> Expires</span>
                  <span className="text-gray-700 font-medium">{formatDate(coupon.expiryDate)}</span>
                </div>
              </div>

              {/* Usage Bar */}
              <div className="mt-4">
                <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                  <div className="h-full bg-[#2563EB] rounded-full transition-all" style={{ width: `${(coupon.usageCount / coupon.usageLimit) * 100}%` }} />
                </div>
              </div>

              {/* Actions */}
              <div className="flex items-center gap-2 mt-4 pt-4 border-t border-gray-50">
                <Button size="xs" variant="ghost" icon={Edit3} onClick={() => toast.success('Edit coupon')}>Edit</Button>
                <Button size="xs" variant="ghost" icon={Trash2} className="text-red-500 hover:bg-red-50"
                        onClick={() => setDeleteModal({ open: true, coupon })}>Delete</Button>
              </div>
            </Card>
          </motion.div>
        ))}
      </div>

      <ConfirmModal
        isOpen={deleteModal.open}
        onClose={() => setDeleteModal({ open: false, coupon: null })}
        onConfirm={() => { toast.success('Coupon deleted'); setDeleteModal({ open: false, coupon: null }); }}
        type="delete" title="Delete Coupon"
        message={`Delete coupon "${deleteModal.coupon?.code}"? This cannot be undone.`}
        confirmLabel="Delete Coupon"
      />
    </div>
  );
};

export default CouponList;

/**
 * Product List Page
 * Grid/Table view with search, filter, sort, pagination.
 */
import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Plus, Grid3X3, List, Edit3, Trash2, Copy, Eye, Package, MoreVertical, Star } from 'lucide-react';
import { PageHeader, StatusBadge, SearchFilter, ConfirmModal, DataTable } from '../../components/common';
import { Button, EmptyState } from '../../components/ui';
import { products } from '../../utils/dummyData';
import { formatCurrency } from '../../utils/formatters';
import usePagination from '../../hooks/usePagination';
import useDebounce from '../../hooks/useDebounce';
import toast from 'react-hot-toast';

const ProductList = () => {
  const navigate = useNavigate();
  const [viewMode, setViewMode] = useState('table');
  const [searchQuery, setSearchQuery] = useState('');
  const [filters, setFilters] = useState({});
  const [deleteModal, setDeleteModal] = useState({ open: false, product: null });
  const debouncedSearch = useDebounce(searchQuery);

  // Filter and search products
  const filteredProducts = useMemo(() => {
    let result = [...products];
    if (debouncedSearch) {
      const q = debouncedSearch.toLowerCase();
      result = result.filter((p) => p.title.toLowerCase().includes(q) || p.sku.toLowerCase().includes(q) || p.category.toLowerCase().includes(q));
    }
    if (filters.status && filters.status !== 'all') {
      result = result.filter((p) => p.status === filters.status);
    }
    if (filters.category && filters.category !== 'all') {
      result = result.filter((p) => p.category === filters.category);
    }
    return result;
  }, [debouncedSearch, filters]);

  const { paginatedData, currentPage, totalPages, pageSize, goToPage, changePageSize } = usePagination(filteredProducts, 10);

  const handleDelete = (product) => {
    setDeleteModal({ open: true, product });
  };

  const confirmDelete = () => {
    toast.success(`"${deleteModal.product?.title}" deleted successfully`);
    setDeleteModal({ open: false, product: null });
  };

  const handleDuplicate = (product) => {
    toast.success(`"${product.title}" duplicated`);
  };

  const filterConfig = [
    { key: 'status', label: 'Status', options: [
      { value: 'active', label: 'Active' }, { value: 'inactive', label: 'Inactive' },
      { value: 'out_of_stock', label: 'Out of Stock' }, { value: 'draft', label: 'Draft' },
    ]},
    { key: 'category', label: 'Category', options: [
      { value: 'Handicraft', label: 'Handicraft' }, { value: 'Food & Grocery', label: 'Food & Grocery' },
      { value: 'Clothing', label: 'Clothing' }, { value: 'Home & Living', label: 'Home & Living' },
    ]},
  ];

  // Table columns
  const columns = [
    { key: 'title', label: 'Product', render: (_, row) => (
      <div className="flex items-center gap-3 min-w-[200px]">
        <div className="w-11 h-11 bg-gray-50 rounded-xl flex items-center justify-center flex-shrink-0 border border-gray-100">
          <Package size={20} className="text-gray-300" />
        </div>
        <div>
          <p className="text-sm font-semibold text-gray-900 line-clamp-1">{row.title}</p>
          <p className="text-[11px] text-gray-400">SKU: {row.sku}</p>
        </div>
      </div>
    )},
    { key: 'category', label: 'Category', render: (val) => (
      <span className="text-xs font-medium text-gray-600 bg-gray-50 px-2.5 py-1 rounded-lg">{val}</span>
    )},
    { key: 'price', label: 'Price', render: (_, row) => (
      <div>
        <p className="text-sm font-semibold text-gray-900">{formatCurrency(row.discountPrice || row.price)}</p>
        {row.discountPrice && <p className="text-xs text-gray-400 line-through">{formatCurrency(row.price)}</p>}
      </div>
    )},
    { key: 'stock', label: 'Stock', render: (val) => (
      <div className="flex items-center gap-2">
        <span className={`text-sm font-semibold ${val === 0 ? 'text-red-500' : val < 10 ? 'text-amber-500' : 'text-gray-900'}`}>{val}</span>
        <div className="w-16 h-1.5 bg-gray-100 rounded-full overflow-hidden">
          <div className={`h-full rounded-full ${val === 0 ? 'bg-red-500' : val < 10 ? 'bg-amber-500' : 'bg-blue-500'}`}
               style={{ width: `${Math.min((val / 200) * 100, 100)}%` }} />
        </div>
      </div>
    )},
    { key: 'status', label: 'Status', align: 'center', render: (val) => <StatusBadge status={val} size="sm" /> },
    { key: 'sales', label: 'Sales', render: (val) => <span className="text-sm font-medium text-gray-600">{val}</span> },
    { key: 'actions', label: 'Actions', sortable: false, align: 'center', render: (_, row) => (
      <div className="flex items-center gap-1 justify-center">
        <button onClick={(e) => { e.stopPropagation(); navigate(`/seller/products/edit/${row.id}`); }}
                className="p-2 rounded-lg hover:bg-blue-50 text-gray-400 hover:text-blue-600 transition-colors" title="Edit">
          <Edit3 size={16} />
        </button>
        <button onClick={(e) => { e.stopPropagation(); handleDuplicate(row); }}
                className="p-2 rounded-lg hover:bg-gray-100 text-gray-400 hover:text-gray-600 transition-colors" title="Duplicate">
          <Copy size={16} />
        </button>
        <button onClick={(e) => { e.stopPropagation(); handleDelete(row); }}
                className="p-2 rounded-lg hover:bg-red-50 text-gray-400 hover:text-red-500 transition-colors" title="Delete">
          <Trash2 size={16} />
        </button>
      </div>
    )},
  ];

  return (
    <div className="space-y-6 pb-8">
      <PageHeader title="Products" subtitle={`${filteredProducts.length} products in your store`}>
        <div className="flex items-center gap-2">
          <div className="flex bg-gray-100 rounded-lg p-0.5">
            <button onClick={() => setViewMode('table')} className={`p-2 rounded-md transition-colors ${viewMode === 'table' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400'}`}>
              <List size={16} />
            </button>
            <button onClick={() => setViewMode('grid')} className={`p-2 rounded-md transition-colors ${viewMode === 'grid' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400'}`}>
              <Grid3X3 size={16} />
            </button>
          </div>
          <Button icon={Plus} onClick={() => navigate('/seller/products/add')}>Add Product</Button>
        </div>
      </PageHeader>

      <SearchFilter
        searchValue={searchQuery}
        onSearchChange={setSearchQuery}
        placeholder="Search products, SKU, category..."
        filters={filterConfig}
        activeFilters={filters}
        onFilterChange={(key, value) => setFilters((prev) => ({ ...prev, [key]: value }))}
      />

      {/* Table View */}
      {viewMode === 'table' && (
        <DataTable
          columns={columns}
          data={filteredProducts}
          onRowClick={(row) => navigate(`/seller/products/edit/${row.id}`)}
          emptyIcon="products"
          emptyTitle="No products found"
          emptyDescription="Add your first product to start selling."
        />
      )}

      {/* Grid View */}
      {viewMode === 'grid' && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5">
          <AnimatePresence>
            {filteredProducts.map((product, i) => (
              <motion.div
                key={product.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.05 }}
                onClick={() => navigate(`/seller/products/edit/${product.id}`)}
                className="bg-white rounded-2xl border border-gray-100 overflow-hidden hover:shadow-lg hover:border-blue-100 transition-all cursor-pointer group"
              >
                <div className="h-40 bg-gray-50 flex items-center justify-center relative">
                  <Package size={40} className="text-gray-200" />
                  <div className="absolute top-3 right-3"><StatusBadge status={product.status} size="sm" /></div>
                </div>
                <div className="p-4">
                  <p className="text-sm font-semibold text-gray-900 line-clamp-1 group-hover:text-blue-600 transition-colors">{product.title}</p>
                  <p className="text-xs text-gray-400 mt-1">{product.category} • SKU: {product.sku}</p>
                  <div className="flex items-center justify-between mt-3">
                    <div>
                      <p className="text-base font-bold text-gray-900">{formatCurrency(product.discountPrice || product.price)}</p>
                      {product.discountPrice && <p className="text-xs text-gray-400 line-through">{formatCurrency(product.price)}</p>}
                    </div>
                    <div className="flex items-center gap-1 text-xs text-gray-400">
                      <Star size={12} className="text-amber-400 fill-amber-400" />
                      <span>{product.rating}</span>
                    </div>
                  </div>
                  <div className="flex items-center justify-between mt-3 pt-3 border-t border-gray-50">
                    <span className={`text-xs font-medium ${product.stock === 0 ? 'text-red-500' : product.stock < 10 ? 'text-amber-500' : 'text-gray-500'}`}>
                      {product.stock === 0 ? 'Out of stock' : `${product.stock} in stock`}
                    </span>
                    <span className="text-xs text-gray-400">{product.sales} sold</span>
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>
      )}

      {filteredProducts.length === 0 && (
        <EmptyState icon="products" title="No products found" description="Try adjusting your search or filters." actionLabel="Add Product" onAction={() => navigate('/seller/products/add')} />
      )}

      <ConfirmModal
        isOpen={deleteModal.open}
        onClose={() => setDeleteModal({ open: false, product: null })}
        onConfirm={confirmDelete}
        type="delete"
        title="Delete Product"
        message={`Are you sure you want to delete "${deleteModal.product?.title}"? This action cannot be undone.`}
        confirmLabel="Delete Product"
      />
    </div>
  );
};

export default ProductList;

/**
 * Return Management Page
 */
import React, { useState, useMemo } from 'react';
import { motion } from 'framer-motion';
import { CheckCircle, XCircle, Clock, RotateCcw } from 'lucide-react';
import { PageHeader, StatusBadge, SearchFilter } from '../../components/common';
import { Card, Button } from '../../components/ui';
import { ConfirmModal } from '../../components/common';
import { returns } from '../../utils/dummyData';
import { formatCurrency, formatDate, getRelativeTime } from '../../utils/formatters';
import toast from 'react-hot-toast';

const tabs = [
  { key: 'all', label: 'All', icon: RotateCcw },
  { key: 'pending', label: 'Pending', icon: Clock },
  { key: 'approved', label: 'Approved', icon: CheckCircle },
  { key: 'rejected', label: 'Rejected', icon: XCircle },
];

const ReturnList = () => {
  const [activeTab, setActiveTab] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [confirmAction, setConfirmAction] = useState({ open: false, type: null, item: null });

  const filtered = useMemo(() => {
    let result = [...returns];
    if (activeTab !== 'all') result = result.filter((r) => r.status === activeTab);
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      result = result.filter((r) => r.orderId.toLowerCase().includes(q) || r.customer.name.toLowerCase().includes(q));
    }
    return result;
  }, [activeTab, searchQuery]);

  const handleAction = (type, item) => setConfirmAction({ open: true, type, item });

  const confirmHandler = () => {
    const action = confirmAction.type === 'approve' ? 'approved' : 'rejected';
    toast.success(`Return #${confirmAction.item?.id} has been ${action}`);
    setConfirmAction({ open: false, type: null, item: null });
  };

  return (
    <div className="space-y-6 pb-8">
      <PageHeader title="Returns & Refunds" subtitle={`${returns.length} return requests`} />

      <div className="flex gap-2 overflow-x-auto">
        {tabs.map((tab) => (
          <button key={tab.key} onClick={() => setActiveTab(tab.key)}
            className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-medium whitespace-nowrap transition-all ${
              activeTab === tab.key ? 'bg-[#2563EB] text-white shadow-sm' : 'bg-white text-gray-500 border border-gray-200 hover:bg-gray-50'}`}>
            <tab.icon size={16} /> {tab.label}
          </button>
        ))}
      </div>

      <SearchFilter searchValue={searchQuery} onSearchChange={setSearchQuery} placeholder="Search by order ID or customer..." />

      <div className="space-y-4">
        {filtered.map((ret, i) => (
          <motion.div key={ret.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
            <Card className="hover:border-gray-200 transition-colors">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-2">
                    <span className="text-sm font-bold text-blue-600">#{ret.id}</span>
                    <StatusBadge status={ret.status} />
                    <span className="text-xs text-gray-400">Order #{ret.orderId}</span>
                  </div>
                  <p className="text-sm font-medium text-gray-900">{ret.product.title}</p>
                  <p className="text-xs text-gray-500 mt-1">Customer: {ret.customer.name} • Requested: {getRelativeTime(new Date(ret.requestedAt))}</p>
                  <p className="text-xs text-gray-500 mt-1">Reason: <span className="text-gray-700">{ret.reason}</span></p>
                  <p className="text-sm font-semibold text-gray-900 mt-2">Refund: {formatCurrency(ret.refundAmount)}</p>
                </div>
                {ret.status === 'pending' && (
                  <div className="flex items-center gap-2">
                    <Button variant="success" size="sm" icon={CheckCircle} onClick={() => handleAction('approve', ret)}>Approve</Button>
                    <Button variant="danger" size="sm" icon={XCircle} onClick={() => handleAction('reject', ret)}>Reject</Button>
                  </div>
                )}
              </div>

              {/* Timeline */}
              {ret.timeline && ret.timeline.length > 0 && (
                <div className="mt-4 pt-4 border-t border-gray-50">
                  <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Timeline</p>
                  <div className="space-y-2">
                    {ret.timeline.map((entry, j) => (
                      <div key={j} className="flex items-center gap-3 text-xs">
                        <span className="w-1.5 h-1.5 rounded-full bg-blue-400" />
                        <span className="text-gray-500">{formatDate(entry.date, 'long')}</span>
                        <span className="text-gray-700">{entry.event}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </Card>
          </motion.div>
        ))}

        {filtered.length === 0 && (
          <div className="text-center py-16">
            <RotateCcw size={40} className="text-gray-200 mx-auto mb-4" />
            <p className="text-gray-500">No return requests found</p>
          </div>
        )}
      </div>

      <ConfirmModal
        isOpen={confirmAction.open}
        onClose={() => setConfirmAction({ open: false, type: null, item: null })}
        onConfirm={confirmHandler}
        type={confirmAction.type === 'approve' ? 'save' : 'warning'}
        title={confirmAction.type === 'approve' ? 'Approve Return' : 'Reject Return'}
        message={`Are you sure you want to ${confirmAction.type} this return request?`}
        confirmLabel={confirmAction.type === 'approve' ? 'Approve' : 'Reject'}
      />
    </div>
  );
};

export default ReturnList;

import React, { useState, useRef, useEffect } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, Camera, Mic, ScanLine, MapPin, ChevronDown, Zap, X, Star } from 'lucide-react';
import LanguageSelector from './LanguageSelector';
import { useTranslation } from 'react-i18next';
import SearchInput from '../../../../shared/components/SearchInput';
import toast from 'react-hot-toast';

/**
 * SearchBar — Address selector (top) + Search input (bottom)
 * Styled exactly like the reference image
 */
const SearchBar = ({ selectedAddress }) => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const location = useLocation();
  const [query, setQuery] = useState('');
  const [searchFocused, setSearchFocused] = useState(false);
  const [isListening, setIsListening] = useState(false);

  // Functional scanner & camera search states
  const [isScanning, setIsScanning] = useState(false);
  const [isAnalyzingImage, setIsAnalyzingImage] = useState(false);
  const [stream, setStream] = useState(null);
  const fileInputRef = useRef(null);
  const videoRef = useRef(null);

  const isMithilakActive = location.pathname.includes('/mithilak');
  const isFreshGroceryActive = location.pathname.includes('/fresh-grocery');
  const isQuickShopActive = location.pathname.includes('/quick-shop') && !isMithilakActive;

  const isDarkHeader = isMithilakActive || isQuickShopActive;
  const isMithilakartFlow = !isMithilakActive && !isFreshGroceryActive && !isQuickShopActive;

  const handleSubmit = (e) => {
    e?.preventDefault();
    if (query.trim()) navigate(`/search?q=${encodeURIComponent(query.trim())}`);
  };

  const handleVoiceSearch = () => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice recognition is not supported in this browser. Please use Chrome or Safari.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-IN';
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;

    recognition.onstart = () => {
      setIsListening(true);
    };

    recognition.onresult = (event) => {
      const speechToText = event.results[0][0].transcript;
      setQuery(speechToText);
      navigate(`/search?q=${encodeURIComponent(speechToText)}`);
    };

    recognition.onerror = (e) => {
      console.error(e);
      setIsListening(false);
    };

    recognition.onend = () => {
      setIsListening(false);
    };

    recognition.start();
  };

  // Camera search handler
  const handleCameraClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsAnalyzingImage(true);
      toast.loading("Analyzing image for matching products...", { id: "img-search" });
      
      // Simulate frontend search recognition
      setTimeout(() => {
        setIsAnalyzingImage(false);
        toast.dismiss("img-search");
        toast.success("Image analyzed! Found matching handcrafted item.");
        navigate('/search?q=Mithila%20Painting');
      }, 2000);
    }
  };

  // Scanner modal handlers
  const startScanner = async () => {
    setIsScanning(true);
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment' }
      });
      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
      }
      
      // Simulate barcode scan after 3 seconds
      setTimeout(() => {
        toast.success("Barcode detected: SKU-MITHILA-09");
        stopScanner();
        navigate('/search?q=Jewellery');
      }, 3000);
    } catch (err) {
      console.warn("Webcam not available, running in simulation mode", err);
      // Mock scanner simulation if no webcam
      setTimeout(() => {
        toast.success("Simulated scan completed successfully!");
        stopScanner();
        navigate('/search?q=Watch');
      }, 3500);
    }
  };

  const stopScanner = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
    }
    setStream(null);
    setIsScanning(false);
  };

  useEffect(() => {
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [stream]);

  const displayAddress = selectedAddress?.address
    ? selectedAddress.address.slice(0, 32)
    : '83 Kishan Pura Mataji Mandir, Indore';

  return (
    <div className="px-3 pb-2 flex flex-col gap-1.5 md:px-4 md:pb-3 md:flex-col md:gap-3">
      {/* Hidden file input for camera upload */}
      <input 
        type="file" 
        accept="image/*" 
        ref={fileInputRef} 
        onChange={handleFileChange} 
        className="hidden" 
      />


      <div className="flex items-center justify-between py-0.5 md:py-2">
        {isFreshGroceryActive ? (
          <Link
            to="/profile/addresses"
            className="flex items-center gap-1 min-w-0 text-white hover:text-white/95"
          >
            <MapPin size={13} strokeWidth={2.5} className="w-[13px] h-[13px] flex-shrink-0 text-white" />
            <span className="text-[10px] md:text-[11px] font-bold truncate max-w-[170px] md:max-w-[220px]">
              {displayAddress}
            </span>
            <ChevronDown size={11} strokeWidth={3} className="w-[11px] h-[11px] flex-shrink-0 text-white" />
          </Link>
        ) : isMithilakActive ? (
          <Link
            to="/profile/addresses"
            className="flex items-center gap-1 min-w-0 text-white/95 hover:text-white"
          >
            <MapPin size={13} strokeWidth={2.5} className="w-[13px] h-[13px] md:w-[14px] md:h-[14px] flex-shrink-0" />
            <span className="text-[11.5px] font-bold truncate max-w-[180px] md:max-w-[220px]">
              {displayAddress}
            </span>
            <ChevronDown size={11} strokeWidth={3} className="w-[11px] h-[11px] md:w-[12px] md:h-[12px] flex-shrink-0" />
          </Link>
        ) : (
          <Link
            to="/profile/addresses"
            className="flex items-center gap-1.5 min-w-0 text-white/95 hover:opacity-85 transition-opacity"
          >
            <MapPin size={13} strokeWidth={2.5} className="w-[13px] h-[13px] md:w-[14px] md:h-[14px] flex-shrink-0" />
            <span className="text-[10px] md:text-[11px] font-bold truncate max-w-[170px] md:max-w-[220px]">
              {displayAddress}
            </span>
            <ChevronDown size={11} strokeWidth={3} className="w-[11px] h-[11px] md:w-[12px] md:h-[12px] flex-shrink-0" />
          </Link>
        )}

        {/* Language Pill + Coin/Star Badge */}
        <div className="flex items-center gap-2">
          {/* Functional language selector button */}
          <LanguageSelector isDarkHeader={false} variant={isMithilakActive ? "mithila" : ""} compact={true} />
          
          {/* Custom Coins/Stars Badge */}
          {isFreshGroceryActive ? (
            <div className="flex items-center gap-0.5 px-2 py-0.5 bg-white/20 border border-white/10 rounded-full text-white font-bold text-[10.5px] shadow-xs">
              <span className="flex items-center gap-0.5">✦ 3</span>
            </div>
          ) : isMithilakActive ? (
            <div className="flex items-center gap-0.5 px-2 py-0.5 bg-[#207C8A] border border-white/20 rounded-full text-white font-extrabold text-[11px] shadow-xs">
              <Star size={11} className="text-yellow-300 fill-yellow-300" />
              <span>3</span>
            </div>
          ) : (
            <div className={`flex items-center gap-0.5 px-2 py-0.5 rounded-full text-white border border-[#FFF8EE]/20 shadow-xs ${
              isQuickShopActive ? 'bg-[#D45014]' : 'bg-[#3E5A44]'
            }`}>
              <Star size={11} className="text-yellow-300 fill-yellow-300" />
              <span className="text-[11px] font-extrabold">3</span>
            </div>
          )}
        </div>
      </div>

      {/* ── Search + Scan Field ── */}
      <div className="flex items-center gap-1.5 md:gap-2">
        <form onSubmit={handleSubmit} className="flex-1">
          <SearchInput
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onFocus={() => {
              setSearchFocused(true);
              if (!location.pathname.includes('/search')) {
                navigate('/search');
              }
            }}
            onBlur={() => setSearchFocused(false)}
            placeholder={isAnalyzingImage ? "Analyzing image..." : (isListening ? "Listening..." : (isFreshGroceryActive ? t('nav.searchInGrocery') : "Search for products, categories..."))}
            disabled={isAnalyzingImage}
            className="rounded-full shadow-xs"
            rightElement={
              <div className="flex items-center gap-2.5 md:gap-4 pr-1 text-[#3F2A20]/60">
                {!isFreshGroceryActive && (
                  <Camera 
                    size={16} 
                    strokeWidth={2.2} 
                    onClick={handleCameraClick}
                    className="cursor-pointer hover:text-[#3F2A20] transition-colors" 
                  />
                )}
                <Mic 
                  size={16} 
                  strokeWidth={2.2} 
                  onClick={handleVoiceSearch}
                  className={`cursor-pointer hover:text-[#3F2A20] transition-colors ${
                    isListening
                      ? 'text-red-500 animate-pulse'
                      : ''
                  }`} 
                />
              </div>
            }
          />
        </form>
      </div>

      {/* ── Premium Barcode Scanner Modal Overlay ── */}
      <AnimatePresence>
        {isScanning && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/90 backdrop-blur-md z-[999] flex flex-col items-center justify-center p-4"
          >
            <div className="absolute top-4 right-4">
              <button 
                onClick={stopScanner}
                className="p-3 bg-white/10 rounded-full text-white hover:bg-white/20 transition-colors"
              >
                <X size={24} />
              </button>
            </div>

            <div className="w-full max-w-sm flex flex-col items-center text-center space-y-6">
              <div>
                <h3 className="text-lg font-black text-white uppercase tracking-wider">Barcode / QR Scanner</h3>
                <p className="text-xs text-slate-400 mt-1 font-medium">Align the barcode inside the target box to scan</p>
              </div>

              {/* Viewport Box */}
              <div className="relative w-64 h-64 border-2 border-white/20 rounded-3xl overflow-hidden bg-slate-900 shadow-2xl flex items-center justify-center">
                {stream ? (
                  <video 
                    ref={videoRef} 
                    autoPlay 
                    playsInline 
                    muted 
                    className="w-full h-full object-cover" 
                  />
                ) : (
                  <div className="flex flex-col items-center justify-center space-y-3">
                    <div className="w-10 h-10 border-4 border-t-blue-500 border-white/10 rounded-full animate-spin"></div>
                    <span className="text-[11px] text-slate-500 font-semibold uppercase tracking-wider">Starting camera feed...</span>
                  </div>
                )}

                {/* Laser Animation */}
                <div className="absolute inset-x-0 h-0.5 bg-red-500 shadow-[0_0_8px_#ef4444] top-1/2 animate-bounce"></div>
                {/* Scanner Target Corners */}
                <div className="absolute top-4 left-4 w-6 h-6 border-t-4 border-l-4 border-blue-500 rounded-tl-lg"></div>
                <div className="absolute top-4 right-4 w-6 h-6 border-t-4 border-r-4 border-blue-500 rounded-tr-lg"></div>
                <div className="absolute bottom-4 left-4 w-6 h-6 border-b-4 border-l-4 border-blue-500 rounded-bl-lg"></div>
                <div className="absolute bottom-4 right-4 w-6 h-6 border-b-4 border-r-4 border-blue-500 rounded-br-lg"></div>
              </div>

              <div className="text-xs font-semibold text-slate-500 uppercase tracking-widest animate-pulse">
                Analyzing barcode pattern...
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default SearchBar;

import React, { useState, useEffect, useRef } from 'react';
import { Link, Outlet, useLocation, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import {
  ShoppingCart,
  User,
  Home as HomeIcon,
  LayoutGrid,
  ChevronRight,
} from 'lucide-react';

import MainSidebar from '../components/common/MainSidebar';
import HeaderTop from '../components/common/HeaderTop';
import HeaderTabs from '../components/common/HeaderTabs';
import SearchBar from '../components/common/SearchBar';
import CategoryNavbar from '../components/common/CategoryNavbar';
import LanguageSelector from '../components/common/LanguageSelector';
import useAccountStore from '../../../store/useAccountStore';
import useVendorStore from '../../../store/useVendorStore';
import { useTranslation } from 'react-i18next';
import { parsePrice, formatPrice } from '../../../shared/utils/priceFormatter';
import Footer from '../../../shared/components/Footer';

const getMithilakartHeaderBg = (category) => {
  switch (category) {
    case 'Beauty':
      return 'bg-[#F9A8D4]'; // Soft Rose Pink
    case 'Gifting':
      return 'bg-[#D8B4FE]'; // Soft Purple
    case 'Electronics':
      return 'bg-[#93C5FD]'; // Soft Blue
    case 'Jewellery':
      return 'bg-[#FDBA74]'; // Soft Orange/Peach
    case 'Toys':
      return 'bg-[#99F6E4]'; // Soft Teal
    case 'Stationery':
      return 'bg-[#C7D2FE]'; // Soft Indigo
    case 'Fashion':
      return 'bg-[#FCA5A5]'; // Soft Red
    case 'Electrical':
      return 'bg-[#FEF08A]'; // Soft Yellow
    case 'You Buy':
    default:
      return 'bg-[#3E5A44]'; // Default Olive Green
  }
};

const VendorLayout = () => {
  const { t } = useTranslation();
  const location = useLocation();
  const navigate = useNavigate();
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [cartCount, setCartCount] = useState(0);
  const [cartItems, setCartItems] = useState([]);
  const [scrolled, setScrolled] = useState(false);
  const { savedAddresses, selectedAddressId, isDarkMode } = useAccountStore();
  const { selectedCategory, setSelectedCategory } = useVendorStore();
  const selectedAddress = savedAddresses.find(a => a.id === selectedAddressId) || savedAddresses[0];

  /* ── Cart listener ── */
  useEffect(() => {
    const updateCart = () => {
      try {
        const cart = JSON.parse(localStorage.getItem('userCart') || '[]');
        setCartItems(cart);
        const total = cart.reduce((acc, item) => acc + (item.qty || 1), 0);
        setCartCount(total);
      } catch {
        setCartItems([]);
        setCartCount(0);
      }
    };
    updateCart();
    window.addEventListener('cartUpdated', updateCart);
    return () => window.removeEventListener('cartUpdated', updateCart);
  }, []);

  /* ── Scroll shadow listener ── */
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 4);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const isImmersivePage =
    location.pathname.includes('categories') ||
    location.pathname.includes('category-products') ||
    location.pathname.includes('product-detail') ||
    location.pathname.includes('continue-shopping') ||
    location.pathname.includes('all-offers') ||
    location.pathname.includes('cart') ||
    location.pathname.includes('/profile') ||
    location.pathname.includes('/deals') ||
    location.pathname.includes('/search') ||
    location.pathname.includes('/category') ||
    location.pathname.includes('wishlist');

  const hideHeader = isImmersivePage;
  const hideFooter  = isImmersivePage && !location.pathname.includes('all-offers') && !location.pathname.includes('categories');

  const isCartOrCheckoutPage = location.pathname.includes('/cart') || location.pathname.includes('/checkout');
  const cartTotalItems = cartItems.reduce((acc, item) => acc + (item.qty || 1), 0);
  const cartTotalPrice = cartItems.reduce((acc, item) => {
    return acc + parsePrice(item.price) * parsePrice(item.qty || 1);
  }, 0);
  const isDarkHeader = (
    localStorage.getItem('isMithilakFlow') === 'true' || 
    location.pathname.includes('/mithilak') || 
    (location.pathname.includes('/quick-shop') && !location.pathname.includes('/fresh-grocery')) ||
    (!location.pathname.includes('/quick-shop') && !location.pathname.includes('/fresh-grocery') && (selectedCategory === 'You Buy' || selectedCategory === 'Home' || !selectedCategory))
  );

  const isMithilakartFlow = 
    !location.pathname.includes('/mithilak') && 
    !location.pathname.includes('/quick-shop') && 
    !location.pathname.includes('/fresh-grocery');

  return (
    <div className={`min-h-screen flex flex-col transition-colors duration-300 text-primary-dark relative ${
      (localStorage.getItem('isMithilakFlow') === 'true' || location.pathname.includes('/mithilak'))
        ? 'bg-[#F5F9FA]'
        : location.pathname.includes('/fresh-grocery')
          ? 'bg-[#FFF8EE]'
          : location.pathname.includes('/quick-shop')
            ? 'bg-white'
            : 'bg-[#F6F8F3]'
    }`}>
      {/* Global Repeating Mithila Art Page Background Texture */}
      <div 
        className="fixed inset-0 pointer-events-none z-30 bg-repeat opacity-[0.035] select-none"
        style={{
          backgroundImage: "url('/Screenshot 2026-07-17 130906.png')",
          backgroundSize: '360px',
        }}
      />

      {/* Drawer Sidebar */}
      <MainSidebar isOpen={isDrawerOpen} onClose={() => setIsDrawerOpen(false)} />

      {/* Desktop Header */}
      {!hideHeader && (
        <div className={`hidden md:flex items-center justify-between px-8 py-2.5 border-b border-gray-200/80 sticky top-0 z-50 shadow-sm transition-colors duration-300 ${
          (localStorage.getItem('isMithilakFlow') === 'true' || location.pathname.includes('/mithilak'))
            ? 'bg-gradient-to-r from-[#8b5cf6] to-[#6366f1] text-white'
            : location.pathname.includes('/fresh-grocery')
              ? 'bg-[#D9A21B] text-[#3F2A20]'
              : location.pathname.includes('/quick-shop')
                ? 'bg-gradient-to-r from-[#ff2a5f] to-[#ff7e5f] text-white'
                : `${getMithilakartHeaderBg(selectedCategory)} ${
                    selectedCategory === 'You Buy' || selectedCategory === 'Home' || !selectedCategory
                      ? 'text-white'
                      : 'text-slate-800'
                  }`
        }`}>
          <div className="flex items-center gap-8 max-w-[1600px] mx-auto w-full">
            <Link to="/home" className="flex items-center gap-2 flex-shrink-0">
              <span className="text-2xl font-black tracking-tight">Mithilakart</span>
            </Link>

            {/* Desktop Header Flow Tabs */}
            <div className="w-[360px] flex-shrink-0 scale-95 origin-left">
              <HeaderTabs />
            </div>

            <nav className="flex items-center gap-3 ml-4">
              <Link to="/home" className={`text-[14px] font-black px-3.5 py-1.5 rounded-xl transition-all duration-200 hover:bg-black/5 text-[#3F2A20]`}>{t('nav.home')}</Link>
              <Link to="/categories" className={`text-[14px] font-black px-3.5 py-1.5 rounded-xl transition-all duration-200 hover:bg-black/5 text-[#3F2A20]`}>{t('nav.categories')}</Link>
              <Link to="/cart" className={`text-[14px] font-black px-3.5 py-1.5 rounded-xl transition-all duration-200 flex items-center gap-2 hover:bg-black/5 text-[#3F2A20]`}>
                <span>{t('nav.cart')}</span>
                <span className="text-[10px] px-2 py-0.5 rounded-full font-black bg-[#F26522] text-white">{cartCount}</span>
              </Link>
              <Link to="/profile" className={`text-[14px] font-black px-3.5 py-1.5 rounded-xl transition-all duration-200 hover:bg-black/5 text-[#3F2A20]`}>Profile</Link>
            </nav>

            <div className="ml-auto flex items-center gap-6">
              <LanguageSelector isDarkHeader={isDarkHeader} />
              <div className="text-sm font-semibold flex items-center gap-1 opacity-90">
                <span>📍 {t('nav.deliverTo')}</span>
                <span className="font-bold truncate max-w-[200px]">{selectedAddress?.name || 'Indrapuri Colony, Indore'}</span>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Sticky Header */}
      {!hideHeader && (
        <motion.header
          animate={{
            boxShadow: scrolled
              ? '0 2px 12px rgba(0,0,0,0.08)'
              : '0 1px 0px rgba(0,0,0,0.02)',
          }}
          transition={{ duration: 0.22 }}
          className={`md:hidden sticky top-0 z-50 pb-2 rounded-b-[20px] transition-colors duration-300 ${
            (localStorage.getItem('isMithilakFlow') === 'true' || location.pathname.includes('/mithilak'))
              ? 'bg-[#207C8A]'
              : location.pathname.includes('/fresh-grocery')
                ? 'bg-[#D9A21B]'
                : location.pathname.includes('/quick-shop')
                  ? 'bg-[#F26522]'
                  : 'bg-[#3E5A44]'
          }`}
        >


          {/* Restored HeaderTabs as requested */}
          <HeaderTabs />

          {/* Row 3 : Search + QR */}
          <SearchBar selectedAddress={selectedAddress} />
        </motion.header>
      )}

      {/* SaleBanner is now rendered inside Home.jsx or specifically based on visibility store */}

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col bg-transparent relative z-10">
        <div className="flex-1 flex">
          <div className="w-full max-w-[1600px] mx-auto px-0 md:px-8 xl:px-12 flex h-full">
            <main className="flex-1 min-w-0 pb-16">
              <Outlet />
            </main>
          </div>
        </div>
        {!location.pathname.includes('/profile') && <Footer />}
      </div>

      {/* Mobile-First Bottom Navbar (Fixed) */}
      {!hideFooter && (
        <nav className="md:hidden fixed bottom-0 left-0 right-0 border-t px-6 py-2 flex justify-between items-center z-50 bg-[#FFF8EE] border-[#EADCC9]/55 text-[#3F2A20] shadow-[0_-2px_10px_rgba(63,42,32,0.05)]">
        <Link 
          to={(localStorage.getItem('isMithilakFlow') === 'true' || location.pathname.includes('/mithilak')) ? "/mithilak" : "/home"} 
          onClick={() => {
            if (!(localStorage.getItem('isMithilakFlow') === 'true' || location.pathname.includes('/mithilak'))) {
              localStorage.setItem('isQuickShopFlow', 'false');
              localStorage.setItem('isMithilakFlow', 'false');
              localStorage.setItem('isFreshGroceryFlow', 'false');
            }
          }}
          className={`flex flex-col items-center transition-transform active:scale-90 ${
            location.pathname === '/home' || location.pathname === '/quick-shop' || location.pathname === '/mithilak' || location.pathname === '/fresh-grocery'
              ? ((localStorage.getItem('isMithilakFlow') === 'true' || location.pathname === '/mithilak') 
                  ? 'text-[#207C8A]' 
                  : (localStorage.getItem('isFreshGroceryFlow') === 'true' ? 'text-[#D9A21B]' : (localStorage.getItem('isQuickShopFlow') === 'true' ? 'text-[#FF5C00]' : 'text-[#3E5A44]')))
              : 'text-[#3F2A20]/80'
          }`}
        >
          <HomeIcon size={22} strokeWidth={2.2} />
          <span className={`text-[10px] ${location.pathname === '/home' || location.pathname === '/quick-shop' || location.pathname === '/mithilak' || location.pathname === '/fresh-grocery' ? 'font-black' : 'font-semibold'}`}>Home</span>
        </Link>
        <Link 
          to="/categories"
          className={`flex flex-col items-center transition-transform active:scale-90 ${
            location.pathname === '/categories' 
              ? ((localStorage.getItem('isMithilakFlow') === 'true' || location.pathname.includes('/mithilak')) 
                  ? 'text-[#207C8A]' 
                  : (localStorage.getItem('isFreshGroceryFlow') === 'true' ? 'text-[#D9A21B]' : 'text-[#3E5A44]')) 
              : 'text-[#3F2A20]/80'
          }`}
        >
          <LayoutGrid size={22} strokeWidth={2.2} />
          <span className={`text-[10px] ${location.pathname === '/categories' ? 'font-black' : 'font-semibold'}`}>Categories</span>
        </Link>
        <Link 
          to="/cart" 
          className={`flex flex-col items-center transition-transform active:scale-90 ${
            location.pathname === '/cart' 
              ? ((localStorage.getItem('isMithilakFlow') === 'true' || location.pathname.includes('/mithilak')) 
                  ? 'text-[#207C8A]' 
                  : (localStorage.getItem('isFreshGroceryFlow') === 'true' ? 'text-[#D9A21B]' : 'text-[#3E5A44]')) 
              : 'text-[#3F2A20]/80'
          }`}
        >
          <div className="relative">
            <ShoppingCart size={22} strokeWidth={2.2} />
            <span className="absolute -top-1.5 -right-2 text-[8px] font-black px-1 py-0.5 rounded-full bg-[#F26522] text-white border border-[#FFF8EE]">
              {cartCount}
            </span>
          </div>
          <span className={`text-[10px] ${location.pathname === '/cart' ? 'font-black' : 'font-semibold'}`}>Cart</span>
        </Link>
        <Link 
          to="/profile" 
          className={`flex flex-col items-center transition-transform active:scale-90 ${
            location.pathname === '/profile' 
              ? ((localStorage.getItem('isMithilakFlow') === 'true' || location.pathname.includes('/mithilak')) 
                  ? 'text-[#207C8A]' 
                  : (localStorage.getItem('isFreshGroceryFlow') === 'true' ? 'text-[#D9A21B]' : 'text-[#3E5A44]')) 
              : 'text-[#3F2A20]/80'
          }`}
        >
          <User size={22} strokeWidth={2.2} />
          <span className={`text-[10px] ${location.pathname === '/profile' ? 'font-black' : 'font-semibold'}`}>You</span>
        </Link>
      </nav>
      )}

      {/* Floating Cart Pill (Shows on all pages when cart has items, except cart/checkout page) */}
      {!isCartOrCheckoutPage && cartTotalItems > 0 && (
        <div 
          onClick={() => navigate('/vendor/cart')}
          className={`fixed bottom-[76px] left-4 right-4 md:bottom-8 md:right-8 md:left-auto md:w-[380px] md:px-6 md:py-4 md:rounded-2xl z-[1000] rounded-2xl px-5 py-3.5 flex items-center justify-between shadow-[0_8px_30px_rgba(0,0,0,0.15)] text-white cursor-pointer active:scale-[0.98] transition-all duration-300 animate-in slide-in-from-bottom-6 ${
            localStorage.getItem('isFreshGroceryFlow') === 'true'
              ? 'bg-gradient-to-r from-[#7A3E17] to-[#b45309] hover:brightness-110'
              : localStorage.getItem('isMithilakFlow') === 'true'
                ? 'bg-gradient-to-r from-[#8b5cf6] to-[#6366f1] hover:brightness-110'
                  : localStorage.getItem('isQuickShopFlow') === 'true'
                    ? 'bg-gradient-to-r from-[#ff2a5f] to-[#ff7e5f] hover:brightness-110'
                  : 'bg-[#3E5A44] hover:bg-[#06331b]'
          }`}
        >
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-xl bg-white/15 flex items-center justify-center">
              <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
              </svg>
            </div>
            <div>
              <p className="text-[13.5px] font-black leading-none">
                {cartTotalItems} {cartTotalItems === 1 ? t('cart.item') : t('cart.items')}
              </p>
              <p className="text-[11.5px] font-bold text-white/85 mt-0.5">
                {formatPrice(cartTotalPrice)}
              </p>
            </div>
          </div>
          <div className={`flex items-center gap-1 px-3.5 py-2 rounded-xl text-[11px] font-black uppercase tracking-wider transition-colors duration-300 ${
            localStorage.getItem('isQuickShopFlow') === 'true'
              ? 'bg-white text-[#d6186d]'
              : 'bg-white/20 text-white'
          }`}>
            <span>{t('nav.viewCart')}</span>
            <ChevronRight size={13} strokeWidth={3} />
          </div>
        </div>
      )}
    </div>
  );
};

export default VendorLayout;

import React, { useState, useEffect } from 'react';
import {
  ShoppingCart, ChevronRight, CheckCircle, Info, Trash2,
  ArrowLeft, ShieldCheck, MapPin, Truck, Star, Heart, Zap, X
} from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { parsePrice, formatPrice } from '../../../shared/utils/priceFormatter';

const Cart = () => {
  const { t } = useTranslation();
  const [cartItems, setCartItems] = useState([]);
  const navigate = useNavigate();

  // Authentication and address flow states
  const [isAuthenticated, setIsAuthenticated] = useState(localStorage.getItem('isAuthenticated') === 'true');
  const [address, setAddress] = useState(() => {
    const saved = localStorage.getItem('cartAddress');
    if (saved) return JSON.parse(saved);
    // If user is already logged in on mount, auto-assign default address
    if (localStorage.getItem('isAuthenticated') === 'true') {
      const defaultAddr = {
        name: 'Harsh Pandey',
        phone: '9876543210',
        address: '83 Kishan Pura Mataji Mandir, Sector No. 5 New Harsud Chh...'
      };
      localStorage.setItem('cartAddress', JSON.stringify(defaultAddr));
      return defaultAddr;
    }
    return null;
  });

  const [showAddressModal, setShowAddressModal] = useState(false);
  const [addrName, setAddrName] = useState('');
  const [addrPhone, setAddrPhone] = useState('');
  const [addrDetails, setAddrDetails] = useState('');

  const isMithilakFlow = localStorage.getItem('isMithilakFlow') === 'true';
  const isQuickShopFlow = localStorage.getItem('isQuickShopFlow') === 'true';
  const isFreshGroceryFlow = localStorage.getItem('isFreshGroceryFlow') === 'true';
  const primaryBg = isMithilakFlow ? 'bg-[#207C8A] hover:bg-[#185e68]' : (isFreshGroceryFlow ? 'bg-[#D9A21B] hover:bg-[#c49218]' : (isQuickShopFlow ? 'bg-[#d6186d] hover:bg-[#b5125b]' : 'bg-[#3E5A44] hover:bg-[#06331b]'));
  const primaryText = isMithilakFlow ? 'text-[#207C8A]' : (isFreshGroceryFlow ? 'text-[#D9A21B]' : (isQuickShopFlow ? 'text-[#d6186d]' : 'text-[#3E5A44]'));
  const shopNowLink = isMithilakFlow ? '/mithilak' : (isFreshGroceryFlow ? '/fresh-grocery' : (isQuickShopFlow ? '/quick-shop' : '/vendor/home'));

  // Load cart items for all users (authenticated or not)
  useEffect(() => {
    try {
      const items = JSON.parse(localStorage.getItem('userCart') || '[]');
      setCartItems(items);
    } catch (e) {
      console.error("Failed to load cart", e);
    }
  }, []);

  // Re-sync auth & address state when returning from login page
  useEffect(() => {
    const syncAuthState = () => {
      const authNow = localStorage.getItem('isAuthenticated') === 'true';
      setIsAuthenticated(authNow);
      if (authNow) {
        const savedAddr = localStorage.getItem('cartAddress');
        if (savedAddr) {
          setAddress(JSON.parse(savedAddr));
        } else {
          // Auto-assign default address for logged-in users without one
          const defaultAddr = {
            name: 'Harsh Pandey',
            phone: '9876543210',
            address: '83 Kishan Pura Mataji Mandir, Sector No. 5 New Harsud Chh...'
          };
          localStorage.setItem('cartAddress', JSON.stringify(defaultAddr));
          setAddress(defaultAddr);
        }
      }
    };

    // Listen for popstate (back/forward navigation) and focus (tab switch back)
    window.addEventListener('popstate', syncAuthState);
    window.addEventListener('focus', syncAuthState);
    // Also run on mount in case we just returned from login
    syncAuthState();

    return () => {
      window.removeEventListener('popstate', syncAuthState);
      window.removeEventListener('focus', syncAuthState);
    };
  }, []);

  const handleRemove = (cartId) => {
    const updated = cartItems.filter(item => item.cartId !== cartId);
    setCartItems(updated);
    localStorage.setItem('userCart', JSON.stringify(updated));
    window.dispatchEvent(new Event('cartUpdated'));
  };

  const updateQuantity = (cartId, delta) => {
    const updated = cartItems.map(item => {
      if (item.cartId === cartId) {
        const newQty = Math.max(1, (item.qty || 1) + delta);
        return { ...item, qty: newQty };
      }
      return item;
    });
    setCartItems(updated);
    localStorage.setItem('userCart', JSON.stringify(updated));
    window.dispatchEvent(new Event('cartUpdated'));
  };

  const totalPrice = cartItems.reduce((acc, item) => {
    return acc + parsePrice(item.price) * parsePrice(item.qty || 1);
  }, 0);

  const totalOldPrice = cartItems.reduce((acc, item) => {
    return acc + parsePrice(item.oldPrice) * parsePrice(item.qty || 1);
  }, 0);

  const savings = totalOldPrice - totalPrice;
  const shippingCost = totalPrice > 500 ? 0 : 39;

  return (
    <div className={`min-h-screen pb-32 font-sans text-slate-800 flex flex-col transition-colors duration-300 relative ${
      isFreshGroceryFlow ? 'bg-[#FFF8EE]' : isMithilakFlow ? 'bg-[#F5F9FA]' : 'bg-bg-cream'
    }`}>
      {/* Global Repeating Mithila Art Page Background Texture */}
      {(isFreshGroceryFlow || !(isMithilakFlow || isQuickShopFlow)) && (
        <div 
          className="fixed inset-0 pointer-events-none z-0 bg-repeat opacity-[0.03] select-none"
          style={{
            backgroundImage: "url('/Screenshot 2026-07-17 130906.png')",
            backgroundSize: '360px',
          }}
        />
      )}

      {/* Header */}
      <div className={`sticky top-0 z-[100] px-4 py-3 flex items-center justify-between border-b transition-colors duration-300 relative ${
        isFreshGroceryFlow 
          ? 'bg-[#D9A21B] border-transparent text-white' 
          : isMithilakFlow
            ? 'bg-[#207C8A] border-transparent text-white'
            : 'bg-[#FCF7EE] border-[#F3E3CD]/60'
      }`}>
        <button 
          onClick={() => navigate(-1)} 
          className="w-10 h-10 rounded-full bg-white shadow-sm flex items-center justify-center text-slate-800 active:scale-95 transition-transform border border-slate-100/50"
        >
          <ArrowLeft size={18} strokeWidth={2.5} />
        </button>
        <h1 className={`text-[17px] font-black tracking-tight ${isMithilakFlow ? 'text-white' : 'text-slate-800'}`}>{t('nav.cart')}</h1>
        <div className="w-10 h-10 rounded-full bg-white shadow-sm flex items-center justify-center text-slate-400 border border-slate-100/50 font-bold select-none cursor-pointer">
          •••
        </div>
      </div>

      {/* Main Content Area */}
      <div className={`relative z-10 ${cartItems.length === 0 ? "flex-1 flex flex-col justify-center px-4 mt-2" : "px-4 mt-2"}`}>
        {cartItems.length === 0 ? (
          <div className="bg-white rounded-[28px] text-center py-20 px-6 flex flex-col items-center justify-center shadow-sm border border-slate-100/50 animate-in fade-in duration-300">
            {/* Custom Empty Cart Illustration */}
            <svg width="200" height="200" viewBox="0 0 200 200" fill="none" xmlns="http://www.w3.org/2000/svg" className="mx-auto mb-4">
              {/* Floating Sparkles */}
              <path d="M40 85h6v-6h2v6h6v2h-6v6h-2v-6h-6v-2z" fill="#9ca3af" />
              <path d="M80 35h4v-4h2v4h4v2h-4v4h-2v-4h-4v-2z" fill="#9ca3af" />
              <path d="M150 100h4v-4h2v4h4v2h-4v4h-2v-4h-4v-2z" fill="#9ca3af" />
              <path d="M60 145h4v-4h2v4h4v2h-4v4h-2v-4h-4v-2z" fill="#9ca3af" />

              {/* Speed Lines */}
              <line x1="45" y1="90" x2="65" y2="90" stroke="#374151" strokeWidth="2.5" strokeLinecap="round" />
              <line x1="55" y1="102" x2="70" y2="102" stroke="#374151" strokeWidth="2.5" strokeLinecap="round" />
              <line x1="50" y1="114" x2="62" y2="114" stroke="#9ca3af" strokeWidth="2" strokeLinecap="round" />

              {/* Cart Frame */}
              <path d="M57 90h15l15 45h35l14-30H79" stroke="#374151" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
              
              {/* Cart Grid */}
              <line x1="88" y1="95" x2="88" y2="135" stroke="#f3f4f6" strokeWidth="2" />
              <line x1="102" y1="95" x2="102" y2="135" stroke="#f3f4f6" strokeWidth="2" />
              <line x1="116" y1="95" x2="116" y2="135" stroke="#f3f4f6" strokeWidth="2" />
              <line x1="82" y1="105" x2="124" y2="105" stroke="#f3f4f6" strokeWidth="2" />
              <line x1="85" y1="120" x2="128" y2="120" stroke="#f3f4f6" strokeWidth="2" />

              {/* Wheels */}
              <circle cx="86" cy="144" r="9" fill="#fecaca" stroke="#374151" strokeWidth="2" />
              <circle cx="86" cy="144" r="3" fill="#374151" />
              <circle cx="120" cy="144" r="9" fill="#fecaca" stroke="#374151" strokeWidth="2" />
              <circle cx="120" cy="144" r="3" fill="#374151" />

              {/* Plus Badge */}
              <circle cx="132" cy="94" r="13" fill="#bfdbfe" />
              <path d="M129 94h6M132 91v6" stroke="white" strokeWidth="2" strokeLinecap="round" />
            </svg>

            <h2 className="text-[16px] font-black text-slate-800 tracking-tight">
              {t('cart.empty')}
            </h2>
            <p className="text-[13px] text-slate-400 font-bold mt-1.5 mb-8">
              {t('cart.emptySubtitle')}
            </p>
            
            {/* Action Button */}
            <Link to={shopNowLink} className={`inline-block ${primaryBg} text-white px-12 py-3 rounded-full font-black uppercase text-[12px] shadow-md tracking-wider active:scale-95 transition-transform`}>
              {t('cart.shopNow')}
            </Link>
          </div>
        ) : (
          <div className="space-y-4 md:grid md:grid-cols-3 md:gap-8 md:space-y-0 md:max-w-6xl md:mx-auto md:px-4 md:py-6">
            {/* Left Column (Items & Address) */}
            <div className="md:col-span-2 space-y-4">
              {/* Delivery Address Card */}
              <div className="bg-white rounded-[24px] p-4 flex items-center justify-between border border-slate-100/50 shadow-[0_4px_16px_rgba(0,0,0,0.01)]">
                <div className="flex-1 min-w-0 pr-4">
                  <p className="text-[11px] font-black text-slate-800 uppercase tracking-wider">
                    {address ? 'Deliver to Home' : 'Delivery Address'}
                  </p>
                  <p className="text-[12px] text-slate-500 font-medium mt-1 leading-normal">
                    {address ? `${address.name} | ${address.address} | Phone: ${address.phone}` : 'Please login and add an address to proceed.'}
                  </p>
                </div>
                {address ? (
                  <button 
                    onClick={() => {
                      setAddrName(address.name || '');
                      setAddrPhone(address.phone || '');
                      setAddrDetails(address.address || '');
                      setShowAddressModal(true);
                    }}
                    className={`${primaryText} text-[11px] font-black uppercase tracking-wider border border-slate-100 hover:bg-slate-50 px-4 py-2 rounded-full active:scale-95 transition-transform`}
                  >
                    Change
                  </button>
                ) : (
                  isAuthenticated && (
                    <button 
                      onClick={() => setShowAddressModal(true)}
                      className={`${primaryText} text-[11px] font-black uppercase tracking-wider border border-slate-150 hover:bg-slate-50 px-4 py-2 rounded-full active:scale-95 transition-transform`}
                    >
                      Add Address
                    </button>
                  )
                )}
              </div>

              {/* Populated Items Card */}
              <div className="bg-white rounded-[28px] p-4 shadow-[0_4px_20px_rgba(0,0,0,0.01)] border border-slate-100/50 space-y-5">
                {cartItems.map((item, idx) => (
                  <div key={item.cartId} className="flex flex-col">
                    {idx > 0 && <div className="h-[1px] bg-slate-100 mb-5" />}
                    <div className="flex gap-4 items-center relative">
                      {/* Item Image Box */}
                      <div className="w-[84px] h-[84px] rounded-[18px] bg-slate-50 border border-slate-100 flex items-center justify-center p-2 flex-shrink-0">
                        <img src={item.image} alt={item.name} className="w-full h-full object-contain mix-blend-multiply" />
                      </div>

                      {/* Item Details */}
                      <div className="flex-1 min-w-0 pr-6">
                        <h3 className="text-[13.5px] font-black text-slate-800 truncate leading-snug">{item.name}</h3>
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-wider mt-0.5">{item.brand || 'Premium Brand'}</p>
                        <p className="text-[15px] font-black text-slate-900 mt-1">{formatPrice(item.price)}</p>
                        
                        {/* Quantity Pill Capsule */}
                        <div className="flex items-center gap-3 border border-slate-150 rounded-full px-2.5 py-1 w-fit mt-2 bg-white select-none">
                          <button 
                            onClick={() => updateQuantity(item.cartId, -1)}
                            className="text-slate-400 hover:text-slate-700 active:scale-90 transition-transform font-bold text-[14px] px-1"
                          >
                            —
                          </button>
                          <span className="text-[11px] font-black text-slate-800 min-w-[12px] text-center">
                            {item.qty || 1}
                          </span>
                          <button 
                            onClick={() => updateQuantity(item.cartId, 1)}
                            className={`${primaryBg} text-white rounded-full w-5 h-5 flex items-center justify-center active:scale-90 transition-transform font-black text-[12px] leading-none`}
                          >
                            +
                          </button>
                        </div>
                      </div>

                      {/* Delete Action */}
                      <button 
                        onClick={() => handleRemove(item.cartId)}
                        className="absolute right-0 top-1/2 -translate-y-1/2 text-rose-600 hover:text-rose-800 p-2 rounded-full hover:bg-rose-50/50 active:scale-90 transition-transform"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Right Column (Summary & Desktop Action) */}
            <div className="md:col-span-1 space-y-4">
              {/* Pricing Summary Card */}
              <div className="bg-white rounded-[28px] p-5 shadow-[0_4px_20px_rgba(0,0,0,0.01)] border border-slate-100/50 space-y-3.5">
                <div className="flex justify-between items-center text-[13px] text-slate-500 font-bold">
                  <span>{t('cart.subtotal')}</span>
                  <span className="text-slate-800 font-black">{formatPrice(totalPrice)}</span>
                </div>
                <div className="flex justify-between items-center text-[13px] text-slate-500 font-bold">
                  <span>{t('cart.shippingAndTax')}</span>
                  <span className="text-slate-800 font-black">
                    {shippingCost === 0 ? t('cart.free') : formatPrice(shippingCost)}
                  </span>
                </div>
                
                <div className="border-t border-dashed border-slate-200 my-2" />

                <div className="flex justify-between items-center text-[15px] font-black text-slate-800">
                  <span>{t('cart.total')}</span>
                  <span className="text-[18px] text-slate-900">{formatPrice(totalPrice + shippingCost)}</span>
                </div>
              </div>

              {/* Desktop Checkout button */}
              {!isAuthenticated ? (
                <button 
                  onClick={() => navigate('/login', { state: { from: '/cart' } })}
                  className={`hidden md:flex w-full ${primaryBg} text-white font-black py-4 rounded-full active:scale-[0.98] transition-all items-center justify-center text-[14px] shadow-md cursor-pointer`}
                >
                  Login to Proceed
                </button>
              ) : !address ? (
                <button 
                  onClick={() => setShowAddressModal(true)}
                  className={`hidden md:flex w-full ${primaryBg} text-white font-black py-4 rounded-full active:scale-[0.98] transition-all items-center justify-center text-[14px] shadow-md cursor-pointer`}
                >
                  Add Address
                </button>
              ) : (
                <button 
                  onClick={() => navigate('/vendor/checkout', { state: { product: cartItems[0] } })}
                  className={`hidden md:flex w-full ${primaryBg} text-white font-black py-4 rounded-full active:scale-[0.98] transition-all items-center justify-center text-[14px] shadow-md cursor-pointer`}
                >
                  Proceed to Checkout
                </button>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Fixed Bottom Action Bar (Mobile Only) */}
      {cartItems.length > 0 && (
        <div className="fixed bottom-3 left-4 right-4 bg-white/95 backdrop-blur-md border border-slate-100 px-5 py-3.5 flex items-center justify-between z-50 shadow-[0_10px_30px_rgba(8,66,36,0.08)] rounded-[24px] md:hidden">
          <div className="flex flex-col pr-2">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-wider">{t('cart.totalAmount')}</span>
            <span className="text-[18px] font-black text-slate-905 leading-none mt-1">{formatPrice(totalPrice + shippingCost)}</span>
          </div>
          {!isAuthenticated ? (
            <button 
              onClick={() => navigate('/login', { state: { from: '/cart' } })}
              className={`${primaryBg} text-white rounded-full px-6 py-3.5 font-black uppercase text-[11px] tracking-wider shadow-[0_4px_16px_rgba(8,66,36,0.22)] active:scale-95 transition-transform`}
            >
              Login to Proceed
            </button>
          ) : !address ? (
            <button 
              onClick={() => setShowAddressModal(true)}
              className={`${primaryBg} text-white rounded-full px-6 py-3.5 font-black uppercase text-[11px] tracking-wider shadow-[0_4px_16px_rgba(8,66,36,0.22)] active:scale-95 transition-transform`}
            >
              Add Address
            </button>
          ) : (
            <button 
              onClick={() => navigate('/vendor/checkout', { state: { product: cartItems[0] } })}
              className={`${primaryBg} text-white rounded-full px-6 py-3.5 font-black uppercase text-[11px] tracking-wider shadow-[0_4px_16px_rgba(8,66,36,0.22)] active:scale-95 transition-transform`}
            >
              Proceed to Checkout
            </button>
          )}
        </div>
      )}

      {/* Address Form Modal */}
      {showAddressModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[1000] flex items-center justify-center p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-[32px] w-full max-w-[400px] p-6 shadow-2xl border border-slate-100/50 relative transform animate-in zoom-in-95 duration-200">
            <button 
              onClick={() => setShowAddressModal(false)}
              className="absolute right-6 top-6 text-slate-400 hover:text-slate-700 p-1.5 rounded-full hover:bg-slate-100 transition-colors"
            >
              <X size={20} />
            </button>
            <h3 className="text-[20px] font-black text-slate-800 tracking-tight mb-5">
              Add Delivery Address
            </h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const newAddress = { name: addrName, phone: addrPhone, address: addrDetails };
              localStorage.setItem('cartAddress', JSON.stringify(newAddress));
              setAddress(newAddress);
              setShowAddressModal(false);
            }} className="space-y-4">
              <div>
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-wider mb-1">Receiver's Name</label>
                <input 
                  type="text" 
                  value={addrName} 
                  onChange={(e) => setAddrName(e.target.value)} 
                  placeholder="e.g. Harsh Pandey"
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-[14px] font-semibold text-slate-800 placeholder-slate-400 focus:outline-none focus:border-emerald-600 focus:ring-1 focus:ring-emerald-600 transition-all"
                  required
                />
              </div>
              <div>
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-wider mb-1">Phone Number</label>
                <input 
                  type="tel" 
                  value={addrPhone} 
                  onChange={(e) => setAddrPhone(e.target.value)} 
                  placeholder="e.g. 9876543210"
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-[14px] font-semibold text-slate-800 placeholder-slate-400 focus:outline-none focus:border-emerald-600 focus:ring-1 focus:ring-emerald-600 transition-all"
                  required
                />
              </div>
              <div>
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-wider mb-1">Full Address</label>
                <textarea 
                  value={addrDetails} 
                  onChange={(e) => setAddrDetails(e.target.value)} 
                  placeholder="Street, Landmark, City, Pincode"
                  rows="3"
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-[14px] font-semibold text-slate-800 placeholder-slate-400 focus:outline-none focus:border-emerald-600 focus:ring-1 focus:ring-emerald-600 transition-all resize-none"
                  required
                />
              </div>
              <button 
                type="submit"
                className={`w-full py-4 mt-2 ${primaryBg} text-white font-black rounded-2xl text-[13px] uppercase tracking-wider shadow-md hover:shadow-lg transition-all active:scale-[0.98] cursor-pointer`}
              >
                Save & Continue
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Safe Payments Footer */}
      <div className="mt-8 px-6 py-6 flex flex-col items-center gap-3 text-slate-400/80">
        <div className="flex items-center gap-2">
          <ShieldCheck size={18} className={`${primaryText}/70`} />
          <span className="text-[11px] font-black uppercase tracking-wider">{t('cart.safePayments')}</span>
        </div>
        <p className="text-[10px] text-center leading-relaxed font-bold">
          {t('cart.paymentsSubtitle')}
        </p>
      </div>
    </div>
  );
};

export default Cart;

import React, { useState, useEffect, useMemo } from 'react';
import { useSearchParams, Link } from 'react-router-dom';
import { 
  Heart, 
  Star, 
  ChevronDown, 
  SlidersHorizontal, 
  Search,
  ShoppingCart,
  ArrowLeft,
  LayoutGrid,
  Menu,
  MapPin,
  Bell
} from 'lucide-react';

import JewelleryImg from '../../../assets/products/product12.jpg';
import MakeupHero from '../../../assets/products/product08.jpg';
import SamsungS24 from '../../../assets/products/product01.jpg';
import EarbudsDeal from '../../../assets/products/product03.jpg';

// Import Beauty/Jewellery assets
import BeautyJewel1 from '../../../assets/Beauty/BeautyJewel1.jpg';
import BeautyJewel2 from '../../../assets/Beauty/BeautyJewel2.jpg';
import BeautyJewel3 from '../../../assets/Beauty/BeautyJewel3.jpg';
import BeautyJewel4 from '../../../assets/Beauty/BeautyJewel4.jpg';
import BeautyJewel5 from '../../../assets/Beauty/BeautyJewel5.jpg';
import BeautyJewel6 from '../../../assets/Beauty/BeautyJewel6.jpg';

const CornerFlower = () => (
  <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" className="w-[10px] h-[10px] md:w-[14px] md:h-[14px] opacity-85 select-none pointer-events-none">
    {/* Green leaves/petals */}
    <path d="M12 2C13 4.5 13 4.5 12 7C11 4.5 11 4.5 12 2Z" fill="#3E5A44" />
    <path d="M12 22C13 19.5 13 19.5 12 17C11 19.5 11 19.5 12 22Z" fill="#3E5A44" />
    <path d="M2 12C4.5 13 4.5 13 7 12C4.5 11 4.5 11 2 12Z" fill="#3E5A44" />
    <path d="M22 12C19.5 13 19.5 13 17 12C19.5 11 19.5 11 22 12Z" fill="#3E5A44" />
    {/* Orange petals */}
    <circle cx="12" cy="8.5" r="2.2" fill="#E67E22" />
