  { id: 7, name: 'Cotton Kurti Set', category: 'Fashion', price: '₹1,299', stock: 0, status: 'Out of Stock', approval: 'Rejected', image: '', vendor: 'Fashion Hub' },
  { id: 8, name: 'Bluetooth Speaker', category: 'Electronics', price: '₹2,499', stock: 5, status: 'Low Stock', approval: 'Approved', image: '', vendor: 'Elite Electronics' },
];

const Products = () => {
  const [activeTab, setActiveTab] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const tabs = ['All', 'Approved', 'Pending', 'Rejected', 'In Stock', 'Low Stock', 'Out of Stock'];

  const filteredProducts = useMemo(() => {
    return PRODUCTS.filter(p => {
      const matchesTab = activeTab === 'All' || p.status === activeTab || p.approval === activeTab;
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           p.category.toLowerCase().includes(searchQuery.toLowerCase()) ||
                           p.vendor.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesTab && matchesSearch;
    });
  }, [activeTab, searchQuery]);

  const totalPages = Math.ceil(filteredProducts.length / itemsPerPage);
  const paginatedProducts = filteredProducts.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  const stats = [
    { label: 'Total Products', value: PRODUCTS.length.toString(), icon: Package, color: 'text-blue-500', bg: 'bg-blue-50' },
    { label: 'Pending Approval', value: PRODUCTS.filter(p => p.approval === 'Pending').length.toString(), icon: Clock, color: 'text-amber-500', bg: 'bg-amber-50' },
    { label: 'Out of Stock', value: PRODUCTS.filter(p => p.status === 'Out of Stock').length.toString(), icon: AlertCircle, color: 'text-red-500', bg: 'bg-red-50' },
    { label: 'Active Listings', value: PRODUCTS.filter(p => p.approval === 'Approved' && p.status !== 'Out of Stock').length.toString(), icon: CheckCircle2, color: 'text-green-500', bg: 'bg-green-50' },
  ];

  return (
    <div className="space-y-6 pb-10 animate-in fade-in duration-700">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl lg:text-4xl font-semibold text-slate-900 tracking-tight font-montserrat uppercase">Product Management</h1>
          <p className="text-slate-500 text-sm sm:text-base font-medium mt-1 font-raleway">Manage your inventory, pricing, approval status, and stock levels.</p>
        </div>
        <div className="flex gap-3 w-full sm:w-auto">
          <button className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-5 py-2.5 bg-white border border-slate-200 text-slate-700 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-slate-50 transition-all shadow-sm">
            <Download size={16} />
            Export
          </button>
          <button className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-6 py-3 bg-blue-500 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-lg shadow-blue-100 hover:scale-105 active:scale-95 transition-all">
            <Plus size={16} /> Add Product
          </button>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {stats.map((stat, i) => (
          <motion.div
            key={i}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: i * 0.05 }}
            className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-4 hover:shadow-md transition-all group"
          >
            <div className={`w-11 h-11 ${stat.bg} ${stat.color} rounded-xl flex items-center justify-center shadow-inner group-hover:scale-110 transition-transform`}>
              <stat.icon size={22} />
            </div>
            <div>
              <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1.5">{stat.label}</p>
              <p className="text-xl font-black text-slate-900 font-roboto leading-none">{stat.value}</p>
            </div>
          </motion.div>
        ))}
      </div>

      {/* Table Card */}
      <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
        {/* Tabs & Search */}
        <div className="p-6 border-b border-slate-50 space-y-4">
          <div className="flex flex-wrap gap-2">
            {tabs.map(tab => (
              <button
                key={tab}
                onClick={() => { setActiveTab(tab); setCurrentPage(1); }}
                className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                  activeTab === tab 
                  ? 'bg-blue-500 text-white shadow-lg shadow-blue-100' 
                  : 'bg-slate-50 text-slate-400 hover:bg-slate-100'
                }`}
              >
                {tab}
              </button>
            ))}
          </div>
          <div className="flex flex-col sm:flex-row gap-4">
            <SearchInput 
              type="text" 
              placeholder="Search by name, category, vendor..."
              value={searchQuery}
              onChange={(e) => { setSearchQuery(e.target.value); setCurrentPage(1); }}
            />
            <button className="h-[52px] px-6 bg-slate-50 border border-slate-100 rounded-xl text-slate-400 hover:text-slate-900 transition-all shadow-sm flex items-center justify-center gap-2 font-black text-[10px] uppercase tracking-widest w-full sm:w-auto">
              <Filter size={16} />
              Filters
            </button>
          </div>
        </div>

        {/* Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                <th className="px-6 py-4">Product</th>
                <th className="px-6 py-4">Category</th>
                <th className="px-6 py-4">Price</th>
                <th className="px-6 py-4">Stock</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4">Approval</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50 text-sm">
              <AnimatePresence>
                {paginatedProducts.length > 0 ? paginatedProducts.map((product, i) => (
                  <motion.tr
                    key={product.id}
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    transition={{ delay: i * 0.03 }}
                    className="group hover:bg-blue-50/30 transition-colors"
                  >
                    <td className="px-6 py-5">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-slate-50 rounded-xl overflow-hidden border border-slate-100 flex items-center justify-center flex-shrink-0">
                          {product.image ? (
                            <img src={product.image} alt={product.name} className="w-full h-full object-contain p-1" />
                          ) : (
                            <Package size={20} className="text-slate-300" />
                          )}
                        </div>
                        <div>
                          <p className="font-bold text-slate-900 font-montserrat leading-tight">{product.name}</p>
                          <p className="text-[10px] text-slate-400 font-bold mt-1">SKU: SH-902{product.id} • {product.vendor}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-5">
                      <span className="px-2.5 py-1 bg-slate-50 text-slate-600 rounded-lg text-[10px] font-black border border-slate-100 uppercase tracking-wider">
                        {product.category}
                      </span>
                    </td>
                    <td className="px-6 py-5 font-black text-slate-900 font-roboto">{product.price}</td>
                    <td className="px-6 py-5">
                      <span className={`text-sm font-bold ${product.stock === 0 ? 'text-red-500' : product.stock < 15 ? 'text-amber-500' : 'text-slate-600'}`}>
                        {product.stock} units
                      </span>
                    </td>
                    <td className="px-6 py-5">
                      <StatusBadge status={product.status} />
                    </td>
                    <td className="px-6 py-5">
                      <StatusBadge status={product.approval} />
                    </td>
                    <td className="px-6 py-5 text-right">
                      <div className="flex items-center justify-end gap-1.5">
                        <button className="p-2 bg-slate-50 text-slate-400 rounded-lg hover:bg-blue-50 hover:text-blue-500 transition-all" title="View" aria-label="View product">
                          <Eye size={16} />
                        </button>
                        <button className="p-2 bg-slate-50 text-slate-400 rounded-lg hover:bg-indigo-50 hover:text-indigo-500 transition-all" title="Edit" aria-label="Edit product">
                          <Edit2 size={16} />
                        </button>
                        <button className="p-2 bg-slate-50 text-slate-400 rounded-lg hover:bg-red-50 hover:text-red-500 transition-all" title="Delete" aria-label="Delete product">
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </td>
                  </motion.tr>
                )) : (
                  <tr>
                    <td colSpan="7" className="px-6 py-20 text-center">
                      <div className="flex flex-col items-center gap-3 text-slate-300">
                        <Package size={48} className="opacity-20" />
                        <p className="text-sm font-bold uppercase tracking-widest">No products found matching your criteria</p>
                      </div>
                    </td>
                  </tr>
                )}
              </AnimatePresence>
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {paginatedProducts.length > 0 && (
          <Pagination
            currentPage={currentPage}
            totalPages={totalPages}
            totalItems={filteredProducts.length}
            itemsPerPage={itemsPerPage}
            onPageChange={setCurrentPage}
          />
        )}
      </div>
    </div>
  );
};

export default Products;

import React from 'react';
import { Package, Download, AlertCircle, CheckCircle2, AlertTriangle } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { motion } from 'framer-motion';
import { INVENTORY_REPORT_DATA } from '../../constants/dummyData';
import { StatusBadge } from '../../components/ui';

const InventoryReport = () => {
  const totalProducts = INVENTORY_REPORT_DATA.reduce((sum, c) => sum + c.totalProducts, 0);
  const totalOOS = INVENTORY_REPORT_DATA.reduce((sum, c) => sum + c.outOfStock, 0);
  const totalLow = INVENTORY_REPORT_DATA.reduce((sum, c) => sum + c.lowStock, 0);

  const stats = [
    { label: 'Total Products', value: totalProducts.toString(), icon: Package, color: 'text-blue-500', bg: 'bg-blue-50' },
    { label: 'In Stock', value: INVENTORY_REPORT_DATA.reduce((s, c) => s + c.inStock, 0).toString(), icon: CheckCircle2, color: 'text-green-500', bg: 'bg-green-50' },
    { label: 'Low Stock', value: totalLow.toString(), icon: AlertTriangle, color: 'text-amber-500', bg: 'bg-amber-50' },
    { label: 'Out of Stock', value: totalOOS.toString(), icon: AlertCircle, color: 'text-red-500', bg: 'bg-red-50' },
  ];

  return (
    <div className="space-y-6 pb-10 animate-in fade-in duration-700">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl lg:text-4xl font-semibold text-slate-900 tracking-tight font-montserrat uppercase">Inventory Report</h1>
          <p className="text-slate-500 text-sm sm:text-base font-medium mt-1 font-raleway">Stock levels, category distribution, and inventory health overview.</p>
        </div>
        <button className="w-full sm:w-auto flex items-center justify-center gap-2 px-5 py-2.5 bg-blue-500 text-white rounded-xl text-[11px] font-black uppercase tracking-widest shadow-lg shadow-blue-100 hover:scale-105 active:scale-95 transition-all">
          <Download size={16} /> Export
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {stats.map((stat, i) => (
          <motion.div key={i} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
            className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-4">
            <div className={`w-11 h-11 ${stat.bg} ${stat.color} rounded-xl flex items-center justify-center shadow-inner`}><stat.icon size={22} /></div>
            <div><p className="text-[9px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1.5">{stat.label}</p><p className="text-xl font-black text-slate-900 font-roboto leading-none">{stat.value}</p></div>
          </motion.div>
        ))}
      </div>

      <div className="bg-white rounded-3xl border border-slate-100 shadow-sm p-8">
        <h3 className="text-lg font-bold text-slate-900 uppercase tracking-tight font-montserrat mb-8">Stock Distribution by Category</h3>
        <div className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={INVENTORY_REPORT_DATA}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="category" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 700}} dy={10} />
              <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 700}} dx={-10} />
              <Tooltip contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontWeight: 'bold'}} />
              <Legend wrapperStyle={{fontSize: '10px', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.1em'}} />
              <Bar dataKey="inStock" name="In Stock" fill="#10b981" radius={[4, 4, 0, 0]} barSize={22} />
              <Bar dataKey="lowStock" name="Low Stock" fill="#f59e0b" radius={[4, 4, 0, 0]} barSize={22} />
              <Bar dataKey="outOfStock" name="Out of Stock" fill="#ef4444" radius={[4, 4, 0, 0]} barSize={22} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-slate-50"><h3 className="text-lg font-bold text-slate-900 uppercase tracking-tight font-montserrat">Category Breakdown</h3></div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead><tr className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-widest"><th className="px-6 py-4">Category</th><th className="px-6 py-4">Total</th><th className="px-6 py-4">In Stock</th><th className="px-6 py-4">Low Stock</th><th className="px-6 py-4">Out of Stock</th><th className="px-6 py-4">Health</th></tr></thead>
            <tbody className="divide-y divide-slate-50 text-sm">
              {INVENTORY_REPORT_DATA.map((row, i) => {
                const healthPct = Math.round((row.inStock / row.totalProducts) * 100);
                return (
                  <tr key={i} className="hover:bg-blue-50/30 transition-colors">
                    <td className="px-6 py-5 font-bold text-slate-900 font-montserrat">{row.category}</td>
                    <td className="px-6 py-5 font-black text-slate-900 font-roboto">{row.totalProducts}</td>
                    <td className="px-6 py-5 font-bold text-green-600">{row.inStock}</td>
                    <td className="px-6 py-5 font-bold text-amber-500">{row.lowStock}</td>
                    <td className="px-6 py-5 font-bold text-red-500">{row.outOfStock}</td>
                    <td className="px-6 py-5">
                      <div className="flex items-center gap-3">
                        <div className="flex-1 h-2 bg-slate-100 rounded-full overflow-hidden max-w-[100px]">
                          <div className={`h-full rounded-full ${healthPct > 80 ? 'bg-green-500' : healthPct > 60 ? 'bg-amber-500' : 'bg-red-500'}`} style={{ width: `${healthPct}%` }} />
                        </div>
                        <span className="text-[10px] font-black text-slate-500">{healthPct}%</span>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default InventoryReport;

import SearchInput from '../../../../shared/components/SearchInput';
import React, { useState } from 'react';
import { 
  Terminal, Search, Filter, Calendar, 
  Download, Clock, Shield, Key, 
  Database, UserCheck, AlertTriangle
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { MOCK_AUDIT_LOGS, MOCK_LOGIN_HISTORY } from '../../constants/dummyData';
import { Pagination } from '../../components/ui';

const AuditLogs = () => {
  const [activeTab, setActiveTab] = useState('Activity'); // 'Activity' | 'Logins'
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const logs = activeTab === 'Activity' ? MOCK_AUDIT_LOGS : MOCK_LOGIN_HISTORY;

  const filteredLogs = logs.filter(log => {
    const q = searchQuery.toLowerCase();
    if (activeTab === 'Activity') {
      return log.admin.toLowerCase().includes(q) || 
             log.action.toLowerCase().includes(q) || 
             log.target.toLowerCase().includes(q) ||
             log.ip.includes(q);
    } else {
      return log.admin.toLowerCase().includes(q) || 
             log.ip.includes(q) || 
             log.device.toLowerCase().includes(q) || 
             log.location.toLowerCase().includes(q);
    }
  });

  const totalPages = Math.ceil(filteredLogs.length / itemsPerPage);
  const paginatedLogs = filteredLogs.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  const getLogIcon = (type) => {
    switch (type) {
      case 'auth': return <Key size={14} className="text-blue-500" />;
      case 'user': return <UserCheck size={14} className="text-green-500" />;
      case 'product': return <Database size={14} className="text-indigo-500" />;
      case 'settings': return <Shield size={14} className="text-purple-500" />;
      default: return <Clock size={14} className="text-slate-500" />;
    }
  };

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-700">
      {/* Header */}
      <div className="flex justify-between items-end">
        <div>
          <h1 className="text-4xl font-semibold text-slate-900 tracking-tight font-montserrat uppercase">Audit Logs</h1>
          <p className="text-slate-500 font-medium mt-1 font-raleway">Monitor administrator activities, security events, and login history.</p>
        </div>
        <button className="flex items-center gap-2 px-5 py-2.5 bg-white border border-slate-200 text-slate-700 rounded-xl text-sm font-bold hover:bg-slate-50 transition-all shadow-sm">
          <Download size={16} />
          Export Logs
        </button>
      </div>

      {/* Tabs / Filters Panel */}
      <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-slate-50 space-y-4">
          <div className="flex gap-2">
            {['Activity', 'Logins'].map(tab => (
              <button
                key={tab}
                onClick={() => { setActiveTab(tab); setCurrentPage(1); setSearchQuery(''); }}
                className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                  activeTab === tab 
                  ? 'bg-slate-900 text-white shadow-lg' 
                  : 'bg-slate-50 text-slate-400 hover:bg-slate-100'
                }`}
              >
                {tab === 'Activity' ? 'Admin Actions' : 'Login History'}
              </button>
            ))}
          </div>

          <div className="flex gap-4">
            <SearchInput 
              type="text" 
              placeholder="Search audit trail..."
              value={searchQuery}
              onChange={(e) => { setSearchQuery(e.target.value); setCurrentPage(1); }}
            />
          </div>
        </div>

        {/* Content Table */}
        <div className="overflow-x-auto">
          {activeTab === 'Activity' ? (
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                  <th className="px-6 py-4">Timestamp</th>
                  <th className="px-6 py-4">Administrator</th>
                  <th className="px-6 py-4">Action</th>
                  <th className="px-6 py-4">Target Resource</th>
                  <th className="px-6 py-4">IP Address</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50 text-sm">
                <AnimatePresence>
                  {paginatedLogs.map((log) => (
                    <motion.tr key={log.id} initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="hover:bg-slate-50/30 transition-colors">
                      <td className="px-6 py-4 text-[11px] font-bold text-slate-500">{log.timestamp}</td>
                      <td className="px-6 py-4 font-bold text-slate-900">{log.admin}</td>
                      <td className="px-6 py-4">
                        <span className="flex items-center gap-2 font-semibold text-slate-700">
                          <span className="p-1 bg-slate-100 rounded">
                            {getLogIcon(log.type)}
                          </span>
                          {log.action}
                        </span>
                      </td>
                      <td className="px-6 py-4 font-mono text-xs text-slate-600">{log.target}</td>
                      <td className="px-6 py-4 font-mono text-xs text-slate-500">{log.ip}</td>
                    </motion.tr>
                  ))}
                </AnimatePresence>
              </tbody>
            </table>
          ) : (
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                  <th className="px-6 py-4">Timestamp</th>
                  <th className="px-6 py-4">Administrator</th>
                  <th className="px-6 py-4">Location</th>
                  <th className="px-6 py-4">Browser / Device</th>
                  <th className="px-6 py-4">IP Address</th>
                  <th className="px-6 py-4">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50 text-sm">
                <AnimatePresence>
                  {paginatedLogs.map((log) => (
                    <motion.tr key={log.id} initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="hover:bg-slate-50/30 transition-colors">
                      <td className="px-6 py-4 text-[11px] font-bold text-slate-500">{log.timestamp}</td>
                      <td className="px-6 py-4 font-bold text-slate-900">{log.admin}</td>
                      <td className="px-6 py-4 font-bold text-slate-600">{log.location}</td>
                      <td className="px-6 py-4 text-xs text-slate-600">{log.device}</td>
                      <td className="px-6 py-4 font-mono text-xs text-slate-500">{log.ip}</td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-1 rounded text-[9px] font-black uppercase tracking-widest ${
                          log.status === 'Success' ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'
                        }`}>
                          {log.status}
                        </span>
                      </td>
                    </motion.tr>
                  ))}
                </AnimatePresence>
              </tbody>
            </table>
          )}
        </div>

        {/* Pagination */}
        {paginatedLogs.length > 0 && (
          <Pagination 
            currentPage={currentPage}
            totalPages={totalPages}
            totalItems={filteredLogs.length}
            itemsPerPage={itemsPerPage}
            onPageChange={setCurrentPage}
          />
        )}
      </div>
    </div>
  );
};

export default AuditLogs;

import SearchInput from '../../../shared/components/SearchInput';
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Users as UsersIcon, Search, Filter, Mail, 
  Phone, MapPin, Calendar, MoreVertical,
  CheckCircle2, XCircle, Clock, ShieldCheck,
  Download, UserPlus, Star, Edit2, ShieldAlert, Eye
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const MOCK_USERS = [
  { id: 'USR001', name: 'Rahul Sharma', email: 'rahul@example.com', phone: '+91 98765 43210', joined: '2026-05-01', totalSpent: '₹45,200', orders: 12, status: 'Active' },
  { id: 'USR002', name: 'Priyanka Das', email: 'priyanka@example.com', phone: '+91 98765 43211', joined: '2026-04-28', totalSpent: '₹12,500', orders: 4, status: 'Active' },
  { id: 'USR003', name: 'Amit Verma', email: 'amit@example.com', phone: '+91 98765 43212', joined: '2026-04-20', totalSpent: '₹89,400', orders: 28, status: 'VIP' },
  { id: 'USR004', name: 'Sneha Kapur', email: 'sneha@example.com', phone: '+91 98765 43213', joined: '2026-04-15', totalSpent: '₹0', orders: 0, status: 'Inactive' },
  { id: 'USR005', name: 'Vikram Singh', email: 'vikram@example.com', phone: '+91 98765 43214', joined: '2026-04-10', totalSpent: '₹1,56,000', orders: 45, status: 'VIP' },
];

const Users = () => {
  const navigate = useNavigate();
  const [searchQuery, setSearchQuery] = useState('');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [usersList, setUsersList] = useState(MOCK_USERS);
  const [filterStatus, setFilterStatus] = useState('All');
  const [isFilterOpen, setIsFilterOpen] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    status: 'Active'
  });

  const filteredUsers = usersList.filter(user => {
    const matchesSearch = user.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          user.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          user.phone.toLowerCase().includes(searchQuery.toLowerCase());
    
    const matchesStatus = filterStatus === 'All' || user.status === filterStatus;
    
    return matchesSearch && matchesStatus;
  });

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSaveCustomer = () => {
    if (!formData.name || !formData.email) return;

    const newUser = {
      id: `USR${String(usersList.length + 1).padStart(3, '0')}`,
      name: formData.name,
      email: formData.email,
      phone: formData.phone || '+91 00000 00000',
      joined: new Date().toISOString().split('T')[0],
      totalSpent: '₹0',
      orders: 0,
      status: formData.status
    };

    setUsersList([newUser, ...usersList]);
    setIsAddModalOpen(false);
    setFormData({ name: '', email: '', phone: '', status: 'Active' });
  };

  const [activeMenu, setActiveMenu] = useState(null);

  const toggleMenu = (e, userId) => {
    e.stopPropagation();
    setActiveMenu(activeMenu === userId ? null : userId);
  };

  const handleAction = (e, action, user) => {
    e.stopPropagation();
    console.log(`${action} user: ${user.name}`);
    if (action === 'view') navigate(`/admin/users/${user.id}`);
    setActiveMenu(null);
  };

  const handleExport = () => {
    const headers = ['ID', 'Name', 'Email', 'Phone', 'Joined', 'Spent', 'Orders', 'Status'];
    const csvContent = [
      headers.join(','),
      ...usersList.map(u => `${u.id},"${u.name}",${u.email},${u.phone},${u.joined},"${u.totalSpent}",${u.orders},${u.status}`)
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `customers_export_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 pb-10 animate-in fade-in duration-700 relative">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl lg:text-4xl font-semibold text-slate-900 tracking-tight font-montserrat uppercase">Customer Database</h1>
          <p className="text-slate-500 text-sm sm:text-base font-medium mt-1 font-raleway">Manage platform buyers, review their spending history and account status.</p>
        </div>
        <div className="flex gap-3 w-full sm:w-auto">
          <button 
            onClick={handleExport}
            className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-6 py-3 bg-white border border-slate-200 text-slate-700 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-slate-50 transition-all shadow-sm active:scale-95"
          >
            <Download size={16} />
            Export List
          </button>
          <button 
            onClick={() => setIsAddModalOpen(true)}
            className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-blue-500 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-lg shadow-blue-100 hover:scale-105 active:scale-95 transition-all"
          >
            <UserPlus size={16} />
            Add Customer
          </button>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { label: 'Total Buyers', value: usersList.length.toLocaleString(), icon: UsersIcon, color: 'text-blue-500', bg: 'bg-blue-50' },
          { label: 'Active Now', value: '182', icon: Clock, color: 'text-green-500', bg: 'bg-green-50' },
          { label: 'Avg LTV', value: '₹12,400', icon: Star, color: 'text-amber-500', bg: 'bg-amber-50' },
          { label: 'New This Week', value: '+45', icon: UserPlus, color: 'text-indigo-500', bg: 'bg-indigo-50' },
        ].map((stat, i) => (
          <div key={i} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-4">
            <div className={`w-11 h-11 ${stat.bg} ${stat.color} rounded-xl flex items-center justify-center shadow-inner`}>
              <stat.icon size={22} />
            </div>
            <div>
              <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1.5">{stat.label}</p>
              <p className="text-xl font-black text-slate-900 font-roboto leading-none">{stat.value}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Table */}
      <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden min-h-[400px]">
        <div className="p-6 border-b border-slate-50">
          <div className="flex flex-col sm:flex-row gap-4">
            <SearchInput 
              type="text" 
              placeholder="Search by Name, Email or Phone..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
            <div className="relative w-full sm:w-auto">
              <button 
                onClick={() => setIsFilterOpen(!isFilterOpen)}
                className={`w-full sm:w-auto px-6 h-[52px] border rounded-xl transition-all shadow-sm flex items-center justify-center gap-2 ${isFilterOpen || filterStatus !== 'All' ? 'bg-slate-900 text-white border-slate-900' : 'bg-slate-50 border-slate-100 text-slate-400 hover:text-slate-900'}`}
              >
                <Filter size={18} />
                {filterStatus !== 'All' && <span className="text-[10px] font-black uppercase tracking-widest">{filterStatus}</span>}
              </button>

              <AnimatePresence>
                {isFilterOpen && (
                  <>
                    <div className="fixed inset-0 z-10" onClick={() => setIsFilterOpen(false)} />
                    <motion.div 
                      initial={{ opacity: 0, scale: 0.95, y: -10 }}
                      animate={{ opacity: 1, scale: 1, y: 0 }}
                      exit={{ opacity: 0, scale: 0.95, y: -10 }}
                      className="absolute right-0 top-16 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 z-20 py-3 overflow-hidden"
                    >
                       <p className="px-4 pb-2 mb-2 border-b border-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest">Filter by Status</p>
                       {['All', 'Active', 'VIP', 'Inactive'].map((status) => (
                         <button 
                            key={status}
                            onClick={() => {
                              setFilterStatus(status);
                              setIsFilterOpen(false);
                            }}
                            className={`w-full px-4 py-2.5 text-left text-[10px] font-black uppercase tracking-widest transition-colors flex items-center justify-between ${filterStatus === status ? 'bg-blue-50 text-blue-600' : 'text-slate-600 hover:bg-slate-50'}`}
                         >
                            {status}
                            {filterStatus === status && <CheckCircle2 size={12} />}
                         </button>
                       ))}
                    </motion.div>
                  </>
                )}
              </AnimatePresence>
            </div>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                <th className="px-6 py-4">Customer Details</th>
                <th className="px-6 py-4">Total Spent</th>
                <th className="px-6 py-4">Orders</th>
                <th className="px-6 py-4">Member Since</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50 text-sm">
              {filteredUsers.length > 0 ? filteredUsers.map((user, i) => (
                <tr 
                  key={user.id} 
                  onClick={() => navigate(`/admin/users/${user.id}`)}
                  className="group hover:bg-blue-50/30 cursor-pointer transition-all border-l-4 border-transparent hover:border-blue-500 animate-in fade-in slide-in-from-left-2 duration-300"
                  style={{ animationDelay: `${i * 50}ms` }}
                >
                  <td className="px-6 py-5">
                    <div className="flex items-center gap-4">
                       <div className="w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center font-black text-slate-400 border border-slate-100">
                          {user.name.charAt(0)}
                       </div>
                       <div>
                          <p className="font-bold text-slate-900 font-montserrat leading-tight">{user.name}</p>
                          <p className="text-[10px] text-slate-400 font-bold mt-1">{user.email}</p>
                       </div>
                    </div>
                  </td>
                  <td className="px-6 py-5 font-black text-slate-900 font-roboto">{user.totalSpent}</td>
                  <td className="px-6 py-5">
                     <span className="px-2 py-1 bg-slate-50 text-slate-600 rounded-lg text-[10px] font-black border border-slate-100">
                        {user.orders} Orders
                     </span>
                  </td>
                  <td className="px-6 py-5 text-[11px] font-bold text-slate-500 uppercase tracking-tighter">{user.joined}</td>
                  <td className="px-6 py-5">
                     <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${
                       user.status === 'VIP' ? 'bg-amber-50 text-amber-600 border border-amber-100' : 
                       user.status === 'Active' ? 'bg-green-50 text-green-600 border border-green-100' : 'bg-slate-100 text-slate-400'
                     }`}>
                        {user.status}
                     </span>
                  </td>
                  <td className="px-6 py-5 text-right relative" onClick={(e) => e.stopPropagation()}>
                    <button 
                      onClick={(e) => toggleMenu(e, user.id)}
                      className={`p-2 rounded-lg transition-all ${activeMenu === user.id ? 'bg-slate-900 text-white' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}
                    >
                       <MoreVertical size={16} />
                    </button>

                    <AnimatePresence>
                      {activeMenu === user.id && (
                        <>
                          <div className="fixed inset-0 z-10" onClick={() => setActiveMenu(null)} />
                          <motion.div 
                            initial={{ opacity: 0, scale: 0.95, y: -10 }}
                            animate={{ opacity: 1, scale: 1, y: 0 }}
                            exit={{ opacity: 0, scale: 0.95, y: -10 }}
                            className="absolute right-6 top-14 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 z-20 py-2 overflow-hidden"
                          >
                             <button onClick={(e) => handleAction(e, 'view', user)} className="w-full px-4 py-2.5 flex items-center gap-3 hover:bg-slate-50 text-slate-600 transition-colors">
                                <Eye size={14} className="text-blue-500" />
                                <span className="text-[10px] font-black uppercase tracking-widest">View Profile</span>
                             </button>
                             <button onClick={(e) => handleAction(e, 'edit', user)} className="w-full px-4 py-2.5 flex items-center gap-3 hover:bg-slate-50 text-slate-600 transition-colors">
                                <Edit2 size={14} className="text-indigo-500" />
                                <span className="text-[10px] font-black uppercase tracking-widest">Edit Information</span>
                             </button>
                             <button onClick={(e) => handleAction(e, 'email', user)} className="w-full px-4 py-2.5 flex items-center gap-3 hover:bg-slate-50 text-slate-600 transition-colors">
                                <Mail size={14} className="text-green-500" />
                                <span className="text-[10px] font-black uppercase tracking-widest">Send Email</span>
                             </button>
                             <div className="h-px bg-slate-50 my-1" />
                             <button onClick={(e) => handleAction(e, 'suspend', user)} className="w-full px-4 py-2.5 flex items-center gap-3 hover:bg-red-50 text-red-600 transition-colors">
                                <ShieldAlert size={14} />
                                <span className="text-[10px] font-black uppercase tracking-widest">Suspend Account</span>
                             </button>
                          </motion.div>
                        </>
                      )}
                    </AnimatePresence>
                  </td>
                </tr>
              )) : (
                <tr>
                  <td colSpan="6" className="px-6 py-20 text-center">
                    <div className="flex flex-col items-center gap-3 text-slate-300">
                      <UsersIcon size={48} className="opacity-20" />
                      <p className="text-sm font-bold uppercase tracking-widest">No customers found matching your search</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add Customer Slide-over */}
      <AnimatePresence>
        {isAddModalOpen && (
          <div className="fixed inset-0 z-[100] flex items-center justify-end p-4 bg-slate-900/40 backdrop-blur-sm">
            <motion.div 
              initial={{ x: '100%' }}
              animate={{ x: 0 }}
              exit={{ x: '100%' }}
              className="w-full max-w-lg bg-white h-full rounded-[32px] shadow-2xl p-10 flex flex-col"
            >
              <div className="flex justify-between items-center mb-10">
                <h2 className="text-2xl font-black text-slate-900 font-montserrat uppercase tracking-tight">Add New Customer</h2>
                <button 
                  onClick={() => setIsAddModalOpen(false)} 
                  className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-400 hover:text-slate-900 transition-all active:scale-90 shadow-sm"
                >
                  <XCircle size={24} />
                </button>
              </div>

              <div className="flex-1 space-y-8 overflow-y-auto no-scrollbar pb-10">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Full Name</label>
                  <input 
                    name="name"
                    value={formData.name}
                    onChange={handleInputChange}
                    type="text" 
                    placeholder="e.g. Rahul Sharma" 
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 px-6 text-sm font-black focus:ring-4 focus:ring-blue-50 outline-none transition-all" 
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Email Address</label>
                  <input 
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    type="email" 
                    placeholder="rahul@example.com" 
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 px-6 text-sm font-black focus:ring-4 focus:ring-blue-50 outline-none transition-all" 
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Phone Number</label>
                  <input 
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    type="tel" 
                    placeholder="+91 00000 00000" 
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 px-6 text-sm font-black focus:ring-4 focus:ring-blue-50 outline-none transition-all" 
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Initial Status</label>
                  <select 
                    name="status"
                    value={formData.status}
                    onChange={handleInputChange}
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 px-6 text-sm font-black focus:ring-4 focus:ring-blue-50 outline-none transition-all appearance-none"
                  >
                    <option value="Active">Active</option>
                    <option value="Inactive">Inactive</option>
                    <option value="VIP">VIP</option>
                  </select>
                </div>
                
                <div className="bg-blue-50 p-6 rounded-[24px] border border-blue-100 flex gap-4 items-start">
                   <div className="p-2 bg-white rounded-xl text-blue-500 shadow-sm">
                      <ShieldCheck size={20} />
                   </div>
                   <div>
                      <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Platform Sync</p>
                      <p className="text-[11px] text-blue-400 font-bold mt-1 leading-relaxed uppercase">Adding a customer will automatically trigger a welcome email and sync profile across all storefronts.</p>
                   </div>
                </div>
              </div>

              <div className="pt-8 border-t border-slate-50 flex gap-4">
                <button onClick={() => setIsAddModalOpen(false)} className="flex-1 py-4 bg-slate-50 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-100 transition-all">Cancel</button>
                <button 
                  onClick={handleSaveCustomer}
                  className="flex-1 py-4 bg-blue-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-blue-100 hover:scale-105 active:scale-95 transition-all flex items-center justify-center gap-2"
                >
                   <CheckCircle2 size={16} />
                   Save Customer
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Users;

import SearchInput from '../../../shared/components/SearchInput';
import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { 
  Search, Filter, MoreVertical, ExternalLink, 
  UserCheck, UserX, Ban, MessageSquare, Download
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const VendorList = () => {
  const navigate = useNavigate();
  const { allVendors } = useSelector(state => state.admin);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterStatus, setFilterStatus] = useState('All');

  const filteredVendors = allVendors.filter(v => 
    (filterStatus === 'All' || v.status === filterStatus) &&
    (v.name.toLowerCase().includes(searchQuery.toLowerCase()) || v.owner.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  const StatusBadge = ({ status }) => {
    const colors = {
      Approved: 'bg-green-50 text-green-600',
      Pending: 'bg-amber-50 text-amber-600',
      Suspended: 'bg-red-50 text-red-600',
      Blocked: 'bg-slate-100 text-slate-500'
    };
    return (
      <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${colors[status] || colors.Blocked}`}>
        {status}
      </span>
    );
  };

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight font-montserrat">Vendor Directory</h2>
          <p className="text-slate-400 font-medium text-sm mt-1 font-raleway">Manage and monitor all platform partners.</p>
        </div>
        <div className="flex gap-3 w-full md:w-auto">
          <div className="flex-1 md:w-80">
            <SearchInput 
              type="text" 
              placeholder="Search vendor, email or owner..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <button className="p-3 bg-white border border-slate-200 rounded-2xl text-slate-600 hover:bg-slate-50 transition-all shadow-sm">
            <Filter size={20} />
          </button>
          <button className="px-6 py-3 bg-blue-600 text-white rounded-2xl text-sm font-black uppercase tracking-widest shadow-lg shadow-blue-100 hover:scale-105 active:scale-95 transition-all">
            Add New Vendor
          </button>
        </div>
      </div>

      {/* Stats Summary */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Total Vendors', value: allVendors.length, color: 'text-blue-600', bg: 'bg-blue-50' },
          { label: 'Active', value: allVendors.filter(v => v.status === 'Approved').length, color: 'text-green-600', bg: 'bg-green-50' },
          { label: 'New This Month', value: 12, color: 'text-indigo-600', bg: 'bg-indigo-50' },
          { label: 'Top Performers', value: 8, color: 'text-amber-600', bg: 'bg-amber-50' }
        ].map((stat, i) => (
          <div key={i} className="bg-white p-5 rounded-3xl border border-slate-100 flex flex-col gap-1 shadow-sm">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{stat.label}</span>
            <span className={`text-2xl font-black ${stat.color}`}>{stat.value}</span>
          </div>
        ))}
      </div>

      {/* Table Section */}
      <div className="bg-white rounded-[32px] border border-slate-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100">
                <th className="px-8 py-5 text-[11px] font-black text-slate-400 uppercase tracking-widest">Vendor / ID</th>
                <th className="px-8 py-5 text-[11px] font-black text-slate-400 uppercase tracking-widest">Owner / Contact</th>
                <th className="px-8 py-5 text-[11px] font-black text-slate-400 uppercase tracking-widest">Status</th>
                <th className="px-8 py-5 text-[11px] font-black text-slate-400 uppercase tracking-widest">Revenue</th>
                <th className="px-8 py-5 text-[11px] font-black text-slate-400 uppercase tracking-widest">Joined</th>
                <th className="px-8 py-5 text-[11px] font-black text-slate-400 uppercase tracking-widest text-center">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              <AnimatePresence>
                {filteredVendors.map((vendor, index) => (
                  <motion.tr 
                    key={vendor.id}
                    initial={{ opacity: 0, x: -10 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: index * 0.05 }}
                    onClick={() => navigate(`/admin/vendors/${vendor.id}`)}
                    className="group hover:bg-slate-50/50 transition-colors cursor-pointer"
                  >
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-4">
